INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C1','sci',4,2,'u3',1,'기체가 있음을 아는 방법 — 눈으로 볼 수 없어도 기체가 있다는 것을 다양한 상황에서 알 수 있음 · 기체는 대부분 눈에 보이지 않고, 담는 용기에 따라 모양이 바뀌며, 주어진 공간을 가득 채울 수 있음',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C2','sci',4,2,'u3',1,'숨이를 단서로 기체가 있는 부분 찾기 — 숨이(머리에 풍선 모양 장식)가 있는 위치는 기체를 찾는 단서 · ◯표는 숨이가 아니라 기체가 있는 부분에 함 · 소방대원이 등에 멘 공기통, 풍선, 공기 미끄럼틀 안에 공기가 들어 있음',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C3','sci',4,2,'u3',1,'공기가 들어 있음과 공기가 이동함 — 공·풍선·튜브·공기 미끄럼틀 안에 공기가 들어 있어 팽팽함 · 부채질을 하면 공기가 이동해 바람을 느낌 · 공기 주입기를 통해 공기가 자전거 타이어 안으로 이동함',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C4','sci',4,2,'u3',1,'찾은 것을 친구와 비교하기 — 내가 찾은 모습을 친구와 비교하고, 다르면 그렇게 생각한 까닭을 이야기함 · 물에서 공기 방울이 보글보글 올라오는 모습을 상상해서 찾은 것처럼 그림 밖의 경험도 들어 봄 · 바람이 불 때, 숨을 쉴 때도 공기를 느낌',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C5','sci',4,2,'u3',2,'기체도 무게가 있음 — 쌓기나무 같은 고체, 물 같은 액체처럼 공기와 같은 기체도 무게가 있음 · 눈에 보이지 않는 기체도 무게가 있음',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C6','sci',4,2,'u3',2,'공기를 넣을 때의 무게 변화 — 공기 주입 마개를 끼운 페트병의 무게를 전자저울로 잼 → 마개를 여러 번 눌러 공기를 넣고 다시 잼 → 무게가 늘어남(예 54.0 g → 54.2 g) · 많이 누를수록 공기가 많이 들어가 더 무거움',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C7','sci',4,2,'u3',2,'공기를 뺄 때의 무게 변화 — 감압 용기의 무게를 잼 → 펌프를 여러 번 당겨 공기를 빼냄 → 무게가 줄어듦 · 팽팽한 고무배에서 공기를 빼내면 무게가 줄어듦',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C8','sci',4,2,'u3',2,'무엇의 무게를 재었나 — 전자저울로 잰 것은 용기(페트병·마개·안의 공기를 모두 합한 것)의 무게 · 용기 안에 공기가 많이 들어 있을수록 용기의 무게가 더 무거워짐 · 모양과 크기가 똑같은 두 공기통은 무게를 비교해 공기의 양을 알아냄',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C9','sci',4,2,'u3',2,'무게 실험의 안전 — 실험복·보안경·실험용 장갑을 갖춤 · 공기를 많이 넣은 공기 주입 마개를 열 때 큰 소리가 날 수 있고 마개가 튕겨 나갈 수 있으므로 조심함',ARRAY['[4과15-01] 실험을 통해 기체가 무게가 있음을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C10','sci',4,2,'u3',3,'온도에 따른 기체의 부피 변화 — 기체의 부피는 주변 온도의 영향을 받음 · 따뜻하게 하면(온도가 높아지면) 포일 풍선이 부풀어 오르고 부피가 늘어남 · 차갑게 하면(온도가 낮아지면) 쭈그러들고 부피가 줄어듦',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C11','sci',4,2,'u3',3,'포일 풍선 실험 방법 — 포일 풍선에 공기를 넣고 입구를 잘 닫음(바람이 안으로 들어가 늘어난 것이 아님) → 수조에 넣고 머리 말리개로 따뜻한 바람 → 얼음이 담긴 수조에 넣음 · 정확한 크기보다 부피가 어떻게 변하는지 관찰함',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C12','sci',4,2,'u3',3,'온도 실험의 안전 — 풍선에 공기를 너무 많이 넣어 터지지 않게 함 · 머리 말리개를 피부나 풍선에 가까이 하지 않음 · 얼음을 맛보거나 먹지 않음 · 면장갑으로 손을 보호함',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C13','sci',4,2,'u3',3,'생활 속 온도와 부피 — 열기구 아래쪽을 가열하면 부풀어 오름 · 추운 겨울 바깥의 풍선은 쭈그러들고 따뜻한 실내로 가져오면 다시 팽팽해짐 · 물이 조금 든 페트병을 냉장고에 넣으면 쭈그러듦',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C14','sci',4,2,'u3',4,'압력의 뜻 — 압력은 누르는 힘 · 주사기의 피스톤을 누르면(세게 누를수록) 기체에 미치는 압력이 높아지고, 당기면 낮아짐',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C15','sci',4,2,'u3',4,'압력에 따른 기체의 부피 변화 — 기체에 미치는 압력이 높아지면 부피가 줄어들고, 낮아지면 늘어남 · 피스톤을 누르면 주사기 안 공기와 풍선의 부피가 함께 줄어들고, 당기면 함께 늘어남(피스톤에 닿지 않은 풍선도 달라짐)',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C16','sci',4,2,'u3',4,'주사기 실험 방법과 안전 — 주사기에 공기를 넣고 입구를 주사기 마개로 막음 · 풍선을 넣을 때는 주사기 마개를 먼저 분리한 뒤 피스톤을 분리함 · 보안경을 씀 · 눈금 숫자보다 부피가 어떻게 변하는지 관찰함',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C17','sci',4,2,'u3',4,'생활 속 압력과 부피 — 세게 친 배구공이 찌그러짐 · 호핑볼에 앉으면 부피가 줄고, 뛰어오르는 순간에는 늘어남 · 운동화 밑창의 공기 주머니는 발이 땅을 디딜 때 압력이 높아지며 줄어듦',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C18','sci',4,2,'u3',5,'생활 속 기체의 부피 변화 찾기 — 땡볕 아래 튜브·비치 볼은 팽팽해짐(온도↑) · 아이가 앉은 에어 매트는 납작해짐(압력↑) · 세게 찬 축구공은 순간적으로 찌그러짐(압력↑) · 냉장고의 비닐 랩 용기는 랩이 오목해짐(온도↓) · 짐을 많이 실은 자동차 타이어는 찌그러짐 · 포개진 그릇·공기 안전 매트',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C19','sci',4,2,'u3',5,'달라진 까닭 가르기 — 기체의 부피가 달라진 까닭이 온도인지 압력인지, 높아졌는지 낮아졌는지 함께 살핌 · 모습이 같아도(둘 다 줄어듦) 까닭은 다를 수 있음',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C20','sci',4,2,'u3',5,'스마트 기기로 조사하기 — 「온도에 따른 기체의 부피 변화의 예」처럼 검색어를 정함 · 조사한 정보의 출처를 확인하고 옳은 정보와 거짓 정보를 구분함 · 다른 사람에게 전달해도 되는 내용인지 판단함',ARRAY['[4과15-02] 온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C21','sci',4,2,'u3',6,'제품 속 여러 가지 기체 — 우리는 질소, 산소, 이산화 탄소 등의 기체를 이용함 · 과자 봉지(질소)·산소 캔(산소)·탄산음료(이산화 탄소)의 제품 설명에서 기체를 찾음 · 돋보기 활용, 준비물로 장난치지 않음 · 수소 같은 다른 기체도 있음 · 모둠 신문·뉴스·역할극·영상으로 발표함',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C22','sci',4,2,'u3',6,'질소 — 다른 물질과 만나도 반응을 거의 하지 않는 안정된 성질 → 식품을 오랫동안 보관하기 위한 포장 · 온도와 압력이 크게 변하는 항공기 타이어',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C23','sci',4,2,'u3',6,'산소 — 다른 물질이 타는 것을 돕는 성질, 생물의 호흡에 필요함 → 로켓의 연료를 태울 때, 산소 캔 같은 호흡을 돕는 장치, 살아 있는 해산물 포장 · 과일의 자른 면을 갈색으로 변하게 함',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C24','sci',4,2,'u3',6,'이산화 탄소 — 물에 넣으면 톡 쏘는 맛이 남 → 탄산음료 · 다른 물질이 타는 것을 막는 성질 → 소화기 · 발포 비타민을 물에 넣으면 나오는 기체 · 스스로 불을 꺼 버리는 것이 아니라 타는 것을 막는 성질',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C25','sci',4,2,'u3',6,'성질에 맞게 이용되는 기체 — 여러 가지 기체는 각각의 성질에 맞게 일상생활에서 다양하게 이용됨 · 이용 사례를 외우는 것이 아니라 성질과 이어서 이해함 · 조사할 때 출처를 확인함',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C26','sci',4,2,'u3',7,'시럽 장치가 움직이는 까닭 — 온도에 따라 약병 안 기체의 부피가 달라지면서 시럽 방울이 빨대 안에서 위아래로 움직임 · 따뜻한 창가 → 부피 늘어남 → 시럽 올라감 · 냉장고 안 → 부피 줄어듦 → 시럽 내려감 · 시럽을 움직이는 것은 약병 안 공기',ARRAY['[4과15-04] 기체의 성질을 이용하여 작동시킬 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C27','sci',4,2,'u3',7,'장치를 설계하고 만드는 차례 — 설계해요(재료·모양·변화가 잘 나타날 방법) → 약병 입구를 가위로 잘라 빨대를 꽂고 유토로 틈을 막음 → 색소를 섞은 시럽 한 방울(스포이트)을 빨대 중간에 → 도화지에 색깔·눈금을 그려 붙임 → 여러 장소에 두고 비교 · 가위 안전 · 보완 = 더 큰 병 등',ARRAY['[4과15-04] 기체의 성질을 이용하여 작동시킬 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C28','sci',4,2,'u3',7,'장치를 소개하고 평가하기 — 기체의 어떤 성질을 이용했는지 소개함 · 평가 기준 = 기체의 성질을 이용했는가, 친구의 생각이 잘 표현되었는가, 알맞게 작동했는가 · 잘한 점과 보완할 점을 함께 이야기함 · 꾸밈보다 이용한 성질 · 장치를 움직이는 기체는 공기',ARRAY['[4과15-04] 기체의 성질을 이용하여 작동시킬 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C29','sci',4,2,'u3',7,'옳지 않은 풍선 고치기 — 팡팡! 과학 놀이터 — 옳은 내용 풍선을 고르고 옳지 않은 내용을 바르게 고침 · 불을 끄는 소화기에는 산소가 아니라 이산화 탄소 · 햇빛 아래 과자 봉지가 부풀어 오름 · 공기를 더 넣으면 무게가 늘어남 · 환자의 호흡 장치에는 산소',ARRAY['[4과15-04] 기체의 성질을 이용하여 작동시킬 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C30','sci',4,2,'u3',8,'비행기의 문제 — 비행기는 중요한 운송 수단이지만 엔진에서 뿜어져 나오는 많은 양의 이산화 탄소가 환경오염을 유발함 · 이 문제를 보완하기 위해 과학자들이 비행선에 주목함',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C31','sci',4,2,'u3',8,'비행선과 헬륨 — 비행선은 커다란 풍선 모양의 비행체(날아다니는 물체) · 풍선 안에 헬륨이 들어 있음 · 헬륨은 같은 부피의 공기보다 가벼워 비행선이 공중에 떠오름 · 활주로 = 비행기가 뜨거나 내릴 때 달리는 길',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C32','sci',4,2,'u3',8,'비행선의 좋은 점 — 비행기에 비해 엔진을 적게 사용함(전혀 쓰지 않는 것이 아님) · 적은 양의 에너지로도 오랫동안 떠 있음 · 활주로가 없는 곳에서도 뜨고 내림 · 비행기가 다닐 수 없는 곳에서도 이용함',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u3-C33','sci',4,2,'u3',8,'기체를 이용한 친환경 제품 — 기체의 성질과 이용은 우리 주변의 산업과 환경에 영향을 미침 · 수소 기체를 연료로 이용해 환경오염 물질을 배출하지 않는 수소 자동차처럼 기체를 이용한 친환경 제품을 떠올림',ARRAY['[4과15-03] 일상생활에서 이용되는 기체의 종류와 성질을 조사하고 기체에 흥미를 느낄 수 있다(지도서 성취기준 · W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X01','sci',4,'u3',ARRAY['SC4-2-u3-C1']::text[],'기체는 눈에 보이지 않으니 있는지 알 방법이 없다거나 색깔을 보고 안다고 여긴다','다양한 상황에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X02','sci',4,'u3',ARRAY['SC4-2-u3-C1']::text[],'기체는 늘 눈에 보이거나, 어떤 용기에 담아도 모양이 같다고 여긴다','보이지 않음 · 모양이 바뀜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X03','sci',4,'u3',ARRAY['SC4-2-u3-C2']::text[],'숨이를 빨리 찾는 것 자체가 목표라고 여긴다','숨이는 단서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X04','sci',4,'u3',ARRAY['SC4-2-u3-C2']::text[],'◯표를 숨이에게 하거나 기체는 그림에 표시된 곳에만 있다고 여긴다','기체가 있는 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X05','sci',4,'u3',ARRAY['SC4-2-u3-C3']::text[],'공기가 들어 있는 것과 이동하는 것을 헷갈리거나 부채 바람의 까닭을 잘못 안다(부채가 차가워서)','들어 있음 · 이동함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X06','sci',4,'u3',ARRAY['SC4-2-u3-C4']::text[],'정답은 정해진 몇 가지뿐이라 여겨 친구가 다르게 찾은 것을 틀렸다고 한다','까닭을 들어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X07','sci',4,'u3',ARRAY['SC4-2-u3-C5']::text[],'기체는 무게가 없거나 눈에 보일 때만 무게가 있다고 여긴다','보이지 않아도 무게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X08','sci',4,'u3',ARRAY['SC4-2-u3-C6']::text[],'공기를 넣으면 용기가 가벼워지거나 무게가 그대로라고 여긴다','넣으면 늘어나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X09','sci',4,'u3',ARRAY['SC4-2-u3-C7']::text[],'공기를 빼도 무게가 그대로이거나 오히려 늘어난다고 여긴다','빼면 줄어들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X10','sci',4,'u3',ARRAY['SC4-2-u3-C8']::text[],'전자저울에 나온 값을 공기만의 무게라고 여긴다','용기 전체의 무게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X11','sci',4,'u3',ARRAY['SC4-2-u3-C8']::text[],'누른 횟수를 정확히 맞추는 것이 가장 중요하다거나 공기의 양을 모양·크기로 견준다고 여긴다','무게를 비교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X12','sci',4,'u3',ARRAY['SC4-2-u3-C9']::text[],'공기를 많이 넣은 마개를 힘껏 빨리 열거나 안전 장구를 갖추지 않는다','큰 소리 · 튕겨 나감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X13','sci',4,'u3',ARRAY['SC4-2-u3-C10']::text[],'온도가 높아지면 기체의 부피가 줄어들고 낮아지면 늘어난다고 거꾸로 안다','높아지면 늘어나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X14','sci',4,'u3',ARRAY['SC4-2-u3-C10']::text[],'기체의 부피는 온도가 달라져도 그대로라거나 고체만 온도의 영향을 받는다고 여긴다','온도의 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X15','sci',4,'u3',ARRAY['SC4-2-u3-C11']::text[],'머리 말리개의 바람이 풍선 안으로 들어가서 부피가 늘었다고 여긴다','입구를 잘 닫았어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X16','sci',4,'u3',ARRAY['SC4-2-u3-C11']::text[],'포일 풍선의 정확한 크기를 그리는 것이 가장 중요하다고 여긴다','어떻게 변하는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X17','sci',4,'u3',ARRAY['SC4-2-u3-C12']::text[],'머리 말리개를 풍선에 바짝 대거나 얼음을 맛보거나 풍선에 공기를 가득 넣는다','안전 셋') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X18','sci',4,'u3',ARRAY['SC4-2-u3-C13']::text[],'생활 속 온도 변화에서 부피가 변하는 방향을 거꾸로 알거나 물·뚜껑이 있으면 변하지 않는다고 여긴다','차가우면 쭈그러들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X19','sci',4,'u3',ARRAY['SC4-2-u3-C14']::text[],'압력의 뜻을 잘못 알거나(온도·크기) 피스톤을 당기면 압력이 높아진다고 여긴다','누르는 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X20','sci',4,'u3',ARRAY['SC4-2-u3-C15']::text[],'압력이 높아지면 기체의 부피가 늘어나고 낮아지면 줄어든다고 거꾸로 안다','높아지면 줄어들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X21','sci',4,'u3',ARRAY['SC4-2-u3-C15']::text[],'피스톤에 닿지 않은 주사기 안 풍선은 부피가 달라지지 않는다고 여긴다','닿지 않아도 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X22','sci',4,'u3',ARRAY['SC4-2-u3-C16']::text[],'주사기 입구를 막지 않거나 피스톤을 먼저 뽑는 등 실험 차례·안전을 잘못 안다','마개 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X23','sci',4,'u3',ARRAY['SC4-2-u3-C16']::text[],'주사기 눈금 숫자를 정확히 읽는 것이 가장 중요하다고 여긴다','어떻게 변하는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X24','sci',4,'u3',ARRAY['SC4-2-u3-C17']::text[],'생활 속 압력 변화에서 부피가 변하는 방향을 거꾸로 알거나 공기가 빠져나가 사라진다고 여긴다','앉으면 줄어들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X25','sci',4,'u3',ARRAY['SC4-2-u3-C18','SC4-2-u3-C19']::text[],'생활 속 예가 온도 때문인지 압력 때문인지 뒤바꾼다(땡볕·냉장고 — 압력, 앉기·차기 — 온도)','온도인지 압력인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X26','sci',4,'u3',ARRAY['SC4-2-u3-C19']::text[],'부피가 줄어든 모습이 같으면 까닭도 모두 같다고 여긴다','까닭은 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X27','sci',4,'u3',ARRAY['SC4-2-u3-C18']::text[],'한 번 달라진 부피는 그대로이거나 짐을 실으면 타이어가 더 팽팽해진다고 여긴다','다시 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X28','sci',4,'u3',ARRAY['SC4-2-u3-C20','SC4-2-u3-C25']::text[],'조사한 정보를 출처를 보지 않고 옮기거나 누리망 정보는 모두 옳다고 여긴다','출처 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X29','sci',4,'u3',ARRAY['SC4-2-u3-C21']::text[],'제품 겉면을 보지 않고 기체 이름을 짐작하거나 준비물로 장난친다','겉면 · 돋보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X30','sci',4,'u3',ARRAY['SC4-2-u3-C22']::text[],'질소의 성질을 다른 기체와 헷갈린다(톡 쏘는 맛, 타는 것을 도움, 숨 쉬게 함)','안정된 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X31','sci',4,'u3',ARRAY['SC4-2-u3-C23']::text[],'산소를 불을 끄는 데 쓰거나 산소는 반응을 거의 하지 않는다고 여긴다','타는 것을 도움 · 호흡') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X32','sci',4,'u3',ARRAY['SC4-2-u3-C24']::text[],'이산화 탄소가 물처럼 스스로 불을 꺼 버린다고 여긴다','타는 것을 막는 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X33','sci',4,'u3',ARRAY['SC4-2-u3-C24']::text[],'이산화 탄소의 성질을 다른 기체와 헷갈린다(타는 것을 도움, 호흡에 필요, 반응을 거의 하지 않음)','톡 쏘는 맛 · 타는 것을 막음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X34','sci',4,'u3',ARRAY['SC4-2-u3-C25']::text[],'기체가 어디에 이용되는지는 성질과 상관없이 외우기만 하면 된다고 여긴다','성질에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X35','sci',4,'u3',ARRAY['SC4-2-u3-C26']::text[],'장치를 따뜻한 곳에 두면 시럽이 내려가고 차가운 곳에 두면 올라간다고 거꾸로 안다','창가 — 올라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X36','sci',4,'u3',ARRAY['SC4-2-u3-C26']::text[],'시럽이 녹거나 무거워져서 움직인다거나 입구를 막았으니 움직이지 않는다고 여긴다','약병 안 공기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X37','sci',4,'u3',ARRAY['SC4-2-u3-C27']::text[],'장치를 만들 때 틈을 그대로 두거나 가위로 장난치거나 만드는 차례를 잘못 안다','유토로 틈 막기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X38','sci',4,'u3',ARRAY['SC4-2-u3-C27']::text[],'장치를 보완하는 방법을 잘못 고른다(틈 열기, 시럽 빼기, 색만 더 칠하기)','변화가 잘 나타나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X39','sci',4,'u3',ARRAY['SC4-2-u3-C28']::text[],'예쁘게 꾸미기만 하면 잘 만든 장치라고 여긴다','이용한 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X40','sci',4,'u3',ARRAY['SC4-2-u3-C28']::text[],'장치 안에는 공기가 아닌 특별한 기체를 따로 넣어야 작동한다고 여긴다','움직이는 것은 공기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X41','sci',4,'u3',ARRAY['SC4-2-u3-C30']::text[],'비행기 엔진의 이산화 탄소가 비행기를 띄우거나 환경과 관계없다고 여긴다','환경오염을 유발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X42','sci',4,'u3',ARRAY['SC4-2-u3-C31']::text[],'비행선 풍선 안에 공기나 공기보다 무거운 기체가 들어 있거나 엔진 힘만으로 뜬다고 여긴다','공기보다 가벼운 헬륨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X43','sci',4,'u3',ARRAY['SC4-2-u3-C32']::text[],'비행선은 엔진을 전혀 쓰지 않는다고 여긴다','비행기에 비해 적게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X44','sci',4,'u3',ARRAY['SC4-2-u3-C32']::text[],'비행선도 긴 활주로가 있어야만 뜨고 내린다고 여긴다','활주로 없이도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u3-X45','sci',4,'u3',ARRAY['SC4-2-u3-C33']::text[],'친환경 제품의 뜻을 잘못 안다(엔진을 더 크게, 이산화 탄소를 더 많이)','환경오염 물질 줄이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#1','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C1',1,'mc','auto','눈으로 볼 수 없는 기체가 있다는 것을 어떻게 알 수 있나요?',ARRAY['SC4-2-u3-X01','SC4-2-u3-X03']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C1","difficulty":1,"kind":"mc","stem":"눈으로 볼 수 없는 기체가 있다는 것을 어떻게 알 수 있나요?","options":[{"t":"다양한 상황에서 알 수 있다","correct":true},{"t":"기체의 색깔을 보고 알 수 있다","mis":"SC4-2-u3-X01"},{"t":"알 수 있는 방법이 없다","mis":"SC4-2-u3-X01"},{"t":"숨이를 찾으면 알 수 있다","mis":"SC4-2-u3-X03"}],"explanation":["보이지 않아도 느낄 수 있어요.","바람, 팽팽한 공을 떠올려요.","다양한 상황에서 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#2','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C1',1,'ox','auto','기체는 대부분 눈에 보이지 않아요.',ARRAY['SC4-2-u3-X02']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C1","difficulty":1,"kind":"ox","stem":"기체는 대부분 눈에 보이지 않아요.","answer":"O","reason_options":[{"t":"공기처럼 기체는 대부분 눈으로 볼 수 없기 때문에","correct":true},{"t":"기체는 언제나 눈에 잘 보이기 때문에","mis":"SC4-2-u3-X02"}],"mis":"SC4-2-u3-X02","explanation":["공기를 떠올려요.","눈으로 볼 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#3','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C3',1,'mc','auto','부채질을 하면 바람을 느낄 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X05','SC4-2-u3-X03']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C3","difficulty":1,"kind":"mc","stem":"부채질을 하면 바람을 느낄 수 있는 까닭은 무엇인가요?","options":[{"t":"부채질을 하면 공기가 이동하기 때문에","correct":true},{"t":"부채에서 물이 나오기 때문에","mis":"SC4-2-u3-X05"},{"t":"부채가 차갑기 때문에","mis":"SC4-2-u3-X05"},{"t":"숨이가 옆에 앉아 있기 때문에","mis":"SC4-2-u3-X03"}],"explanation":["부채가 무엇을 움직일까요?","공기가 움직여요.","공기가 이동하기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#4','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C2',1,'sa','auto','숨이의 머리에는 무엇 모양의 장식이 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C2","difficulty":1,"kind":"sa","stem":"숨이의 머리에는 무엇 모양의 장식이 있나요? 두 글자로 쓰세요.","answer":["풍선","풍선 모양"],"explanation":["숨이의 모습을 떠올려요.","공기를 담는 물건이에요.","풍선이에요."],"mis":"SC4-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#5','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C2',2,'mc','auto','숨이가 있는 곳을 보고 ◯표는 어디에 하나요?',ARRAY['SC4-2-u3-X04','SC4-2-u3-X03']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C2","difficulty":2,"kind":"mc","stem":"숨이가 있는 곳을 보고 ◯표는 어디에 하나요?","options":[{"t":"숨이 주변에서 기체가 있는 부분","correct":true},{"t":"숨이의 얼굴","mis":"SC4-2-u3-X04"},{"t":"그림에서 가장 큰 물건","mis":"SC4-2-u3-X04"},{"t":"숨이를 가장 먼저 찾은 곳","mis":"SC4-2-u3-X03"}],"explanation":["숨이는 단서예요.","기체를 찾아요.","기체가 있는 부분이에요."],"asset":{"type":"passage","lines":["소방서 앞 — 소방대원이 등에 멘 공기통","공기 미끄럼틀 위 — 아이들이 노는 미끄럼틀","자전거 앞 — 공기 주입기와 자전거 타이어","부채질하는 사람 옆 — 부채"],"title":"숨이가 있는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#6','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C2',2,'match','auto','숨이가 있는 곳과 기체가 있는 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u3-C2","difficulty":2,"kind":"match","stem":"숨이가 있는 곳과 기체가 있는 부분을 알맞게 이으세요.","pairs":[{"l":"소방서 앞","r":"소방대원이 등에 멘 공기통 안의 공기"},{"l":"공기 미끄럼틀 위","r":"미끄럼틀 안에 들어 있는 공기"},{"l":"자전거 앞","r":"공기 주입기로 타이어에 넣는 공기"},{"l":"부채질하는 사람 옆","r":"부채질로 이동하는 공기"}],"mis":"SC4-2-u3-X04","explanation":["숨이 주변을 살펴요.","기체가 있는 곳을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["소방서 앞 — 소방대원이 등에 멘 공기통","공기 미끄럼틀 위 — 아이들이 노는 미끄럼틀","자전거 앞 — 공기 주입기와 자전거 타이어","부채질하는 사람 옆 — 부채"],"title":"숨이가 있는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#7','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C1',2,'mc','auto','기체에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X02']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C1","difficulty":2,"kind":"mc","stem":"기체에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"기체는 담는 용기에 따라 모양이 바뀐다","correct":true},{"t":"기체는 어떤 용기에 담아도 모양이 늘 같다","mis":"SC4-2-u3-X02"},{"t":"기체는 언제나 눈에 잘 보인다","mis":"SC4-2-u3-X02"},{"t":"기체는 주어진 공간의 한쪽에만 모인다","mis":"SC4-2-u3-X02"}],"explanation":["기체에 대해 알고 있는 것을 떠올려요.","용기 모양을 따라가요.","모양이 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#8','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C3',2,'ox','auto','공이나 튜브가 팽팽한 것은 그 안에 공기가 들어 있기 때문이에요.',ARRAY['SC4-2-u3-X05']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C3","difficulty":2,"kind":"ox","stem":"공이나 튜브가 팽팽한 것은 그 안에 공기가 들어 있기 때문이에요.","answer":"O","reason_options":[{"t":"공기가 안을 가득 채우고 있기 때문에","correct":true},{"t":"공과 튜브는 원래 딱딱한 물건이기 때문에","mis":"SC4-2-u3-X05"}],"mis":"SC4-2-u3-X05","explanation":["팽팽한 공을 떠올려요.","안에 무엇이 있을까요?","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#9','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C4',2,'mc','auto','내가 찾은 것과 친구가 찾은 것이 다를 때 어떻게 하면 좋을까요?',ARRAY['SC4-2-u3-X06','SC4-2-u3-X03']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C4","difficulty":2,"kind":"mc","stem":"내가 찾은 것과 친구가 찾은 것이 다를 때 어떻게 하면 좋을까요?","options":[{"t":"그렇게 생각한 까닭을 서로 이야기한다","correct":true},{"t":"친구가 찾은 것은 틀렸다고 한다","mis":"SC4-2-u3-X06"},{"t":"내가 찾은 것을 모두 지운다","mis":"SC4-2-u3-X06"},{"t":"숨이를 더 빨리 찾은 사람 것만 인정한다","mis":"SC4-2-u3-X03"}],"explanation":["비교하는 까닭을 떠올려요.","까닭을 들어 봐요.","서로 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_basic#10','sci',4,2,'u3','L01','g4_2_sci_u3_L01_basic','lesson_basic','SC4-2-u3-C3',3,'mc','auto','공기가 「이동하는」 모습은 무엇인가요?',ARRAY['SC4-2-u3-X05']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C3","difficulty":3,"kind":"mc","stem":"공기가 「이동하는」 모습은 무엇인가요?","options":[{"t":"공기 주입기를 통해 공기가 자전거 타이어 안으로 들어간다","correct":true},{"t":"공 안에 공기가 들어 있다","mis":"SC4-2-u3-X05"},{"t":"튜브 안에 공기가 들어 있다","mis":"SC4-2-u3-X05"},{"t":"풍선 안에 공기가 들어 있다","mis":"SC4-2-u3-X05"}],"explanation":["들어 있음과 이동함을 나눠요.","어디에서 어디로 가요.","공기 주입기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#1','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C1',2,'blank','auto','「기체는 주어진 공간을 (    ) 채울 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X02']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C1","difficulty":2,"kind":"blank","stem":"「기체는 주어진 공간을 (    ) 채울 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"가득","correct":true},{"t":"절반만","mis":"SC4-2-u3-X02"},{"t":"한쪽 구석만","mis":"SC4-2-u3-X02"},{"t":"바닥만","mis":"SC4-2-u3-X02"}],"explanation":["공간을 떠올려요.","빈틈없이 채워요.","가득이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#2','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C2',2,'mc','auto','숨이를 찾는 활동에서 가장 중요한 것은 무엇인가요?',ARRAY['SC4-2-u3-X03','SC4-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C2","difficulty":2,"kind":"mc","stem":"숨이를 찾는 활동에서 가장 중요한 것은 무엇인가요?","options":[{"t":"숨이 주변에서 기체가 있는 알맞은 상황을 찾는 것","correct":true},{"t":"숨이를 가장 빨리 찾는 것","mis":"SC4-2-u3-X03"},{"t":"숨이를 색칠하는 것","mis":"SC4-2-u3-X03"},{"t":"그림에 표시된 곳만 찾는 것","mis":"SC4-2-u3-X04"}],"explanation":["숨이는 단서예요.","기체를 찾는 활동이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#3','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C2',3,'error','auto','숨이 주변에서 기체를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X04','SC4-2-u3-X03']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C2","difficulty":3,"kind":"error","stem":"숨이 주변에서 기체를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「숨이를 찾았으니 숨이 얼굴에 ◯표 하면 끝이야.」","correct":true,"mis_target":"SC4-2-u3-X04"},{"t":"친구 가 — 「숨이가 있는 곳 가까이에서 기체를 찾아보자.」","mis":"SC4-2-u3-X03"},{"t":"친구 나 — 「소방대원의 공기통 안에도 공기가 있어.」","mis":"SC4-2-u3-X04"}],"explanation":["◯표 할 곳을 떠올려요.","기체가 있는 부분이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#4','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C3',3,'mc','auto','공기가 안에 「들어 있는」 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u3-X05']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C3","difficulty":3,"kind":"mc","stem":"공기가 안에 「들어 있는」 것끼리 묶은 것은 무엇인가요?","options":[{"t":"공, 풍선, 튜브","correct":true},{"t":"부채질로 부는 바람, 공기 주입기로 넣는 공기","mis":"SC4-2-u3-X05"},{"t":"공, 부채질로 부는 바람","mis":"SC4-2-u3-X05"},{"t":"공기 주입기로 넣는 공기, 튜브","mis":"SC4-2-u3-X05"}],"explanation":["안에 담겨 있는 것을 찾아요.","팽팽한 물건이에요.","공, 풍선, 튜브예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#5','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C4',3,'ox','auto','물에서 공기 방울이 보글보글 올라오는 모습처럼 그림에 없는 것을 상상해서 찾은 것도 이야기할 수 있어요.',ARRAY['SC4-2-u3-X06']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C4","difficulty":3,"kind":"ox","stem":"물에서 공기 방울이 보글보글 올라오는 모습처럼 그림에 없는 것을 상상해서 찾은 것도 이야기할 수 있어요.","answer":"O","reason_options":[{"t":"우리 주변에서 기체가 있는 상황은 정해진 몇 가지뿐이 아니기 때문에","correct":true},{"t":"그림에 ◯표 할 수 없는 것은 모두 틀린 답이기 때문에","mis":"SC4-2-u3-X06"}],"mis":"SC4-2-u3-X06","explanation":["친구의 생각을 떠올려요.","까닭을 들어 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#6','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C1',3,'mc','auto','바람이 불 때, 숨을 쉴 때 공기를 느낀 경험으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u3-X01','SC4-2-u3-X04']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C1","difficulty":3,"kind":"mc","stem":"바람이 불 때, 숨을 쉴 때 공기를 느낀 경험으로 알 수 있는 것은 무엇인가요?","options":[{"t":"눈으로 볼 수 없어도 우리 주변에 공기가 있다","correct":true},{"t":"공기는 바람이 불 때만 생긴다","mis":"SC4-2-u3-X01"},{"t":"공기는 눈으로 보아야만 있다는 것을 안다","mis":"SC4-2-u3-X01"},{"t":"숨이가 없는 곳에는 공기가 없다","mis":"SC4-2-u3-X04"}],"explanation":["경험을 떠올려요.","보이지 않아도 느꼈어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#7','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C3',3,'mc','auto','자전거 타이어에 공기를 넣을 때 일어나는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X05','SC4-2-u3-X01']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C3","difficulty":3,"kind":"mc","stem":"자전거 타이어에 공기를 넣을 때 일어나는 일로 알맞은 것은 무엇인가요?","options":[{"t":"공기가 공기 주입기를 통해 타이어 안으로 이동해 타이어가 팽팽해진다","correct":true},{"t":"타이어 안의 공기가 밖으로 빠져 납작해진다","mis":"SC4-2-u3-X05"},{"t":"공기 주입기가 공기를 없앤다","mis":"SC4-2-u3-X05"},{"t":"보이지 않으니 아무것도 들어가지 않는다","mis":"SC4-2-u3-X01"}],"explanation":["공기 주입기를 떠올려요.","공기가 안으로 가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#8','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C4',4,'mc','auto','친구가 「물에서 공기 방울이 보글보글 올라오는 모습을 상상해서 찾았어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X06','SC4-2-u3-X03']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C4","difficulty":4,"kind":"mc","stem":"친구가 「물에서 공기 방울이 보글보글 올라오는 모습을 상상해서 찾았어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「그림에 없는 모습이어도 좋아. 왜 그렇게 생각했는지 들려줄래?」","correct":true},{"t":"「정답은 그림 속 몇 가지뿐이라 틀렸어.」","mis":"SC4-2-u3-X06"},{"t":"「그림에 동그라미가 없으니 인정할 수 없어.」","mis":"SC4-2-u3-X06"},{"t":"「숨이를 못 찾았으니 다시 찾아.」","mis":"SC4-2-u3-X03"}],"explanation":["친구와 비교할 때를 떠올려요.","까닭을 들어 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#9','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C1',4,'mc','auto','친구가 「공기는 보이지 않으니 정말 있는지 알 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X01','SC4-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C1","difficulty":4,"kind":"mc","stem":"친구가 「공기는 보이지 않으니 정말 있는지 알 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「부채질하면 바람이 느껴지고 공이 팽팽한 걸 보면 공기가 있다는 걸 알 수 있어.」","correct":true},{"t":"「맞아, 보이지 않으면 없는 거야.」","mis":"SC4-2-u3-X01"},{"t":"「공기는 색깔이 있어서 보여.」","mis":"SC4-2-u3-X01"},{"t":"「공기는 공 안에만 있어.」","mis":"SC4-2-u3-X04"}],"explanation":["경험을 떠올려요.","바람과 팽팽한 공이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L01_challenge#10','sci',4,2,'u3','L01','g4_2_sci_u3_L01_challenge','lesson_challenge','SC4-2-u3-C3',4,'essay','teacher','생활 속에서 공기를 느껴 본 경험을 두 가지 쓰고, 각각 공기가 「들어 있는」 것인지 「이동하는」 것인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C3","difficulty":4,"kind":"essay","stem":"생활 속에서 공기를 느껴 본 경험을 두 가지 쓰고, 각각 공기가 「들어 있는」 것인지 「이동하는」 것인지 쓰세요.","answer_guide":{"answer":"예: 공이나 튜브가 팽팽할 때 그 안에 공기가 들어 있다는 것을 알 수 있다(들어 있음). 부채질을 하면 공기가 이동해 바람을 느낄 수 있다(이동함).","scoring_points":["경험 하나를 썼는가","경험 또 하나를 썼는가","들어 있음과 이동함을 바르게 나누었는가"]},"explanation":["경험을 떠올려요.","두 가지를 써요.","어느 쪽인지 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#1','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C5',1,'mc','auto','고체와 액체는 모두 무게가 있어요. 공기와 같은 기체는 어떨까요?',ARRAY['SC4-2-u3-X07']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C5","difficulty":1,"kind":"mc","stem":"고체와 액체는 모두 무게가 있어요. 공기와 같은 기체는 어떨까요?","options":[{"t":"눈에 보이지 않는 기체도 무게가 있다","correct":true},{"t":"기체는 무게가 없다","mis":"SC4-2-u3-X07"},{"t":"눈에 보일 때만 무게가 있다","mis":"SC4-2-u3-X07"},{"t":"색깔이 있는 기체만 무게가 있다","mis":"SC4-2-u3-X07"}],"explanation":["실험 결과를 떠올려요.","공기를 넣으니 무거워졌어요.","기체도 무게가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#2','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C6',1,'sa','auto','페트병이나 감압 용기의 무게를 잴 때 쓴 기구의 이름을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u3-C6","difficulty":1,"kind":"sa","stem":"페트병이나 감압 용기의 무게를 잴 때 쓴 기구의 이름을 네 글자로 쓰세요.","answer":["전자저울","전자 저울"],"explanation":["무게를 재는 기구예요.","숫자가 화면에 나와요.","전자저울이에요."],"mis":"SC4-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#3','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C9',1,'ox','auto','공기를 많이 넣은 공기 주입 마개를 열 때에는 큰 소리가 나고 마개가 튕겨 나갈 수 있으니 조심해요.',ARRAY['SC4-2-u3-X12']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C9","difficulty":1,"kind":"ox","stem":"공기를 많이 넣은 공기 주입 마개를 열 때에는 큰 소리가 나고 마개가 튕겨 나갈 수 있으니 조심해요.","answer":"O","reason_options":[{"t":"마개가 튕겨 나가 다칠 수 있기 때문에","correct":true},{"t":"공기를 많이 넣어도 마개는 조용히 열리기 때문에","mis":"SC4-2-u3-X12"}],"mis":"SC4-2-u3-X12","explanation":["마개를 열 때를 떠올려요.","튕겨 나갈 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#4','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C6',1,'mc','auto','공기를 넣은 뒤 페트병의 무게는 어떻게 되었나요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C6","difficulty":1,"kind":"mc","stem":"공기를 넣은 뒤 페트병의 무게는 어떻게 되었나요?","options":[{"t":"늘어났다","correct":true},{"t":"줄어들었다","mis":"SC4-2-u3-X08"},{"t":"그대로였다","mis":"SC4-2-u3-X08"},{"t":"알 수 없었다","mis":"SC4-2-u3-X07"}],"explanation":["①과 ③을 견줘요.","54.0 g에서 54.2 g이 되었어요.","늘어났어요."],"asset":{"type":"passage","lines":["① 공기 주입 마개를 끼운 페트병의 무게를 재었어요. — 예 54.0 g","② 마개를 여러 번 눌러 공기를 넣었어요.","③ 페트병의 무게를 다시 재었어요. — 예 54.2 g"],"title":"페트병에 공기를 넣는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#5','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C7',2,'mc','auto','펌프를 당긴 뒤 감압 용기의 무게는 어떻게 되었나요?',ARRAY['SC4-2-u3-X09','SC4-2-u3-X07']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C7","difficulty":2,"kind":"mc","stem":"펌프를 당긴 뒤 감압 용기의 무게는 어떻게 되었나요?","options":[{"t":"줄어들었다 — 용기 안의 공기가 빠져나갔기 때문에","correct":true},{"t":"늘어났다 — 용기 안의 공기가 빠져나갔기 때문에","mis":"SC4-2-u3-X09"},{"t":"그대로였다 — 공기는 무게가 없기 때문에","mis":"SC4-2-u3-X07"},{"t":"그대로였다 — 펌프만 움직였기 때문에","mis":"SC4-2-u3-X09"}],"explanation":["①과 ③을 견줘요.","공기를 빼냈어요.","줄어들었어요."],"asset":{"type":"passage","lines":["① 감압 용기의 무게를 재었어요. — 예 333.6 g","② 펌프를 여러 번 당겨 공기를 빼냈어요.","③ 감압 용기의 무게를 다시 재었어요. — 예 333.2 g"],"title":"감압 용기에서 공기를 빼는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#6','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C7',2,'match','auto','한 일과 알게 된 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u3-C7","difficulty":2,"kind":"match","stem":"한 일과 알게 된 것을 알맞게 이으세요.","pairs":[{"l":"공기 주입 마개를 여러 번 눌러요","r":"페트병 안으로 공기가 들어가요"},{"l":"펌프를 여러 번 당겨요","r":"용기 안의 공기가 빠져나가요"},{"l":"공기를 넣은 뒤 페트병을 재어요","r":"무게가 늘어났어요"},{"l":"공기를 뺀 뒤 감압 용기를 재어요","r":"무게가 줄어들었어요"}],"mis":"SC4-2-u3-X09","explanation":["넣기와 빼기를 나눠요.","무게 변화를 떠올려요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#7','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C8',2,'mc','auto','전자저울로 잰 것은 무엇의 무게인가요?',ARRAY['SC4-2-u3-X10']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C8","difficulty":2,"kind":"mc","stem":"전자저울로 잰 것은 무엇의 무게인가요?","options":[{"t":"페트병, 공기 주입 마개, 안에 든 공기를 모두 합한 무게","correct":true},{"t":"페트병 안에 든 공기만의 무게","mis":"SC4-2-u3-X10"},{"t":"공기 주입 마개만의 무게","mis":"SC4-2-u3-X10"},{"t":"전자저울만의 무게","mis":"SC4-2-u3-X10"}],"explanation":["저울 위에 무엇이 있었나요?","용기를 통째로 올렸어요.","모두 합한 무게예요."],"asset":{"type":"passage","lines":["① 공기 주입 마개를 끼운 페트병의 무게를 재었어요. — 예 54.0 g","② 마개를 여러 번 눌러 공기를 넣었어요.","③ 페트병의 무게를 다시 재었어요. — 예 54.2 g"],"title":"페트병에 공기를 넣는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#8','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C9',2,'ox','auto','무게를 재는 실험을 할 때에는 실험복, 보안경, 실험용 장갑을 갖추어요.',ARRAY['SC4-2-u3-X12']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C9","difficulty":2,"kind":"ox","stem":"무게를 재는 실험을 할 때에는 실험복, 보안경, 실험용 장갑을 갖추어요.","answer":"O","reason_options":[{"t":"실험할 때 몸을 보호하기 위해서","correct":true},{"t":"장갑을 끼면 페트병이 더 무거워지기 때문에","mis":"SC4-2-u3-X12"}],"mis":"SC4-2-u3-X12","explanation":["안전을 떠올려요.","몸을 보호해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#9','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C6',2,'mc','auto','공기 주입 마개를 열 번 누른 페트병과 스무 번 누른 페트병 가운데 더 무거운 것은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C6","difficulty":2,"kind":"mc","stem":"공기 주입 마개를 열 번 누른 페트병과 스무 번 누른 페트병 가운데 더 무거운 것은 무엇인가요?","options":[{"t":"스무 번 누른 페트병 — 공기가 더 많이 들어갔기 때문에","correct":true},{"t":"열 번 누른 페트병 — 공기가 적게 들어가 무겁기 때문에","mis":"SC4-2-u3-X08"},{"t":"둘 다 같다 — 공기는 무게가 없기 때문에","mis":"SC4-2-u3-X07"},{"t":"알 수 없다 — 공기는 보이지 않기 때문에","mis":"SC4-2-u3-X07"}],"explanation":["누를수록 무엇이 들어가요?","공기가 많이 들어가요.","스무 번 누른 쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_basic#10','sci',4,2,'u3','L02','g4_2_sci_u3_L02_basic','lesson_basic','SC4-2-u3-C8',3,'mc','auto','모양과 크기가 똑같은 두 공기통 가운데 공기가 더 많이 든 것을 알아내는 방법은 무엇인가요?',ARRAY['SC4-2-u3-X11','SC4-2-u3-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C8","difficulty":3,"kind":"mc","stem":"모양과 크기가 똑같은 두 공기통 가운데 공기가 더 많이 든 것을 알아내는 방법은 무엇인가요?","options":[{"t":"두 공기통의 무게를 비교한다","correct":true},{"t":"두 공기통의 모양과 크기를 비교한다","mis":"SC4-2-u3-X11"},{"t":"공기통 안을 눈으로 들여다본다","mis":"SC4-2-u3-X07"},{"t":"공기는 무게가 없어 알아낼 수 없다","mis":"SC4-2-u3-X07"}],"explanation":["겉모습은 똑같아요.","공기가 많으면 무거워요.","무게를 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#1','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C8',2,'blank','auto','「용기 안에 공기가 많이 들어 있을수록 용기의 무게가 더 (    ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07','SC4-2-u3-X11']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C8","difficulty":2,"kind":"blank","stem":"「용기 안에 공기가 많이 들어 있을수록 용기의 무게가 더 (    ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"무거워져요","correct":true},{"t":"가벼워져요","mis":"SC4-2-u3-X08"},{"t":"그대로예요","mis":"SC4-2-u3-X07"},{"t":"작아져요","mis":"SC4-2-u3-X11"}],"explanation":["넣을수록 어떻게 되었나요?","늘어났어요.","무거워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#2','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C7',2,'mc','auto','무게가 줄어드는 경우는 무엇인가요?',ARRAY['SC4-2-u3-X08']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C7","difficulty":2,"kind":"mc","stem":"무게가 줄어드는 경우는 무엇인가요?","options":[{"t":"팽팽한 고무배에서 공기를 빼낸다","correct":true},{"t":"축구공에 공기를 팽팽하게 넣는다","mis":"SC4-2-u3-X08"},{"t":"고무배에 공기를 더 넣는다","mis":"SC4-2-u3-X08"},{"t":"공기 주입 마개를 여러 번 누른다","mis":"SC4-2-u3-X08"}],"explanation":["빼는 쪽을 찾아요.","공기가 나가요.","공기를 빼낸 고무배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#3','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C8',3,'error','auto','실험 결과를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X10','SC4-2-u3-X08']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C8","difficulty":3,"kind":"error","stem":"실험 결과를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「전자저울에 나온 54.2 g이 페트병 안 공기만의 무게야.」","correct":true,"mis_target":"SC4-2-u3-X10"},{"t":"친구 나 — 「공기를 넣었더니 페트병이 더 무거워졌어.」","mis":"SC4-2-u3-X08"},{"t":"친구 다 — 「페트병과 마개, 공기를 모두 합한 무게를 잰 거야.」","mis":"SC4-2-u3-X10"}],"explanation":["무엇을 재었는지 떠올려요.","용기를 통째로 재었어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 공기 주입 마개를 끼운 페트병의 무게를 재었어요. — 예 54.0 g","② 마개를 여러 번 눌러 공기를 넣었어요.","③ 페트병의 무게를 다시 재었어요. — 예 54.2 g"],"title":"페트병에 공기를 넣는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#4','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C6',3,'mc','auto','페트병에 공기를 넣는 실험으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X11','SC4-2-u3-X07']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C6","difficulty":3,"kind":"mc","stem":"페트병에 공기를 넣는 실험으로 알 수 있는 것은 무엇인가요?","options":[{"t":"공기를 넣으면 용기의 무게가 늘어나므로 공기도 무게가 있다","correct":true},{"t":"페트병은 공기를 넣을 때마다 가벼워진다","mis":"SC4-2-u3-X08"},{"t":"마개를 누른 횟수만 정확히 알면 된다","mis":"SC4-2-u3-X11"},{"t":"공기는 무게가 없다","mis":"SC4-2-u3-X07"}],"explanation":["①과 ③을 견줘요.","늘어난 까닭은 공기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 공기 주입 마개를 끼운 페트병의 무게를 재었어요. — 예 54.0 g","② 마개를 여러 번 눌러 공기를 넣었어요.","③ 페트병의 무게를 다시 재었어요. — 예 54.2 g"],"title":"페트병에 공기를 넣는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#5','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C9',3,'mc','auto','공기를 많이 넣은 페트병의 마개를 열 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u3-X12']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C9","difficulty":3,"kind":"mc","stem":"공기를 많이 넣은 페트병의 마개를 열 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"마개가 튕겨 나갈 수 있으니 조심해서 천천히 연다","correct":true},{"t":"힘껏 빨리 연다","mis":"SC4-2-u3-X12"},{"t":"친구 얼굴 앞에서 연다","mis":"SC4-2-u3-X12"},{"t":"소리가 나지 않으니 아무렇게나 연다","mis":"SC4-2-u3-X12"}],"explanation":["안전을 떠올려요.","튕겨 나갈 수 있어요.","조심해서 열어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#6','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C5',3,'ox','auto','공기는 눈에 보이지 않으니 무게도 없어요.',ARRAY['SC4-2-u3-X07']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C5","difficulty":3,"kind":"ox","stem":"공기는 눈에 보이지 않으니 무게도 없어요.","answer":"X","reason_options":[{"t":"공기를 넣거나 빼면 용기의 무게가 달라지기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 무게가 없기 때문에","mis":"SC4-2-u3-X07"}],"mis":"SC4-2-u3-X07","explanation":["실험 결과를 떠올려요.","무게가 달라졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#7','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C7',3,'mc','auto','감압 용기 실험 결과를 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X09']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C7","difficulty":3,"kind":"mc","stem":"감압 용기 실험 결과를 바르게 말한 것은 무엇인가요?","options":[{"t":"공기를 빼냈더니 용기의 무게가 줄어들었다","correct":true},{"t":"공기를 넣었더니 용기의 무게가 줄어들었다","mis":"SC4-2-u3-X08"},{"t":"공기를 빼냈더니 용기의 무게가 늘어났다","mis":"SC4-2-u3-X09"},{"t":"공기를 빼도 용기의 무게는 그대로였다","mis":"SC4-2-u3-X09"}],"explanation":["②를 읽어요.","공기를 빼냈어요.","줄어들었어요."],"asset":{"type":"passage","lines":["① 감압 용기의 무게를 재었어요. — 예 333.6 g","② 펌프를 여러 번 당겨 공기를 빼냈어요.","③ 감압 용기의 무게를 다시 재었어요. — 예 333.2 g"],"title":"감압 용기에서 공기를 빼는 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#8','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C8',4,'mc','auto','친구가 「축구공에 공기를 더 넣어도 크기가 거의 그대로니까 무게도 그대로야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X11','SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C8","difficulty":4,"kind":"mc","stem":"친구가 「축구공에 공기를 더 넣어도 크기가 거의 그대로니까 무게도 그대로야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「크기가 비슷해도 안에 공기가 더 들어가면 축구공의 무게가 늘어나.」","correct":true},{"t":"「맞아, 크기가 같으면 무게도 같아.」","mis":"SC4-2-u3-X11"},{"t":"「공기를 넣으면 축구공이 가벼워져.」","mis":"SC4-2-u3-X08"},{"t":"「공기는 무게가 없으니 그대로야.」","mis":"SC4-2-u3-X07"}],"explanation":["공기통 문제를 떠올려요.","크기가 아니라 공기의 양이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#9','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C6',4,'mc','auto','친구가 「마개를 누른 횟수를 정확히 맞추지 않으면 실험이 소용없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X11','SC4-2-u3-X07','SC4-2-u3-X10']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C6","difficulty":4,"kind":"mc","stem":"친구가 「마개를 누른 횟수를 정확히 맞추지 않으면 실험이 소용없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「횟수보다 공기를 넣기 전과 넣은 뒤의 무게가 어떻게 달라졌는지 견주는 게 중요해.」","correct":true},{"t":"「맞아, 횟수가 가장 중요해.」","mis":"SC4-2-u3-X11"},{"t":"「무게는 재지 않아도 돼.」","mis":"SC4-2-u3-X07"},{"t":"「공기만의 무게를 재면 돼.」","mis":"SC4-2-u3-X10"}],"explanation":["무엇을 알아보는 실험인가요?","무게 변화를 견줘요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L02_challenge#10','sci',4,2,'u3','L02','g4_2_sci_u3_L02_challenge','lesson_challenge','SC4-2-u3-C5',4,'essay','teacher','페트병 실험과 감압 용기 실험의 결과를 각각 쓰고, 두 실험으로 알 수 있는 사실을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C5","difficulty":4,"kind":"essay","stem":"페트병 실험과 감압 용기 실험의 결과를 각각 쓰고, 두 실험으로 알 수 있는 사실을 쓰세요.","answer_guide":{"answer":"예: 공기 주입 마개를 여러 번 눌러 공기를 넣은 페트병은 무게가 늘어났고, 펌프를 당겨 공기를 빼낸 감압 용기는 무게가 줄어들었다. 이것으로 눈에 보이지 않는 공기와 같은 기체도 무게가 있다는 것을 알 수 있다.","scoring_points":["페트병 실험 결과를 썼는가","감압 용기 실험 결과를 썼는가","기체도 무게가 있다는 사실을 썼는가"]},"explanation":["두 실험을 떠올려요.","결과를 써요.","알게 된 사실을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#1','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C10',1,'mc','auto','기체의 부피와 온도에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X14']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"mc","stem":"기체의 부피와 온도에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"기체의 부피는 주변 온도의 영향을 받는다","correct":true},{"t":"기체의 부피는 온도가 달라져도 그대로이다","mis":"SC4-2-u3-X14"},{"t":"고체만 온도의 영향을 받고 기체는 받지 않는다","mis":"SC4-2-u3-X14"},{"t":"기체는 눈에 보이지 않아 부피가 달라지지 않는다","mis":"SC4-2-u3-X14"}],"explanation":["포일 풍선을 떠올려요.","따뜻할 때와 차가울 때가 달랐어요.","온도의 영향을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#2','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C10',1,'mc','auto','②처럼 따뜻한 바람을 쏘이면 포일 풍선은 어떻게 되나요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"mc","stem":"②처럼 따뜻한 바람을 쏘이면 포일 풍선은 어떻게 되나요?","options":[{"t":"부풀어 오른다","correct":true},{"t":"쭈그러든다","mis":"SC4-2-u3-X13"},{"t":"그대로이다","mis":"SC4-2-u3-X14"},{"t":"터져서 사라진다","mis":"SC4-2-u3-X14"}],"explanation":["②를 읽어요.","온도가 높아져요.","부풀어 올라요."],"asset":{"type":"passage","lines":["① 포일 풍선 안에 공기를 넣고 입구를 잘 닫아요.","② 수조에 넣고 머리 말리개로 따뜻한 바람을 쏘여요.","③ 얼음이 담긴 수조에 넣고 뚜껑을 덮어요."],"title":"포일 풍선 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#3','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C10',1,'sa','auto','③처럼 얼음이 담긴 수조에 넣으면 포일 풍선 안에 든 기체의 부피는 늘어나나요, 줄어드나요? 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"sa","stem":"③처럼 얼음이 담긴 수조에 넣으면 포일 풍선 안에 든 기체의 부피는 늘어나나요, 줄어드나요? 알맞은 말을 쓰세요.","answer":["줄어든다","줄어들어요","줄어들다","줄어듦","줄어들어"],"explanation":["③을 읽어요.","온도가 낮아져요.","줄어들어요."],"asset":{"type":"passage","lines":["① 포일 풍선 안에 공기를 넣고 입구를 잘 닫아요.","② 수조에 넣고 머리 말리개로 따뜻한 바람을 쏘여요.","③ 얼음이 담긴 수조에 넣고 뚜껑을 덮어요."],"title":"포일 풍선 실험"},"mis":"SC4-2-u3-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#4','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C12',1,'ox','auto','얼음은 시원하니 조금 맛보아도 괜찮아요.',ARRAY['SC4-2-u3-X17']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C12","difficulty":1,"kind":"ox","stem":"얼음은 시원하니 조금 맛보아도 괜찮아요.","answer":"X","reason_options":[{"t":"실험에 쓰는 얼음은 맛보거나 먹지 않기 때문에","correct":true},{"t":"얼음은 실험이 끝나면 먹어도 되기 때문에","mis":"SC4-2-u3-X17"}],"mis":"SC4-2-u3-X17","explanation":["안전을 떠올려요.","실험 재료예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#5','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C11',2,'match','auto','한 일과 쓴 준비물을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C11","difficulty":2,"kind":"match","stem":"한 일과 쓴 준비물을 알맞게 이으세요.","pairs":[{"l":"포일 풍선 안에 공기를 넣어요","r":"공기 주입기"},{"l":"포일 풍선에 따뜻한 바람을 쏘여요","r":"머리 말리개"},{"l":"포일 풍선을 차갑게 해요","r":"얼음이 담긴 수조"},{"l":"머리 말리개나 얼음을 다룰 때 손을 보호해요","r":"면장갑"}],"mis":"SC4-2-u3-X15","explanation":["실험 차례를 떠올려요.","준비물마다 쓰임이 있어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#6','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C11',2,'mc','auto','포일 풍선의 입구를 잘 닫는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X15','SC4-2-u3-X16']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C11","difficulty":2,"kind":"mc","stem":"포일 풍선의 입구를 잘 닫는 까닭은 무엇인가요?","options":[{"t":"바람이 들어가거나 공기가 빠져나가지 않게 해서 풍선 안에 든 기체의 변화를 보기 위해서","correct":true},{"t":"머리 말리개 바람을 풍선 안에 넣기 위해서","mis":"SC4-2-u3-X15"},{"t":"풍선의 정확한 크기를 재기 위해서","mis":"SC4-2-u3-X16"},{"t":"얼음이 풍선 안으로 들어가게 하기 위해서","mis":"SC4-2-u3-X15"}],"explanation":["①을 읽어요.","안에 든 기체만 살펴요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 포일 풍선 안에 공기를 넣고 입구를 잘 닫아요.","② 수조에 넣고 머리 말리개로 따뜻한 바람을 쏘여요.","③ 얼음이 담긴 수조에 넣고 뚜껑을 덮어요."],"title":"포일 풍선 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#7','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C12',2,'mc','auto','포일 풍선 실험을 할 때 지켜야 할 일은 무엇인가요?',ARRAY['SC4-2-u3-X17']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C12","difficulty":2,"kind":"mc","stem":"포일 풍선 실험을 할 때 지켜야 할 일은 무엇인가요?","options":[{"t":"머리 말리개를 피부나 풍선에 가까이 하지 않는다","correct":true},{"t":"머리 말리개를 풍선에 바짝 대어 빨리 따뜻하게 한다","mis":"SC4-2-u3-X17"},{"t":"풍선에 공기를 최대한 가득 넣는다","mis":"SC4-2-u3-X17"},{"t":"얼음을 조금 맛본다","mis":"SC4-2-u3-X17"}],"explanation":["안전 셋을 떠올려요.","뜨거운 바람이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#8','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C13',2,'mc','auto','커다란 열기구가 부풀어 오르는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X18','SC4-2-u3-X15']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C13","difficulty":2,"kind":"mc","stem":"커다란 열기구가 부풀어 오르는 까닭은 무엇인가요?","options":[{"t":"아래쪽을 가열해 안에 든 기체의 온도가 높아지면서 부피가 늘어나기 때문에","correct":true},{"t":"아래쪽을 차갑게 해서 부피가 늘어나기 때문에","mis":"SC4-2-u3-X18"},{"t":"열기구가 무거워지기 때문에","mis":"SC4-2-u3-X18"},{"t":"사람이 입으로 바람을 불어 넣기 때문에","mis":"SC4-2-u3-X15"}],"explanation":["열기구 아래쪽을 떠올려요.","불로 가열해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#9','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C13',2,'ox','auto','추운 겨울날 풍선을 바깥에 두면 풍선이 쭈그러들어요.',ARRAY['SC4-2-u3-X18']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C13","difficulty":2,"kind":"ox","stem":"추운 겨울날 풍선을 바깥에 두면 풍선이 쭈그러들어요.","answer":"O","reason_options":[{"t":"풍선 안 기체의 온도가 낮아져 부피가 줄어들기 때문에","correct":true},{"t":"바깥에 두면 풍선 안 기체의 부피가 늘어나기 때문에","mis":"SC4-2-u3-X18"}],"mis":"SC4-2-u3-X18","explanation":["추운 바깥을 떠올려요.","온도가 낮아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_basic#10','sci',4,2,'u3','L03','g4_2_sci_u3_L03_basic','lesson_basic','SC4-2-u3-C13',3,'mc','auto','물이 조금 든 페트병을 따뜻한 방에 두었다가 냉장고 안에 넣어 두면 어떻게 될까요?',ARRAY['SC4-2-u3-X18','SC4-2-u3-X14']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C13","difficulty":3,"kind":"mc","stem":"물이 조금 든 페트병을 따뜻한 방에 두었다가 냉장고 안에 넣어 두면 어떻게 될까요?","options":[{"t":"페트병 안 공기의 온도가 낮아지면서 부피가 줄어들어 페트병이 쭈그러든다","correct":true},{"t":"페트병 안 공기의 부피가 늘어나 페트병이 부풀어 오른다","mis":"SC4-2-u3-X18"},{"t":"물이 들어 있어서 아무 변화가 없다","mis":"SC4-2-u3-X18"},{"t":"뚜껑을 닫았으니 공기의 부피는 그대로이다","mis":"SC4-2-u3-X14"}],"explanation":["냉장고 안은 차가워요.","안의 공기가 차가워져요.","쭈그러들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#1','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C10',2,'blank','auto','「온도가 낮아지면 기체의 부피가 (    ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C10","difficulty":2,"kind":"blank","stem":"「온도가 낮아지면 기체의 부피가 (    ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"줄어들어요","correct":true},{"t":"늘어나요","mis":"SC4-2-u3-X13"},{"t":"그대로예요","mis":"SC4-2-u3-X14"},{"t":"무거워져요","mis":"SC4-2-u3-X14"}],"explanation":["얼음 수조를 떠올려요.","쭈그러들었어요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#2','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C12',2,'mc','auto','포일 풍선에 공기를 넣을 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u3-X17','SC4-2-u3-X15']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C12","difficulty":2,"kind":"mc","stem":"포일 풍선에 공기를 넣을 때 알맞은 방법은 무엇인가요?","options":[{"t":"풍선이 덜 팽팽해질 만큼만 넣는다","correct":true},{"t":"터지기 직전까지 가득 넣는다","mis":"SC4-2-u3-X17"},{"t":"머리 말리개로 바람을 불어 넣는다","mis":"SC4-2-u3-X15"},{"t":"풍선 안에 얼음을 함께 넣는다","mis":"SC4-2-u3-X17"}],"explanation":["터지지 않게 해요.","조금 여유를 둬요.","덜 팽팽할 만큼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#3','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C11',3,'error','auto','포일 풍선이 부풀어 오른 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X15','SC4-2-u3-X13']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C11","difficulty":3,"kind":"error","stem":"포일 풍선이 부풀어 오른 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「머리 말리개의 바람이 풍선 안으로 들어가서 커졌어.」","correct":true,"mis_target":"SC4-2-u3-X15"},{"t":"친구 가 — 「입구를 잘 닫았으니 바람은 들어가지 않았어.」","mis":"SC4-2-u3-X15"},{"t":"친구 다 — 「따뜻해지니 풍선 안 기체의 부피가 늘어났어.」","mis":"SC4-2-u3-X13"}],"explanation":["입구를 떠올려요.","잘 닫았어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#4','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C10',3,'mc','auto','따뜻하게 할 때와 차갑게 할 때를 바르게 짝지은 것은 무엇인가요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C10","difficulty":3,"kind":"mc","stem":"따뜻하게 할 때와 차갑게 할 때를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"따뜻하게 — 부피가 늘어난다 / 차갑게 — 부피가 줄어든다","correct":true},{"t":"따뜻하게 — 부피가 줄어든다 / 차갑게 — 부피가 늘어난다","mis":"SC4-2-u3-X13"},{"t":"따뜻하게 — 부피가 늘어난다 / 차갑게 — 부피가 늘어난다","mis":"SC4-2-u3-X14"},{"t":"따뜻하게 — 그대로이다 / 차갑게 — 그대로이다","mis":"SC4-2-u3-X14"}],"explanation":["두 실험을 견줘요.","방향이 반대예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#5','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C13',3,'mc','auto','추운 바깥에서 쭈그러든 풍선을 따뜻한 실내로 가져오면 어떻게 될까요?',ARRAY['SC4-2-u3-X18','SC4-2-u3-X15']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C13","difficulty":3,"kind":"mc","stem":"추운 바깥에서 쭈그러든 풍선을 따뜻한 실내로 가져오면 어떻게 될까요?","options":[{"t":"온도가 높아지면서 다시 팽팽해진다","correct":true},{"t":"더 쭈그러든다","mis":"SC4-2-u3-X18"},{"t":"한 번 쭈그러들면 그대로이다","mis":"SC4-2-u3-X18"},{"t":"풍선 안의 공기가 모두 빠져나간다","mis":"SC4-2-u3-X15"}],"explanation":["실내는 따뜻해요.","온도가 높아져요.","다시 팽팽해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#6','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C11',3,'ox','auto','포일 풍선의 크기를 자로 재어 정확하게 그리는 것이 가장 중요해요.',ARRAY['SC4-2-u3-X16']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C11","difficulty":3,"kind":"ox","stem":"포일 풍선의 크기를 자로 재어 정확하게 그리는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"풍선 안 기체의 부피가 어떻게 변하는지 살피는 것이 중요하기 때문에","correct":true},{"t":"정확한 크기를 알아야 실험이 끝나기 때문에","mis":"SC4-2-u3-X16"}],"mis":"SC4-2-u3-X16","explanation":["무엇을 관찰하나요?","변하는 모습이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#7','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C12',3,'mc','auto','얼음이 담긴 수조를 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u3-X17','SC4-2-u3-X15']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C12","difficulty":3,"kind":"mc","stem":"얼음이 담긴 수조를 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"얼음은 수조 바닥을 채울 만큼만 넣고, 풍선을 넣은 뒤 뚜껑을 덮어 잠시 둔다","correct":true},{"t":"얼음을 맛보며 수조에 넣는다","mis":"SC4-2-u3-X17"},{"t":"맨손으로 얼음을 꽉 쥐고 있는다","mis":"SC4-2-u3-X17"},{"t":"얼음을 풍선 안에 넣는다","mis":"SC4-2-u3-X15"}],"explanation":["③을 떠올려요.","바닥을 채울 만큼이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#8','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C13',4,'mc','auto','친구가 「냉장고에 넣은 페트병은 뚜껑을 닫았으니 아무 변화가 없을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X18','SC4-2-u3-X13']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C13","difficulty":4,"kind":"mc","stem":"친구가 「냉장고에 넣은 페트병은 뚜껑을 닫았으니 아무 변화가 없을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「뚜껑을 닫아도 안에 든 공기의 온도가 낮아지면 부피가 줄어 페트병이 쭈그러들어.」","correct":true},{"t":"「맞아, 닫아 두면 그대로야.」","mis":"SC4-2-u3-X18"},{"t":"「차가워지면 부풀어 올라.」","mis":"SC4-2-u3-X13"},{"t":"「물이 들어 있으면 변하지 않아.」","mis":"SC4-2-u3-X18"}],"explanation":["입구를 닫은 포일 풍선을 떠올려요.","닫아도 변했어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#9','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C10',4,'mc','auto','친구가 「포일 풍선이 커진 건 따뜻해서고, 작아진 건 바람이 빠져서야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X15','SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C10","difficulty":4,"kind":"mc","stem":"친구가 「포일 풍선이 커진 건 따뜻해서고, 작아진 건 바람이 빠져서야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「입구를 잘 닫았으니 빠진 게 아니야. 온도가 낮아져서 안에 든 기체의 부피가 줄어든 거야.」","correct":true},{"t":"「맞아, 바람이 빠졌어.」","mis":"SC4-2-u3-X15"},{"t":"「차가워지면 기체의 부피가 늘어나.」","mis":"SC4-2-u3-X13"},{"t":"「풍선은 온도와 상관없어.」","mis":"SC4-2-u3-X14"}],"explanation":["입구를 떠올려요.","닫혀 있었어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L03_challenge#10','sci',4,2,'u3','L03','g4_2_sci_u3_L03_challenge','lesson_challenge','SC4-2-u3-C10',4,'essay','teacher','포일 풍선을 따뜻하게 할 때와 차갑게 할 때 풍선 안에 든 기체의 부피가 어떻게 변하는지 쓰고, 「바람이 들어가서 커졌다」는 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C10","difficulty":4,"kind":"essay","stem":"포일 풍선을 따뜻하게 할 때와 차갑게 할 때 풍선 안에 든 기체의 부피가 어떻게 변하는지 쓰고, 「바람이 들어가서 커졌다」는 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 따뜻하게 하면 온도가 높아져 기체의 부피가 늘어나 풍선이 부풀어 오르고, 차갑게 하면 온도가 낮아져 부피가 줄어들어 풍선이 쭈그러든다. 입구를 잘 닫았으므로 바람이 들어간 것이 아니라 풍선 안에 든 기체의 부피가 늘어난 것이다.","scoring_points":["따뜻하게 할 때의 변화를 썼는가","차갑게 할 때의 변화를 썼는가","바람이 들어간 것이 아님을 바르게 고쳤는가"]},"explanation":["두 실험을 떠올려요.","부피 변화를 써요.","고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_basic#1','sci',4,2,'u3','L04','g4_2_sci_u3_L04_basic','lesson_basic','SC4-2-u3-C14',1,'mc','auto','「압력」은 무엇을 말하나요?',ARRAY['SC4-2-u3-X19']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C14","difficulty":1,"kind":"mc","stem":"「압력」은 무엇을 말하나요?","options":[{"t":"누르는 힘","correct":true},{"t":"따뜻한 정도","mis":"SC4-2-u3-X19"},{"t":"물체의 크기","mis":"SC4-2-u3-X19"},{"t":"물체의 색깔","mis":"SC4-2-u3-X19"}],"explanation":["피스톤을 떠올려요.","손으로 눌러요.","누르는 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_basic#2','sci',4,2,'u3','L04','g4_2_sci_u3_L04_basic','lesson_basic','SC4-2-u3-C15',1,'mc','auto','②에서 피스톤을 누르면 주사기 안 공기의 부피는 어떻게 되나요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X24']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C15","difficulty":1,"kind":"mc","stem":"②에서 피스톤을 누르면 주사기 안 공기의 부피는 어떻게 되나요?","options":[{"t":"줄어든다","correct":true},{"t":"늘어난다","mis":"SC4-2-u3-X20"},{"t":"그대로이다","mis":"SC4-2-u3-X20"},{"t":"공기가 사라진다","mis":"SC4-2-u3-X24"}],"explanation":["②를 떠올려요.","눌러요.","줄어들어요."],"asset":{"type":"passage","lines":["① 주사기에 공기를 넣고 입구를 주사기 마개로 막아요.","② 피스톤을 눌렀다가 당겨 보아요.","③ 공기가 든 작은 고무풍선을 넣고 다시 마개로 막아요.","④ 피스톤을 눌렀다가 당겨 보아요."],"title":"주사기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
