INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_basic#4','sci',4,2,'u3','L04','g4_2_sci_u3_L04_basic','lesson_basic','SC4-2-u3-C16',1,'sa','auto','①에서 주사기의 입구를 막는 데 쓴 것은 무엇인가요?','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C16","difficulty":1,"kind":"sa","stem":"①에서 주사기의 입구를 막는 데 쓴 것은 무엇인가요?","answer":["주사기 마개","주사기마개","마개"],"explanation":["①을 읽어요.","입구를 막아요.","주사기 마개예요."],"asset":{"type":"passage","lines":["① 주사기에 공기를 넣고 입구를 주사기 마개로 막아요.","② 피스톤을 눌렀다가 당겨 보아요.","③ 공기가 든 작은 고무풍선을 넣고 다시 마개로 막아요.","④ 피스톤을 눌렀다가 당겨 보아요."],"title":"주사기 실험"},"mis":"SC4-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
