INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#1','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C14',2,'blank','auto','「주사기의 피스톤을 세게 누를수록 기체에 미치는 (    )이/가 높아져요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X19']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C14","difficulty":2,"kind":"blank","stem":"「주사기의 피스톤을 세게 누를수록 기체에 미치는 (    )이/가 높아져요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"압력","correct":true},{"t":"온도","mis":"SC4-2-u3-X19"},{"t":"무게","mis":"SC4-2-u3-X19"},{"t":"크기","mis":"SC4-2-u3-X19"}],"explanation":["누르는 힘이에요.","두 글자예요.","압력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#2','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C17',2,'mc','auto','호핑볼을 타고 위로 뛰어오르는 순간 호핑볼은 어떻게 될까요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X24']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C17","difficulty":2,"kind":"mc","stem":"호핑볼을 타고 위로 뛰어오르는 순간 호핑볼은 어떻게 될까요?","options":[{"t":"압력이 낮아지면서 부피가 늘어난다","correct":true},{"t":"압력이 높아지면서 부피가 늘어난다","mis":"SC4-2-u3-X20"},{"t":"압력이 낮아지면서 부피가 줄어든다","mis":"SC4-2-u3-X24"},{"t":"공기가 빠져나가 사라진다","mis":"SC4-2-u3-X24"}],"explanation":["뛰어오르면 누르지 않아요.","압력이 낮아져요.","늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#3','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C15',3,'error','auto','④를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X21','SC4-2-u3-X20']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C15","difficulty":3,"kind":"error","stem":"④를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「풍선은 피스톤에 닿지 않았으니 크기가 그대로야.」","correct":true,"mis_target":"SC4-2-u3-X21"},{"t":"친구 가 — 「피스톤을 누르니 풍선도 작아졌어.」","mis":"SC4-2-u3-X20"},{"t":"친구 나 — 「피스톤을 당기니 공기와 풍선의 부피가 함께 늘어났어.」","mis":"SC4-2-u3-X20"}],"explanation":["④를 떠올려요.","닿지 않아도 달라졌어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 주사기에 공기를 넣고 입구를 주사기 마개로 막아요.","② 피스톤을 눌렀다가 당겨 보아요.","③ 공기가 든 작은 고무풍선을 넣고 다시 마개로 막아요.","④ 피스톤을 눌렀다가 당겨 보아요."],"title":"주사기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#4','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C16',3,'mc','auto','이 실험에서 가장 중요하게 살펴야 할 것은 무엇인가요?',ARRAY['SC4-2-u3-X23','SC4-2-u3-X22']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C16","difficulty":3,"kind":"mc","stem":"이 실험에서 가장 중요하게 살펴야 할 것은 무엇인가요?","options":[{"t":"피스톤을 누르고 당길 때 기체의 부피가 어떻게 변하는지","correct":true},{"t":"주사기 눈금의 숫자를 정확히 읽는 것","mis":"SC4-2-u3-X23"},{"t":"풍선의 색깔이 무엇인지","mis":"SC4-2-u3-X23"},{"t":"피스톤을 누가 가장 빨리 누르는지","mis":"SC4-2-u3-X22"}],"explanation":["무엇을 알아보는 실험인가요?","부피의 변화예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#5','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C17',3,'mc','auto','밑창에 공기 주머니가 든 운동화를 신고 발로 땅을 디딜 때 공기 주머니는 어떻게 될까요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X24']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C17","difficulty":3,"kind":"mc","stem":"밑창에 공기 주머니가 든 운동화를 신고 발로 땅을 디딜 때 공기 주머니는 어떻게 될까요?","options":[{"t":"압력이 높아지면서 공기 주머니의 부피가 줄어든다","correct":true},{"t":"압력이 높아지면서 공기 주머니의 부피가 늘어난다","mis":"SC4-2-u3-X20"},{"t":"밑창 속에 있어서 변하지 않는다","mis":"SC4-2-u3-X24"},{"t":"걸을 때마다 공기가 빠져나가 사라진다","mis":"SC4-2-u3-X24"}],"explanation":["디딜 때 눌러요.","압력이 높아져요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#6','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C16',3,'ox','auto','주사기 입구를 막지 않고 피스톤을 눌러도 같은 결과를 볼 수 있어요.',ARRAY['SC4-2-u3-X22']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C16","difficulty":3,"kind":"ox","stem":"주사기 입구를 막지 않고 피스톤을 눌러도 같은 결과를 볼 수 있어요.","answer":"X","reason_options":[{"t":"입구가 열려 있으면 공기가 밖으로 빠져나가기 때문에","correct":true},{"t":"입구는 실험과 상관없기 때문에","mis":"SC4-2-u3-X22"}],"mis":"SC4-2-u3-X22","explanation":["①을 떠올려요.","마개로 막았어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#7','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C15',3,'mc','auto','④에서 피스톤을 당겼을 때 알맞은 결과는 무엇인가요?',ARRAY['SC4-2-u3-X21','SC4-2-u3-X20']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C15","difficulty":3,"kind":"mc","stem":"④에서 피스톤을 당겼을 때 알맞은 결과는 무엇인가요?","options":[{"t":"주사기 안 공기와 풍선의 부피가 함께 늘어난다","correct":true},{"t":"공기만 늘어나고 풍선은 그대로이다","mis":"SC4-2-u3-X21"},{"t":"공기와 풍선의 부피가 함께 줄어든다","mis":"SC4-2-u3-X20"},{"t":"공기와 풍선 모두 그대로이다","mis":"SC4-2-u3-X20"}],"explanation":["당기면 압력이 낮아져요.","함께 달라져요.","함께 늘어나요."],"asset":{"type":"passage","lines":["① 주사기에 공기를 넣고 입구를 주사기 마개로 막아요.","② 피스톤을 눌렀다가 당겨 보아요.","③ 공기가 든 작은 고무풍선을 넣고 다시 마개로 막아요.","④ 피스톤을 눌렀다가 당겨 보아요."],"title":"주사기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#8','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C17',4,'mc','auto','친구가 「배구공이 찌그러진 건 공 안 공기가 다 빠져나갔기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X24','SC4-2-u3-X20']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C17","difficulty":4,"kind":"mc","stem":"친구가 「배구공이 찌그러진 건 공 안 공기가 다 빠져나갔기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「세게 칠 때 압력이 높아져 공 안 기체의 부피가 줄어든 거야. 공기가 빠져나간 게 아니야.」","correct":true},{"t":"「맞아, 공기가 다 빠져나갔어.」","mis":"SC4-2-u3-X24"},{"t":"「압력이 높아지면 부피가 늘어나서야.」","mis":"SC4-2-u3-X20"},{"t":"「배구공은 압력과 상관없어.」","mis":"SC4-2-u3-X20"}],"explanation":["세게 칠 때를 떠올려요.","압력이 높아져요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#9','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C14',4,'mc','auto','마개로 막은 주사기의 피스톤을 더 세게 누를수록 어떻게 될까요?',ARRAY['SC4-2-u3-X19','SC4-2-u3-X20']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C14","difficulty":4,"kind":"mc","stem":"마개로 막은 주사기의 피스톤을 더 세게 누를수록 어떻게 될까요?","options":[{"t":"기체에 미치는 압력이 더 높아지고 부피가 더 줄어든다","correct":true},{"t":"압력이 낮아지고 부피가 늘어난다","mis":"SC4-2-u3-X19"},{"t":"압력은 높아지지만 부피는 그대로이다","mis":"SC4-2-u3-X20"},{"t":"누르는 세기와 상관없이 똑같다","mis":"SC4-2-u3-X19"}],"explanation":["세게 누를수록 압력이 커요.","부피는 반대로 가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L04_challenge#10','sci',4,2,'u3','L04','g4_2_sci_u3_L04_challenge','lesson_challenge','SC4-2-u3-C15',4,'essay','teacher','피스톤을 누를 때와 당길 때 주사기 안 공기와 풍선의 부피가 어떻게 변하는지 쓰고, 압력과 기체의 부피 사이의 관계를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C15","difficulty":4,"kind":"essay","stem":"피스톤을 누를 때와 당길 때 주사기 안 공기와 풍선의 부피가 어떻게 변하는지 쓰고, 압력과 기체의 부피 사이의 관계를 쓰세요.","answer_guide":{"answer":"예: 피스톤을 누르면 압력이 높아져 주사기 안 공기와 풍선의 부피가 함께 줄어들고, 피스톤을 당기면 압력이 낮아져 공기와 풍선의 부피가 함께 늘어난다. 기체에 미치는 압력이 높아지면 기체의 부피가 줄어들고, 압력이 낮아지면 기체의 부피가 늘어난다.","scoring_points":["누를 때의 변화를 썼는가","당길 때의 변화를 썼는가","압력과 부피의 관계를 썼는가"]},"explanation":["두 경우를 떠올려요.","변화를 써요.","관계를 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#1','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C18',1,'mc','auto','㉮의 튜브와 비치 볼은 어떻게 되나요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X27']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C18","difficulty":1,"kind":"mc","stem":"㉮의 튜브와 비치 볼은 어떻게 되나요?","options":[{"t":"팽팽해진다","correct":true},{"t":"쭈그러든다","mis":"SC4-2-u3-X25"},{"t":"그대로이다","mis":"SC4-2-u3-X27"},{"t":"공기가 모두 빠져나간다","mis":"SC4-2-u3-X27"}],"explanation":["㉮를 읽어요.","땡볕은 뜨거워요.","팽팽해져요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#2','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C18',1,'mc','auto','온도가 높아지면 비치 볼 안에 든 기체의 부피는 어떻게 될까요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X27']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C18","difficulty":1,"kind":"mc","stem":"온도가 높아지면 비치 볼 안에 든 기체의 부피는 어떻게 될까요?","options":[{"t":"늘어난다","correct":true},{"t":"줄어든다","mis":"SC4-2-u3-X25"},{"t":"그대로이다","mis":"SC4-2-u3-X27"},{"t":"비치 볼은 물에서만 달라진다","mis":"SC4-2-u3-X27"}],"explanation":["온도가 높아질 때를 떠올려요.","부피가 커져요.","늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#3','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C20',1,'ox','auto','조사한 정보는 출처를 확인하고 옳은 정보와 거짓 정보를 구분해요.',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C20","difficulty":1,"kind":"ox","stem":"조사한 정보는 출처를 확인하고 옳은 정보와 거짓 정보를 구분해요.","answer":"O","reason_options":[{"t":"누리망에는 거짓 정보도 있기 때문에","correct":true},{"t":"누리망 정보는 모두 옳기 때문에","mis":"SC4-2-u3-X28"}],"mis":"SC4-2-u3-X28","explanation":["조사할 때를 떠올려요.","거짓 정보도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#4','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C19',1,'sa','auto','㉱에서 비닐 랩이 오목해진 까닭은 온도가 어떻게 되었기 때문인가요? 「온도가 ○○졌다」의 ○○를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C19","difficulty":1,"kind":"sa","stem":"㉱에서 비닐 랩이 오목해진 까닭은 온도가 어떻게 되었기 때문인가요? 「온도가 ○○졌다」의 ○○를 쓰세요.","answer":["낮아"],"explanation":["냉장고 안을 떠올려요.","차가워요.","낮아졌어요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"},"mis":"SC4-2-u3-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#5','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C18',2,'match','auto','그림의 상황과 달라진 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C18","difficulty":2,"kind":"match","stem":"그림의 상황과 달라진 모습을 알맞게 이으세요.","pairs":[{"l":"땡볕 아래 튜브와 비치 볼","r":"팽팽해져요"},{"l":"아이가 앉아 있는 에어 매트","r":"납작해져요"},{"l":"발로 세게 찬 축구공","r":"순간적으로 찌그러져요"},{"l":"냉장고에서 꺼낸 용기","r":"비닐 랩이 오목해져요"}],"mis":"SC4-2-u3-X27","explanation":["그림을 하나씩 살펴요.","늘어난 것과 줄어든 것이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#6','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C19',2,'mc','auto','㉯의 에어 매트가 납작해진 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X20']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C19","difficulty":2,"kind":"mc","stem":"㉯의 에어 매트가 납작해진 까닭은 무엇인가요?","options":[{"t":"압력이 높아졌기 때문에","correct":true},{"t":"온도가 높아졌기 때문에","mis":"SC4-2-u3-X25"},{"t":"온도가 낮아졌기 때문에","mis":"SC4-2-u3-X25"},{"t":"압력이 낮아졌기 때문에","mis":"SC4-2-u3-X20"}],"explanation":["아이가 앉아 있어요.","몸으로 눌러요.","압력이 높아졌어요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#7','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C18',2,'mc','auto','자동차에 짐을 많이 실으면 타이어는 어떻게 되나요?',ARRAY['SC4-2-u3-X27','SC4-2-u3-X25']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C18","difficulty":2,"kind":"mc","stem":"자동차에 짐을 많이 실으면 타이어는 어떻게 되나요?","options":[{"t":"압력이 높아지면서 타이어 안 공기의 부피가 줄어들어 찌그러진다","correct":true},{"t":"타이어 안 공기의 부피가 늘어나 더 팽팽해진다","mis":"SC4-2-u3-X27"},{"t":"온도가 낮아져서 타이어가 찌그러진다","mis":"SC4-2-u3-X25"},{"t":"짐을 실어도 타이어는 그대로이다","mis":"SC4-2-u3-X27"}],"explanation":["짐이 타이어를 눌러요.","압력이 높아져요.","찌그러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#8','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C20',2,'mc','auto','조사한 정보를 다룰 때 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C20","difficulty":2,"kind":"mc","stem":"조사한 정보를 다룰 때 알맞은 것은 무엇인가요?","options":[{"t":"다른 사람에게 전달해도 되는 내용인지 판단한다","correct":true},{"t":"찾은 정보는 무엇이든 바로 다른 사람에게 전한다","mis":"SC4-2-u3-X28"},{"t":"출처를 보지 않고 그대로 옮겨 쓴다","mis":"SC4-2-u3-X28"},{"t":"처음 찾은 정보만 옳다고 믿는다","mis":"SC4-2-u3-X28"}],"explanation":["조사의 규칙을 떠올려요.","전해도 되는지 살펴요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#9','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C19',2,'ox','auto','㉯ 에어 매트와 ㉱ 비닐 랩은 둘 다 부피가 줄어들었으니 까닭도 같아요.',ARRAY['SC4-2-u3-X26']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C19","difficulty":2,"kind":"ox","stem":"㉯ 에어 매트와 ㉱ 비닐 랩은 둘 다 부피가 줄어들었으니 까닭도 같아요.","answer":"X","reason_options":[{"t":"㉯는 압력이 높아져서, ㉱는 온도가 낮아져서 줄어들었기 때문에","correct":true},{"t":"줄어든 모습이 같으면 까닭도 같기 때문에","mis":"SC4-2-u3-X26"}],"mis":"SC4-2-u3-X26","explanation":["둘의 까닭을 따로 따져요.","하나는 압력, 하나는 온도예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_basic#10','sci',4,2,'u3','L05','g4_2_sci_u3_L05_basic','lesson_basic','SC4-2-u3-C19',3,'mc','auto','온도 때문에 기체의 부피가 달라진 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C19","difficulty":3,"kind":"mc","stem":"온도 때문에 기체의 부피가 달라진 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉮와 ㉱","correct":true},{"t":"㉯와 ㉰","mis":"SC4-2-u3-X25"},{"t":"㉮와 ㉯","mis":"SC4-2-u3-X25"},{"t":"㉰와 ㉱","mis":"SC4-2-u3-X25"}],"explanation":["땡볕과 냉장고를 찾아요.","앉기와 차기는 압력이에요.","㉮와 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#1','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C20',2,'blank','auto','「조사한 정보의 (    )을/를 확인하고 옳은 정보와 거짓 정보를 구분해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C20","difficulty":2,"kind":"blank","stem":"「조사한 정보의 (    )을/를 확인하고 옳은 정보와 거짓 정보를 구분해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출처","correct":true},{"t":"글자 수","mis":"SC4-2-u3-X28"},{"t":"글자 색","mis":"SC4-2-u3-X28"},{"t":"길이","mis":"SC4-2-u3-X28"}],"explanation":["어디에서 온 정보인지예요.","두 글자예요.","출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#2','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C18',2,'mc','auto','포개진 그릇의 바깥쪽 아랫부분을 뜨거운 물에 넣어 두면 어떻게 될까요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X27','SC4-2-u3-X15']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C18","difficulty":2,"kind":"mc","stem":"포개진 그릇의 바깥쪽 아랫부분을 뜨거운 물에 넣어 두면 어떻게 될까요?","options":[{"t":"두 그릇 사이 공기의 부피가 늘어나 그릇이 잘 빠진다","correct":true},{"t":"두 그릇 사이 공기의 부피가 줄어들어 더 꽉 낀다","mis":"SC4-2-u3-X13"},{"t":"그릇은 공기와 상관없이 그대로이다","mis":"SC4-2-u3-X27"},{"t":"뜨거운 물이 그릇 사이로 들어가 빠진다","mis":"SC4-2-u3-X15"}],"explanation":["뜨거운 물은 온도를 높여요.","부피가 늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#3','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C19',3,'error','auto','그림 ㉮~㉱를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X26']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C19","difficulty":3,"kind":"error","stem":"그림 ㉮~㉱를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉰ 축구공이 찌그러진 건 온도가 낮아졌기 때문이야.」","correct":true,"mis_target":"SC4-2-u3-X25"},{"t":"친구 나 — 「㉮는 온도가 높아져서 팽팽해졌어.」","mis":"SC4-2-u3-X25"},{"t":"친구 다 — 「㉯는 압력이 높아져서 납작해졌어.」","mis":"SC4-2-u3-X26"}],"explanation":["㉰를 떠올려요.","세게 찼어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#4','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C18',3,'mc','auto','공기 안전 매트 위로 뛰어내리면 어떻게 될까요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X24','SC4-2-u3-X27']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C18","difficulty":3,"kind":"mc","stem":"공기 안전 매트 위로 뛰어내리면 어떻게 될까요?","options":[{"t":"압력이 높아지면서 매트 안 공기의 부피가 줄어들어 움푹 들어간다","correct":true},{"t":"온도가 높아지면서 매트가 부풀어 오른다","mis":"SC4-2-u3-X25"},{"t":"매트 안의 공기가 모두 빠져나간다","mis":"SC4-2-u3-X24"},{"t":"매트는 그대로이다","mis":"SC4-2-u3-X27"}],"explanation":["뛰어내리면 눌러요.","압력이 높아져요.","움푹 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#5','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C19',3,'mc','auto','압력 때문에 기체의 부피가 달라진 예끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C19","difficulty":3,"kind":"mc","stem":"압력 때문에 기체의 부피가 달라진 예끼리 묶은 것은 무엇인가요?","options":[{"t":"에어 매트에 앉기, 축구공 세게 차기","correct":true},{"t":"땡볕에 튜브 두기, 냉장고에 랩 용기 넣기","mis":"SC4-2-u3-X25"},{"t":"땡볕에 튜브 두기, 에어 매트에 앉기","mis":"SC4-2-u3-X25"},{"t":"냉장고에 랩 용기 넣기, 축구공 세게 차기","mis":"SC4-2-u3-X25"}],"explanation":["누르는 힘을 찾아요.","앉기와 차기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#6','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C18',3,'ox','auto','땡볕에서 팽팽해진 비치 볼을 시원한 그늘로 옮기면 조금 작아져요.',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C18","difficulty":3,"kind":"ox","stem":"땡볕에서 팽팽해진 비치 볼을 시원한 그늘로 옮기면 조금 작아져요.","answer":"O","reason_options":[{"t":"온도가 낮아지면서 비치 볼 안 공기의 부피가 줄어들기 때문에","correct":true},{"t":"그늘에서는 압력이 높아지기 때문에","mis":"SC4-2-u3-X25"}],"mis":"SC4-2-u3-X25","explanation":["그늘은 시원해요.","온도가 낮아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#7','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C20',3,'mc','auto','스마트 기기로 생활 속 예를 조사하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C20","difficulty":3,"kind":"mc","stem":"스마트 기기로 생활 속 예를 조사하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"검색어를 정해 찾고, 출처를 확인하고, 전해도 되는 내용인지 판단한다","correct":true},{"t":"처음 나온 정보를 출처 없이 그대로 옮긴다","mis":"SC4-2-u3-X28"},{"t":"재미있는 정보라면 무엇이든 바로 퍼뜨린다","mis":"SC4-2-u3-X28"},{"t":"거짓 정보도 많이 모으면 옳은 정보가 된다","mis":"SC4-2-u3-X28"}],"explanation":["조사의 차례를 떠올려요.","출처와 판단이 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#8','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C19',4,'mc','auto','친구가 「부피가 줄어들었으면 모두 온도가 낮아진 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X26','SC4-2-u3-X25']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C19","difficulty":4,"kind":"mc","stem":"친구가 「부피가 줄어들었으면 모두 온도가 낮아진 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「모습이 같아도 까닭은 다를 수 있어. 에어 매트는 압력이 높아져서, 비닐 랩은 온도가 낮아져서 줄어들었어.」","correct":true},{"t":"「맞아, 모두 온도 때문이야.」","mis":"SC4-2-u3-X26"},{"t":"「모두 압력이 낮아져서야.」","mis":"SC4-2-u3-X25"},{"t":"「줄어든 까닭은 알 수 없어.」","mis":"SC4-2-u3-X26"}],"explanation":["㉯와 ㉱를 견줘요.","까닭이 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#9','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C18',4,'mc','auto','짐을 많이 실어 찌그러졌던 자동차 타이어에서 짐을 모두 내리면 어떻게 될까요?',ARRAY['SC4-2-u3-X27','SC4-2-u3-X25','SC4-2-u3-X20']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C18","difficulty":4,"kind":"mc","stem":"짐을 많이 실어 찌그러졌던 자동차 타이어에서 짐을 모두 내리면 어떻게 될까요?","options":[{"t":"압력이 낮아지면서 타이어 안 공기의 부피가 늘어나 다시 팽팽해진다","correct":true},{"t":"한 번 찌그러진 타이어는 그대로이다","mis":"SC4-2-u3-X27"},{"t":"온도가 높아져서 팽팽해진다","mis":"SC4-2-u3-X25"},{"t":"압력이 낮아지면서 더 찌그러진다","mis":"SC4-2-u3-X20"}],"explanation":["짐이 없으면 덜 눌러요.","압력이 낮아져요.","다시 팽팽해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L05_challenge#10','sci',4,2,'u3','L05','g4_2_sci_u3_L05_challenge','lesson_challenge','SC4-2-u3-C19',4,'essay','teacher','그림 ㉮~㉱ 가운데 두 가지를 골라 기체의 부피가 어떻게 달라졌는지 쓰고, 그 까닭을 「온도/압력」과 「높아짐/낮아짐」으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C19","difficulty":4,"kind":"essay","stem":"그림 ㉮~㉱ 가운데 두 가지를 골라 기체의 부피가 어떻게 달라졌는지 쓰고, 그 까닭을 「온도/압력」과 「높아짐/낮아짐」으로 쓰세요.","answer_guide":{"answer":"예: ㉮ 튜브와 비치 볼은 기체의 부피가 늘어나 팽팽해졌는데, 온도가 높아졌기 때문이다. ㉯ 에어 매트는 기체의 부피가 줄어들어 납작해졌는데, 압력이 높아졌기 때문이다.","scoring_points":["두 가지의 부피 변화를 썼는가","온도인지 압력인지 바르게 썼는가","높아졌는지 낮아졌는지 바르게 썼는가"]},"explanation":["그림을 골라요.","변화를 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 땡볕 아래 놓아 둔 튜브와 비치 볼","㉯ 아이가 앉아 있는 에어 매트","㉰ 축구 선수가 발로 세게 찬 축구공","㉱ 냉장고에서 꺼낸, 비닐 랩을 씌운 용기"],"title":"그림 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#1','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C21',1,'mc','auto','과자 봉지의 제품 설명에서 찾을 수 있는 기체는 무엇인가요?',ARRAY['SC4-2-u3-X30','SC4-2-u3-X29']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C21","difficulty":1,"kind":"mc","stem":"과자 봉지의 제품 설명에서 찾을 수 있는 기체는 무엇인가요?","options":[{"t":"질소","correct":true},{"t":"산소","mis":"SC4-2-u3-X30"},{"t":"이산화 탄소","mis":"SC4-2-u3-X30"},{"t":"수소","mis":"SC4-2-u3-X29"}],"explanation":["과자 봉지를 떠올려요.","포장할 때 넣어요.","질소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#2','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C24',1,'mc','auto','탄산음료의 톡 쏘는 맛을 내는 기체는 무엇인가요?',ARRAY['SC4-2-u3-X33','SC4-2-u3-X29']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C24","difficulty":1,"kind":"mc","stem":"탄산음료의 톡 쏘는 맛을 내는 기체는 무엇인가요?","options":[{"t":"이산화 탄소","correct":true},{"t":"질소","mis":"SC4-2-u3-X33"},{"t":"산소","mis":"SC4-2-u3-X33"},{"t":"수소","mis":"SC4-2-u3-X29"}],"explanation":["톡 쏘는 맛을 떠올려요.","탄산음료예요.","이산화 탄소예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소","산소 캔 — 산소","탄산음료 — 이산화 탄소"],"title":"제품 설명에서 찾은 기체"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#3','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C21',1,'ox','auto','제품 속 기체를 찾을 때에는 준비물을 가지고 장난치지 않아요.',ARRAY['SC4-2-u3-X29']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C21","difficulty":1,"kind":"ox","stem":"제품 속 기체를 찾을 때에는 준비물을 가지고 장난치지 않아요.","answer":"O","reason_options":[{"t":"안전하게 활동해야 하기 때문에","correct":true},{"t":"준비물은 장난감이기 때문에","mis":"SC4-2-u3-X29"}],"mis":"SC4-2-u3-X29","explanation":["활동할 때를 떠올려요.","안전이 먼저예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#4','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C23',1,'sa','auto','생물의 호흡에 필요한 기체는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C23","difficulty":1,"kind":"sa","stem":"생물의 호흡에 필요한 기체는 무엇인가요? 두 글자로 쓰세요.","answer":["산소"],"explanation":["숨 쉴 때 필요해요.","산소 캔에 들어 있어요.","산소예요."],"mis":"SC4-2-u3-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#5','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C25',2,'match','auto','기체가 가진 성질과 쓰이는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C25","difficulty":2,"kind":"match","stem":"기체가 가진 성질과 쓰이는 곳을 알맞게 이으세요.","pairs":[{"l":"반응을 거의 하지 않는 안정된 성질","r":"식품의 포장"},{"l":"다른 물질이 타는 것을 돕는 성질","r":"로켓의 연료를 태울 때"},{"l":"물에 넣으면 톡 쏘는 맛이 나는 성질","r":"탄산음료"},{"l":"다른 물질이 타는 것을 막는 성질","r":"소화기"}],"mis":"SC4-2-u3-X34","explanation":["성질을 먼저 읽어요.","성질에 맞는 쓰임을 찾아요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#6','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C22',2,'mc','auto','질소를 넣어 식품을 포장하면 어떤 점이 좋을까요?',ARRAY['SC4-2-u3-X30']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C22","difficulty":2,"kind":"mc","stem":"질소를 넣어 식품을 포장하면 어떤 점이 좋을까요?","options":[{"t":"다른 물질과 반응을 거의 하지 않아 식품을 오랫동안 보관할 수 있다","correct":true},{"t":"식품에서 톡 쏘는 맛이 난다","mis":"SC4-2-u3-X30"},{"t":"식품이 잘 타도록 돕는다","mis":"SC4-2-u3-X30"},{"t":"식품이 포장 안에서 숨을 쉴 수 있다","mis":"SC4-2-u3-X30"}],"explanation":["질소의 성질을 떠올려요.","안정된 성질이에요.","오랫동안 보관해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#7','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C23',2,'mc','auto','산소의 성질로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X33']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C23","difficulty":2,"kind":"mc","stem":"산소의 성질로 알맞은 것은 무엇인가요?","options":[{"t":"다른 물질이 타는 것을 돕는다","correct":true},{"t":"다른 물질이 타는 것을 막는다","mis":"SC4-2-u3-X31"},{"t":"다른 물질과 반응을 거의 하지 않는다","mis":"SC4-2-u3-X31"},{"t":"물에 넣으면 톡 쏘는 맛이 난다","mis":"SC4-2-u3-X33"}],"explanation":["로켓 연료를 떠올려요.","태울 때 써요.","타는 것을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#8','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C24',2,'ox','auto','이산화 탄소는 다른 물질이 타는 것을 막는 성질이 있어 소화기에 이용돼요.',ARRAY['SC4-2-u3-X33']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C24","difficulty":2,"kind":"ox","stem":"이산화 탄소는 다른 물질이 타는 것을 막는 성질이 있어 소화기에 이용돼요.","answer":"O","reason_options":[{"t":"타는 것을 막는 성질에 맞게 이용하기 때문에","correct":true},{"t":"이산화 탄소는 다른 물질이 타는 것을 돕기 때문에","mis":"SC4-2-u3-X33"}],"mis":"SC4-2-u3-X33","explanation":["소화기를 떠올려요.","불을 끄는 데 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#9','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C21',2,'mc','auto','제품 속 기체를 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X29']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C21","difficulty":2,"kind":"mc","stem":"제품 속 기체를 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"제품 겉면이나 설명서를 돋보기로 살펴본다","correct":true},{"t":"겉면은 보지 않고 이름을 짐작해서 쓴다","mis":"SC4-2-u3-X29"},{"t":"제품의 색깔만 보고 정한다","mis":"SC4-2-u3-X29"},{"t":"제품을 흔들어 소리로 알아낸다","mis":"SC4-2-u3-X29"}],"explanation":["어디에 적혀 있을까요?","겉면과 설명서예요.","돋보기로 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_basic#10','sci',4,2,'u3','L06','g4_2_sci_u3_L06_basic','lesson_basic','SC4-2-u3-C25',3,'mc','auto','여러 가지 기체가 일상생활에서 이용되는 모습을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X34']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C25","difficulty":3,"kind":"mc","stem":"여러 가지 기체가 일상생활에서 이용되는 모습을 바르게 말한 것은 무엇인가요?","options":[{"t":"각각의 성질에 맞게 다양하게 이용된다","correct":true},{"t":"성질과 상관없이 아무 데나 이용된다","mis":"SC4-2-u3-X34"},{"t":"모든 기체가 한 가지 일에만 이용된다","mis":"SC4-2-u3-X34"},{"t":"이용 사례는 외우기만 하면 된다","mis":"SC4-2-u3-X34"}],"explanation":["세 기체를 떠올려요.","성질과 이용이 이어져요.","성질에 맞게 이용돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#1','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C23',2,'blank','auto','「산소는 사과나 배의 자른 면을 (    )으로 변하게 하는 성질이 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X31']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C23","difficulty":2,"kind":"blank","stem":"「산소는 사과나 배의 자른 면을 (    )으로 변하게 하는 성질이 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"갈색","correct":true},{"t":"초록색","mis":"SC4-2-u3-X31"},{"t":"하얀색","mis":"SC4-2-u3-X31"},{"t":"파란색","mis":"SC4-2-u3-X31"}],"explanation":["잘라 둔 사과를 떠올려요.","시간이 지나면 변해요.","갈색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#2','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C24',2,'mc','auto','발포 비타민을 물에 넣었을 때 나오는 기체와 그렇게 생각한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X30','SC4-2-u3-X31']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C24","difficulty":2,"kind":"mc","stem":"발포 비타민을 물에 넣었을 때 나오는 기체와 그렇게 생각한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"이산화 탄소 — 탄산음료처럼 톡 쏘는 맛이 나기 때문에","correct":true},{"t":"질소 — 톡 쏘는 맛이 나기 때문에","mis":"SC4-2-u3-X30"},{"t":"산소 — 불을 끄기 때문에","mis":"SC4-2-u3-X31"},{"t":"산소 — 반응을 거의 하지 않기 때문에","mis":"SC4-2-u3-X31"}],"explanation":["톡 쏘는 맛을 떠올려요.","탄산음료와 같아요.","이산화 탄소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#3','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C24',3,'error','auto','소화기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X32','SC4-2-u3-X33','SC4-2-u3-X31']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C24","difficulty":3,"kind":"error","stem":"소화기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「이산화 탄소는 물처럼 스스로 불을 꺼 버려.」","correct":true,"mis_target":"SC4-2-u3-X32"},{"t":"친구 가 — 「이산화 탄소는 다른 물질이 타는 것을 막아.」","mis":"SC4-2-u3-X33"},{"t":"친구 다 — 「그래서 소화기에 이산화 탄소를 이용해.」","mis":"SC4-2-u3-X31"}],"explanation":["이산화 탄소의 성질을 떠올려요.","타는 것을 막는 성질이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#4','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C23',3,'mc','auto','살아 있는 해산물을 포장할 때 산소를 넣으면 어떤 점이 좋을까요?',ARRAY['SC4-2-u3-X33','SC4-2-u3-X31']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C23","difficulty":3,"kind":"mc","stem":"살아 있는 해산물을 포장할 때 산소를 넣으면 어떤 점이 좋을까요?","options":[{"t":"산소는 생물의 호흡에 필요해서 해산물을 살아 있는 상태로 신선하게 보관할 수 있다","correct":true},{"t":"해산물에서 톡 쏘는 맛이 난다","mis":"SC4-2-u3-X33"},{"t":"산소는 반응을 거의 하지 않아 해산물이 변하지 않는다","mis":"SC4-2-u3-X31"},{"t":"포장 안에서 불이 붙지 않게 막아 준다","mis":"SC4-2-u3-X31"}],"explanation":["살아 있는 생물을 떠올려요.","숨을 쉬어야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#5','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C22',3,'mc','auto','온도와 압력이 크게 변하는 항공기 타이어 안에 넣는 기체로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X33','SC4-2-u3-X29']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C22","difficulty":3,"kind":"mc","stem":"온도와 압력이 크게 변하는 항공기 타이어 안에 넣는 기체로 알맞은 것은 무엇인가요?","options":[{"t":"질소","correct":true},{"t":"산소","mis":"SC4-2-u3-X31"},{"t":"이산화 탄소","mis":"SC4-2-u3-X33"},{"t":"수소","mis":"SC4-2-u3-X29"}],"explanation":["안정된 기체를 떠올려요.","반응을 거의 하지 않아요.","질소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#6','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C25',3,'ox','auto','기체가 어디에 이용되는지는 성질과 상관없이 외우기만 하면 돼요.',ARRAY['SC4-2-u3-X34']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C25","difficulty":3,"kind":"ox","stem":"기체가 어디에 이용되는지는 성질과 상관없이 외우기만 하면 돼요.","answer":"X","reason_options":[{"t":"기체는 각각의 성질에 맞게 이용되기 때문에","correct":true},{"t":"이용 사례는 성질과 관계없이 정해졌기 때문에","mis":"SC4-2-u3-X34"}],"mis":"SC4-2-u3-X34","explanation":["성질과 이용을 이어 봐요.","성질에 맞게 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#7','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C25',3,'mc','auto','여러 가지 기체를 조사하고 발표할 때 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X28','SC4-2-u3-X34']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C25","difficulty":3,"kind":"mc","stem":"여러 가지 기체를 조사하고 발표할 때 알맞은 것은 무엇인가요?","options":[{"t":"조사한 정보의 출처를 확인하고, 모둠 신문·뉴스·역할극·영상 가운데 발표 방법을 정한다","correct":true},{"t":"출처는 보지 않고 재미있는 내용만 옮긴다","mis":"SC4-2-u3-X28"},{"t":"다른 모둠 자료를 그대로 베낀다","mis":"SC4-2-u3-X28"},{"t":"기체 이름만 외워서 말한다","mis":"SC4-2-u3-X34"}],"explanation":["조사의 규칙을 떠올려요.","출처를 확인해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#8','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C23',4,'mc','auto','친구가 「껍질을 깎은 사과가 갈색이 되는 건 질소 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X30','SC4-2-u3-X32','SC4-2-u3-X31']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C23","difficulty":4,"kind":"mc","stem":"친구가 「껍질을 깎은 사과가 갈색이 되는 건 질소 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「산소가 자른 면을 갈색으로 변하게 하는 성질이 있어서야. 그래서 산소와 닿지 않게 용기에 담아 보관해.」","correct":true},{"t":"「맞아, 질소 때문이야.」","mis":"SC4-2-u3-X30"},{"t":"「이산화 탄소가 불을 꺼서야.」","mis":"SC4-2-u3-X32"},{"t":"「사과는 기체와 상관없어.」","mis":"SC4-2-u3-X31"}],"explanation":["산소의 성질을 떠올려요.","갈색으로 변하게 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#9','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C24',4,'mc','auto','친구가 「소화기에 산소를 넣으면 불이 더 빨리 꺼질 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X30','SC4-2-u3-X32']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C24","difficulty":4,"kind":"mc","stem":"친구가 「소화기에 산소를 넣으면 불이 더 빨리 꺼질 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「산소는 타는 것을 돕는 성질이 있어서 맞지 않아. 소화기에는 타는 것을 막는 이산화 탄소를 이용해.」","correct":true},{"t":"「맞아, 산소가 불을 꺼.」","mis":"SC4-2-u3-X31"},{"t":"「질소는 톡 쏘는 맛이 나서 소화기에 써.」","mis":"SC4-2-u3-X30"},{"t":"「이산화 탄소는 물처럼 스스로 불을 꺼.」","mis":"SC4-2-u3-X32"}],"explanation":["두 기체가 가진 성질을 견줘요.","돕는 것과 막는 것이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L06_challenge#10','sci',4,2,'u3','L06','g4_2_sci_u3_L06_challenge','lesson_challenge','SC4-2-u3-C25',4,'essay','teacher','질소, 산소, 이산화 탄소 가운데 두 가지를 골라 성질과 일상생활에서 이용되는 예를 쓰고, 성질과 이용이 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C25","difficulty":4,"kind":"essay","stem":"질소, 산소, 이산화 탄소 가운데 두 가지를 골라 성질과 일상생활에서 이용되는 예를 쓰고, 성질과 이용이 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 질소는 다른 물질과 반응을 거의 하지 않는 안정된 성질이 있어 식품을 오랫동안 보관하는 포장에 이용된다. 이산화 탄소는 다른 물질이 타는 것을 막는 성질이 있어 소화기에 이용된다. 기체는 각각의 성질에 맞게 이용된다.","scoring_points":["기체 하나의 성질과 이용을 썼는가","기체 또 하나의 성질과 이용을 썼는가","성질에 맞게 이용된다는 것을 썼는가"]},"explanation":["두 기체를 골라요.","성질과 이용을 써요.","이어지는 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#1','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C26',1,'mc','auto','장치를 따뜻한 창가에 두면 시럽은 어떻게 되나요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C26","difficulty":1,"kind":"mc","stem":"장치를 따뜻한 창가에 두면 시럽은 어떻게 되나요?","options":[{"t":"올라간다","correct":true},{"t":"내려간다","mis":"SC4-2-u3-X35"},{"t":"움직이지 않는다","mis":"SC4-2-u3-X36"},{"t":"녹아서 사라진다","mis":"SC4-2-u3-X36"}],"explanation":["창가는 따뜻해요.","약병 안 기체의 부피가 늘어나요.","올라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#2','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C26',1,'mc','auto','장치를 냉장고 안에 넣어 두면 약병 안 기체의 부피는 어떻게 되나요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C26","difficulty":1,"kind":"mc","stem":"장치를 냉장고 안에 넣어 두면 약병 안 기체의 부피는 어떻게 되나요?","options":[{"t":"줄어든다","correct":true},{"t":"늘어난다","mis":"SC4-2-u3-X35"},{"t":"그대로이다","mis":"SC4-2-u3-X36"},{"t":"무거워진다","mis":"SC4-2-u3-X36"}],"explanation":["냉장고 안은 차가워요.","온도가 낮아져요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#3','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C27',1,'ox','auto','약병 입구를 가위로 자를 때에는 다치지 않게 조심해요.',ARRAY['SC4-2-u3-X37']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C27","difficulty":1,"kind":"ox","stem":"약병 입구를 가위로 자를 때에는 다치지 않게 조심해요.","answer":"O","reason_options":[{"t":"가위를 쓸 때 손을 다칠 수 있기 때문에","correct":true},{"t":"가위는 장난을 쳐도 안전하기 때문에","mis":"SC4-2-u3-X37"}],"mis":"SC4-2-u3-X37","explanation":["①을 떠올려요.","가위를 써요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 약병 입구를 가위로 잘라 빨대를 꽂고 유토로 틈을 막아요.","② 색소를 섞은 시럽 한 방울을 빨대 중간에 넣어요.","③ 도화지에 색깔이나 눈금을 그려 약병에 붙여요.","④ 따뜻한 창가, 냉장고 안처럼 여러 곳에 두고 견주어요."],"title":"시럽 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#4','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C27',1,'sa','auto','①에서 빨대를 꽂은 자리의 틈을 막는 재료는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C27","difficulty":1,"kind":"sa","stem":"①에서 빨대를 꽂은 자리의 틈을 막는 재료는 무엇인가요? 두 글자로 쓰세요.","answer":["유토"],"explanation":["①을 읽어요.","말랑한 재료예요.","유토예요."],"asset":{"type":"passage","lines":["① 약병 입구를 가위로 잘라 빨대를 꽂고 유토로 틈을 막아요.","② 색소를 섞은 시럽 한 방울을 빨대 중간에 넣어요.","③ 도화지에 색깔이나 눈금을 그려 약병에 붙여요.","④ 따뜻한 창가, 냉장고 안처럼 여러 곳에 두고 견주어요."],"title":"시럽 장치 만들기"},"mis":"SC4-2-u3-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#5','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C27',2,'match','auto','재료와 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C27","difficulty":2,"kind":"match","stem":"재료와 쓰임을 알맞게 이으세요.","pairs":[{"l":"플라스틱 약병","r":"입구를 잘라 빨대를 꽂아요"},{"l":"빨대","r":"색소를 섞은 시럽 한 방울을 넣어요"},{"l":"유토","r":"틈이 생기지 않도록 막아요"},{"l":"도화지","r":"색깔이나 눈금을 그려 시럽의 위치를 견줘요"}],"mis":"SC4-2-u3-X37","explanation":["①~③을 읽어요.","재료마다 쓰임이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 약병 입구를 가위로 잘라 빨대를 꽂고 유토로 틈을 막아요.","② 색소를 섞은 시럽 한 방울을 빨대 중간에 넣어요.","③ 도화지에 색깔이나 눈금을 그려 약병에 붙여요.","④ 따뜻한 창가, 냉장고 안처럼 여러 곳에 두고 견주어요."],"title":"시럽 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#6','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C28',2,'mc','auto','다른 모둠이 만든 장치를 평가하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X39','SC4-2-u3-X40']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C28","difficulty":2,"kind":"mc","stem":"다른 모둠이 만든 장치를 평가하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"기체의 성질을 이용하여 만들었는가","correct":true},{"t":"가장 화려하게 꾸몄는가","mis":"SC4-2-u3-X39"},{"t":"가장 비싼 재료를 썼는가","mis":"SC4-2-u3-X39"},{"t":"특별한 기체를 따로 넣었는가","mis":"SC4-2-u3-X40"}],"explanation":["평가 기준을 떠올려요.","이용한 성질이 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#7','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C29',2,'mc','auto','「불을 끄는 소화기에 산소를 이용할 수 있어요.」라는 풍선을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X32','SC4-2-u3-X33']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C29","difficulty":2,"kind":"mc","stem":"「불을 끄는 소화기에 산소를 이용할 수 있어요.」라는 풍선을 바르게 고친 것은 무엇인가요?","options":[{"t":"「불을 끄는 소화기에는 이산화 탄소를 이용해요.」","correct":true},{"t":"「불을 끄는 소화기에는 산소를 더 많이 넣어요.」","mis":"SC4-2-u3-X31"},{"t":"「이산화 탄소는 물처럼 스스로 불을 꺼요.」","mis":"SC4-2-u3-X32"},{"t":"「소화기에는 톡 쏘는 맛을 내는 산소를 이용해요.」","mis":"SC4-2-u3-X33"}],"explanation":["산소의 성질을 떠올려요.","타는 것을 도와요.","이산화 탄소로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#8','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C26',2,'ox','auto','시럽을 움직이는 것은 약병 안 공기예요.',ARRAY['SC4-2-u3-X36']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C26","difficulty":2,"kind":"ox","stem":"시럽을 움직이는 것은 약병 안 공기예요.","answer":"O","reason_options":[{"t":"온도에 따라 약병 안 공기의 부피가 달라지기 때문에","correct":true},{"t":"시럽이 따뜻해지면 스스로 기어오르기 때문에","mis":"SC4-2-u3-X36"}],"mis":"SC4-2-u3-X36","explanation":["약병 안에 무엇이 있나요?","공기가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#9','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C28',2,'mc','auto','장치를 소개할 때 꼭 이야기할 것은 무엇인가요?',ARRAY['SC4-2-u3-X39','SC4-2-u3-X40']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C28","difficulty":2,"kind":"mc","stem":"장치를 소개할 때 꼭 이야기할 것은 무엇인가요?","options":[{"t":"기체의 어떤 성질을 이용했는지","correct":true},{"t":"도화지를 몇 장 썼는지","mis":"SC4-2-u3-X39"},{"t":"꾸미는 데 걸린 시간","mis":"SC4-2-u3-X39"},{"t":"어떤 특별한 기체를 따로 넣었는지","mis":"SC4-2-u3-X40"}],"explanation":["소통해요를 떠올려요.","이용한 성질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_basic#10','sci',4,2,'u3','L07','g4_2_sci_u3_L07_basic','lesson_basic','SC4-2-u3-C27',3,'mc','auto','기체의 부피 변화가 더 잘 나타나도록 장치를 보완하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X38']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C27","difficulty":3,"kind":"mc","stem":"기체의 부피 변화가 더 잘 나타나도록 장치를 보완하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"기체가 더 많이 들어갈 수 있도록 크기가 큰 병을 쓴다","correct":true},{"t":"도화지를 더 화려한 색으로 꾸민다","mis":"SC4-2-u3-X38"},{"t":"약병 입구의 틈을 조금 열어 둔다","mis":"SC4-2-u3-X38"},{"t":"시럽을 빨대 밖으로 빼낸다","mis":"SC4-2-u3-X38"}],"explanation":["기체가 많으면 변화도 커요.","병을 키워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#1','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C26',2,'blank','auto','「온도가 높아지면 약병 안 기체의 부피가 (    ) 시럽의 위치가 올라가요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C26","difficulty":2,"kind":"blank","stem":"「온도가 높아지면 약병 안 기체의 부피가 (    ) 시럽의 위치가 올라가요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"늘어나","correct":true},{"t":"줄어들어","mis":"SC4-2-u3-X35"},{"t":"그대로여서","mis":"SC4-2-u3-X36"},{"t":"무거워져","mis":"SC4-2-u3-X36"}],"explanation":["창가를 떠올려요.","부피가 커져요.","늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#2','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C27',2,'mc','auto','장치를 만들 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SC4-2-u3-X37','SC4-2-u3-X39']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C27","difficulty":2,"kind":"mc","stem":"장치를 만들 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"어떤 재료로 어떻게 만들지 모둠별로 계획을 세워 설계한다","correct":true},{"t":"다른 모둠 장치부터 평가한다","mis":"SC4-2-u3-X37"},{"t":"도화지부터 꾸민다","mis":"SC4-2-u3-X39"},{"t":"냉장고에 약병부터 넣어 본다","mis":"SC4-2-u3-X37"}],"explanation":["설계해요를 떠올려요.","계획이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#3','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C26',3,'error','auto','장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C26","difficulty":3,"kind":"error","stem":"장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「냉장고에 넣으면 약병 안 공기의 부피가 늘어나서 시럽이 올라가.」","correct":true,"mis_target":"SC4-2-u3-X35"},{"t":"친구 나 — 「창가에 두면 시럽이 올라가.」","mis":"SC4-2-u3-X35"},{"t":"친구 다 — 「시럽을 움직이는 건 약병 안 공기야.」","mis":"SC4-2-u3-X36"}],"explanation":["냉장고 안을 떠올려요.","부피가 줄어들어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#4','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C27',3,'mc','auto','빨대를 꽂은 자리에 틈이 생기면 어떻게 해야 하나요?',ARRAY['SC4-2-u3-X38','SC4-2-u3-X37']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C27","difficulty":3,"kind":"mc","stem":"빨대를 꽂은 자리에 틈이 생기면 어떻게 해야 하나요?","options":[{"t":"공기가 새어 나가지 않도록 유토로 막는다","correct":true},{"t":"틈이 있어야 시럽이 잘 움직이니 그대로 둔다","mis":"SC4-2-u3-X38"},{"t":"틈은 장치와 상관없으니 신경 쓰지 않는다","mis":"SC4-2-u3-X37"},{"t":"틈에 시럽을 더 넣는다","mis":"SC4-2-u3-X38"}],"explanation":["①을 떠올려요.","공기가 새면 안 돼요.","유토로 막아요."],"asset":{"type":"passage","lines":["① 약병 입구를 가위로 잘라 빨대를 꽂고 유토로 틈을 막아요.","② 색소를 섞은 시럽 한 방울을 빨대 중간에 넣어요.","③ 도화지에 색깔이나 눈금을 그려 약병에 붙여요.","④ 따뜻한 창가, 냉장고 안처럼 여러 곳에 두고 견주어요."],"title":"시럽 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#5','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C28',3,'mc','auto','이 장치를 움직이는 기체에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X40','SC4-2-u3-X36']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C28","difficulty":3,"kind":"mc","stem":"이 장치를 움직이는 기체에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"약병 안에 들어 있는 공기를 그대로 이용한다","correct":true},{"t":"공기가 아닌 특별한 기체를 따로 넣어야 한다","mis":"SC4-2-u3-X40"},{"t":"기체가 없어야 시럽이 움직인다","mis":"SC4-2-u3-X36"},{"t":"시럽이 스스로 기체를 만든다","mis":"SC4-2-u3-X36"}],"explanation":["약병 안을 떠올려요.","공기가 들어 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#6','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C28',3,'ox','auto','장치는 예쁘게 꾸미기만 하면 잘 만든 것이에요.',ARRAY['SC4-2-u3-X39']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C28","difficulty":3,"kind":"ox","stem":"장치는 예쁘게 꾸미기만 하면 잘 만든 것이에요.","answer":"X","reason_options":[{"t":"기체의 성질을 이용해 알맞게 작동하는지가 중요하기 때문에","correct":true},{"t":"꾸밈이 장치를 움직이기 때문에","mis":"SC4-2-u3-X39"}],"mis":"SC4-2-u3-X39","explanation":["평가 기준을 떠올려요.","작동이 중요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#7','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C29',3,'mc','auto','팡팡! 과학 놀이터에서 옳은 내용이 쓰인 풍선은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X31','SC4-2-u3-X20']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C29","difficulty":3,"kind":"mc","stem":"팡팡! 과학 놀이터에서 옳은 내용이 쓰인 풍선은 무엇인가요?","options":[{"t":"「따뜻한 햇빛 아래 놓아 둔 과자 봉지가 팽팽하게 부풀어 올라요.」","correct":true},{"t":"「축구공에 공기를 더 많이 넣을수록 축구공의 무게가 줄어들어요.」","mis":"SC4-2-u3-X08"},{"t":"「불을 끄는 소화기에 산소를 이용할 수 있어요.」","mis":"SC4-2-u3-X31"},{"t":"「압력이 높아지면 기체의 부피가 늘어나요.」","mis":"SC4-2-u3-X20"}],"explanation":["하나씩 따져요.","온도가 높아지면 부피가 늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#8','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C28',4,'mc','auto','친구가 「우리 장치는 반짝이 스티커를 가장 많이 붙였으니 최고야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X39','SC4-2-u3-X40','SC4-2-u3-X38']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C28","difficulty":4,"kind":"mc","stem":"친구가 「우리 장치는 반짝이 스티커를 가장 많이 붙였으니 최고야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「꾸밈보다 기체의 어떤 성질을 이용했는지, 알맞게 작동하는지가 중요해.」","correct":true},{"t":"「맞아, 많이 붙일수록 좋아.」","mis":"SC4-2-u3-X39"},{"t":"「특별한 기체를 넣어야 최고야.」","mis":"SC4-2-u3-X40"},{"t":"「시럽 색만 바꾸면 돼.」","mis":"SC4-2-u3-X38"}],"explanation":["평가 기준을 떠올려요.","꾸밈이 아니에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#9','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C26',4,'mc','auto','창가에 두었던 장치를 냉장고 안으로 옮기면 어떻게 될까요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C26","difficulty":4,"kind":"mc","stem":"창가에 두었던 장치를 냉장고 안으로 옮기면 어떻게 될까요?","options":[{"t":"온도가 낮아지면서 약병 안 기체의 부피가 줄어들어 시럽이 내려간다","correct":true},{"t":"온도가 낮아지면서 시럽이 올라간다","mis":"SC4-2-u3-X35"},{"t":"시럽은 처음 자리에 그대로 멈춰 있다","mis":"SC4-2-u3-X36"},{"t":"부피가 늘어나 시럽이 빨대 밖으로 넘친다","mis":"SC4-2-u3-X35"}],"explanation":["냉장고는 차가워요.","부피가 줄어들어요.","시럽이 내려가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L07_challenge#10','sci',4,2,'u3','L07','g4_2_sci_u3_L07_challenge','lesson_challenge','SC4-2-u3-C28',4,'essay','teacher','시럽 장치를 친구들에게 소개하는 글을 쓰세요. 이용한 기체의 성질, 창가와 냉장고에서의 변화, 보완할 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C28","difficulty":4,"kind":"essay","stem":"시럽 장치를 친구들에게 소개하는 글을 쓰세요. 이용한 기체의 성질, 창가와 냉장고에서의 변화, 보완할 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 이 장치는 온도에 따라 기체의 부피가 달라지는 성질을 이용했다. 따뜻한 창가에 두면 약병 안 기체의 부피가 늘어나 시럽이 올라가고, 냉장고 안에 두면 부피가 줄어들어 시럽이 내려간다. 변화가 더 잘 보이도록 크기가 큰 병을 쓰면 좋겠다.","scoring_points":["이용한 성질을 썼는가","창가와 냉장고에서의 변화를 썼는가","알맞은 보완할 점을 썼는가"]},"explanation":["이용한 성질을 써요.","두 곳의 변화를 써요.","보완할 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#1','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C30',1,'mc','auto','비행기의 엔진에서 뿜어져 나오는 많은 양의 이산화 탄소는 무엇을 유발하나요?',ARRAY['SC4-2-u3-X41']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C30","difficulty":1,"kind":"mc","stem":"비행기의 엔진에서 뿜어져 나오는 많은 양의 이산화 탄소는 무엇을 유발하나요?","options":[{"t":"환경오염","correct":true},{"t":"비행기가 공중에 떠오르는 힘","mis":"SC4-2-u3-X41"},{"t":"활주로가 짧아지는 일","mis":"SC4-2-u3-X41"},{"t":"적은 에너지로 오래 나는 일","mis":"SC4-2-u3-X41"}],"explanation":["비행기의 문제를 떠올려요.","환경에 나빠요.","환경오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#2','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C31',1,'mc','auto','비행선의 풍선 안에 들어 있는 기체는 무엇인가요?',ARRAY['SC4-2-u3-X42']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C31","difficulty":1,"kind":"mc","stem":"비행선의 풍선 안에 들어 있는 기체는 무엇인가요?","options":[{"t":"헬륨","correct":true},{"t":"이산화 탄소","mis":"SC4-2-u3-X42"},{"t":"공기보다 무거운 기체","mis":"SC4-2-u3-X42"},{"t":"아무것도 들어 있지 않다","mis":"SC4-2-u3-X42"}],"explanation":["비행선의 이름을 떠올려요.","헬륨 비행선이에요.","헬륨이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#3','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C31',1,'ox','auto','헬륨 기체는 같은 부피의 공기보다 가벼워요.',ARRAY['SC4-2-u3-X42']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C31","difficulty":1,"kind":"ox","stem":"헬륨 기체는 같은 부피의 공기보다 가벼워요.","answer":"O","reason_options":[{"t":"그래서 비행선이 공중에 떠오를 수 있기 때문에","correct":true},{"t":"헬륨은 공기보다 무거워 아래로 가라앉기 때문에","mis":"SC4-2-u3-X42"}],"mis":"SC4-2-u3-X42","explanation":["비행선이 떠오르는 까닭을 떠올려요.","가벼워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#4','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C31',1,'sa','auto','「비행장에서 비행기가 뜨거나 내릴 때 달리는 길」을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C31","difficulty":1,"kind":"sa","stem":"「비행장에서 비행기가 뜨거나 내릴 때 달리는 길」을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["활주로"],"explanation":["새로 나온 낱말이에요.","비행기가 달리는 길이에요.","활주로예요."],"mis":"SC4-2-u3-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#5','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C31',2,'match','auto','말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C31","difficulty":2,"kind":"match","stem":"말과 뜻을 알맞게 이으세요.","pairs":[{"l":"비행체","r":"날아다니는 물체"},{"l":"활주로","r":"비행기가 뜨거나 내릴 때 달리는 길"},{"l":"헬륨","r":"비행선의 풍선 안에 들어 있는 기체"}],"mis":"SC4-2-u3-X42","explanation":["새로 나온 낱말을 떠올려요.","뜻을 하나씩 읽어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#6','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C32',2,'mc','auto','헬륨 비행선의 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X41','SC4-2-u3-X44','SC4-2-u3-X43']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C32","difficulty":2,"kind":"mc","stem":"헬륨 비행선의 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"활주로가 없는 곳에서도 뜨고 내릴 수 있다","correct":true},{"t":"엔진에서 많은 양의 이산화 탄소를 뿜어낸다","mis":"SC4-2-u3-X41"},{"t":"긴 활주로가 있는 비행장에서만 이용할 수 있다","mis":"SC4-2-u3-X44"},{"t":"비행기보다 엔진을 많이 사용한다","mis":"SC4-2-u3-X43"}],"explanation":["표의 비행선 줄을 읽어요.","활주로가 없어도 돼요.","첫 번째예요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 뿜어져 나와요.","비행기 — 활주로를 달려서 뜨거나 내려요.","헬륨 비행선 — 비행기에 비해 엔진을 적게 사용해요.","헬륨 비행선 — 활주로가 없는 곳에서도 뜨고 내려요."],"title":"비행기와 비행선 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#7','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C30',2,'mc','auto','비행기의 문제를 보완하기 위해 과학자들이 주목한 것은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X44','SC4-2-u3-X41']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C30","difficulty":2,"kind":"mc","stem":"비행기의 문제를 보완하기 위해 과학자들이 주목한 것은 무엇인가요?","options":[{"t":"비행선","correct":true},{"t":"더 큰 엔진","mis":"SC4-2-u3-X45"},{"t":"더 긴 활주로","mis":"SC4-2-u3-X44"},{"t":"이산화 탄소를 더 많이 뿜는 비행기","mis":"SC4-2-u3-X41"}],"explanation":["이야기의 첫 부분을 떠올려요.","풍선 모양 비행체예요.","비행선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#8','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C32',2,'ox','auto','비행선은 엔진을 전혀 사용하지 않아요.',ARRAY['SC4-2-u3-X43']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C32","difficulty":2,"kind":"ox","stem":"비행선은 엔진을 전혀 사용하지 않아요.","answer":"X","reason_options":[{"t":"비행기에 비해 엔진을 적게 사용하는 것이지 전혀 쓰지 않는 것은 아니기 때문에","correct":true},{"t":"헬륨이 있으면 엔진이 필요 없기 때문에","mis":"SC4-2-u3-X43"}],"mis":"SC4-2-u3-X43","explanation":["「적게」를 떠올려요.","전혀가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#9','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C32',2,'mc','auto','헬륨을 이용한 비행선은 적은 양의 에너지로도 어떻게 할 수 있나요?',ARRAY['SC4-2-u3-X43','SC4-2-u3-X44','SC4-2-u3-X41']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C32","difficulty":2,"kind":"mc","stem":"헬륨을 이용한 비행선은 적은 양의 에너지로도 어떻게 할 수 있나요?","options":[{"t":"오랫동안 떠 있을 수 있다","correct":true},{"t":"잠깐만 떠 있을 수 있다","mis":"SC4-2-u3-X43"},{"t":"활주로를 달려야만 떠오를 수 있다","mis":"SC4-2-u3-X44"},{"t":"이산화 탄소를 많이 뿜을 수 있다","mis":"SC4-2-u3-X41"}],"explanation":["비행선의 좋은 점을 떠올려요.","오래 떠 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_basic#10','sci',4,2,'u3','L08','g4_2_sci_u3_L08_basic','lesson_basic','SC4-2-u3-C33',3,'mc','auto','기체를 이용한 친환경 제품의 예로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X42','SC4-2-u3-X44']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C33","difficulty":3,"kind":"mc","stem":"기체를 이용한 친환경 제품의 예로 알맞은 것은 무엇인가요?","options":[{"t":"수소 기체를 연료로 이용해 환경오염 물질을 배출하지 않는 수소 자동차","correct":true},{"t":"엔진을 더 크게 만들어 이산화 탄소를 더 많이 뿜는 비행기","mis":"SC4-2-u3-X45"},{"t":"공기보다 무거운 기체를 넣어 띄우는 풍선","mis":"SC4-2-u3-X42"},{"t":"활주로를 더 길게 만든 비행장","mis":"SC4-2-u3-X44"}],"explanation":["친환경의 뜻을 떠올려요.","환경오염 물질을 줄여요.","수소 자동차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#1','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C31',2,'blank','auto','「비행선은 커다란 (    ) 모양의 비행체예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X42','SC4-2-u3-X44','SC4-2-u3-X43']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C31","difficulty":2,"kind":"blank","stem":"「비행선은 커다란 (    ) 모양의 비행체예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"풍선","correct":true},{"t":"상자","mis":"SC4-2-u3-X42"},{"t":"바퀴","mis":"SC4-2-u3-X44"},{"t":"엔진","mis":"SC4-2-u3-X43"}],"explanation":["비행선의 모습을 떠올려요.","헬륨이 들어 있어요.","풍선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#2','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C30',2,'mc','auto','비행기에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X41','SC4-2-u3-X43']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C30","difficulty":2,"kind":"mc","stem":"비행기에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"중요한 운송 수단이지만 엔진에서 많은 양의 이산화 탄소가 나와 환경오염을 유발한다","correct":true},{"t":"비행기는 환경에 아무 영향도 주지 않는다","mis":"SC4-2-u3-X41"},{"t":"엔진에서 나오는 이산화 탄소가 비행기를 띄운다","mis":"SC4-2-u3-X41"},{"t":"비행기는 엔진을 쓰지 않는다","mis":"SC4-2-u3-X43"}],"explanation":["비행기의 좋은 점과 문제를 함께 떠올려요.","이산화 탄소가 나와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#3','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C32',3,'error','auto','비행선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X43','SC4-2-u3-X44']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C32","difficulty":3,"kind":"error","stem":"비행선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「비행선은 엔진을 하나도 안 쓰니까 이산화 탄소가 전혀 안 나와.」","correct":true,"mis_target":"SC4-2-u3-X43"},{"t":"친구 가 — 「비행선은 비행기에 비해 엔진을 적게 써.」","mis":"SC4-2-u3-X43"},{"t":"친구 나 — 「활주로가 없는 곳에서도 뜨고 내릴 수 있어.」","mis":"SC4-2-u3-X44"}],"explanation":["「적게」를 떠올려요.","하나도 안 쓰는 게 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#4','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C31',3,'mc','auto','비행선이 공중에 떠오를 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X42','SC4-2-u3-X44']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C31","difficulty":3,"kind":"mc","stem":"비행선이 공중에 떠오를 수 있는 까닭은 무엇인가요?","options":[{"t":"풍선 안 헬륨 기체가 같은 부피의 공기보다 가볍기 때문에","correct":true},{"t":"엔진을 아주 많이 사용하기 때문에","mis":"SC4-2-u3-X42"},{"t":"활주로를 아주 빠르게 달리기 때문에","mis":"SC4-2-u3-X44"},{"t":"풍선 안에 이산화 탄소가 가득하기 때문에","mis":"SC4-2-u3-X42"}],"explanation":["헬륨을 떠올려요.","공기보다 가벼워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#5','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C32',3,'mc','auto','비행선을 비행기가 다닐 수 없는 곳에서도 이용할 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X43','SC4-2-u3-X41','SC4-2-u3-X44']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C32","difficulty":3,"kind":"mc","stem":"비행선을 비행기가 다닐 수 없는 곳에서도 이용할 수 있는 까닭은 무엇인가요?","options":[{"t":"활주로가 없는 곳에서도 뜨고 내릴 수 있기 때문에","correct":true},{"t":"엔진을 더 많이 사용하기 때문에","mis":"SC4-2-u3-X43"},{"t":"이산화 탄소를 많이 뿜기 때문에","mis":"SC4-2-u3-X41"},{"t":"긴 활주로가 꼭 있어야 하기 때문에","mis":"SC4-2-u3-X44"}],"explanation":["표의 넷째 줄을 읽어요.","활주로가 없어도 돼요.","첫 번째예요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 뿜어져 나와요.","비행기 — 활주로를 달려서 뜨거나 내려요.","헬륨 비행선 — 비행기에 비해 엔진을 적게 사용해요.","헬륨 비행선 — 활주로가 없는 곳에서도 뜨고 내려요."],"title":"비행기와 비행선 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#6','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C33',3,'ox','auto','기체의 성질과 이용은 우리 주변의 환경에 영향을 미쳐요.',ARRAY['SC4-2-u3-X41']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C33","difficulty":3,"kind":"ox","stem":"기체의 성질과 이용은 우리 주변의 환경에 영향을 미쳐요.","answer":"O","reason_options":[{"t":"어떤 기체를 어떻게 이용하느냐에 따라 환경오염이 늘거나 줄 수 있기 때문에","correct":true},{"t":"기체는 눈에 보이지 않아 환경과 상관없기 때문에","mis":"SC4-2-u3-X41"}],"mis":"SC4-2-u3-X41","explanation":["비행기와 비행선을 떠올려요.","환경에 미치는 영향이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#7','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C30',3,'mc','auto','과학자들이 비행선에 주목한 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X44']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C30","difficulty":3,"kind":"mc","stem":"과학자들이 비행선에 주목한 까닭은 무엇인가요?","options":[{"t":"비행기의 엔진에서 나오는 많은 양의 이산화 탄소 문제를 보완하기 위해서","correct":true},{"t":"비행기보다 엔진을 더 많이 쓰려고","mis":"SC4-2-u3-X45"},{"t":"더 긴 활주로를 만들려고","mis":"SC4-2-u3-X44"},{"t":"이산화 탄소를 더 많이 쓰려고","mis":"SC4-2-u3-X45"}],"explanation":["비행기의 문제를 떠올려요.","보완하려고 했어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#8','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C32',4,'mc','auto','친구가 「비행선은 엔진을 전혀 안 쓰니까 에너지가 하나도 안 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X43','SC4-2-u3-X44','SC4-2-u3-X42']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C32","difficulty":4,"kind":"mc","stem":"친구가 「비행선은 엔진을 전혀 안 쓰니까 에너지가 하나도 안 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「비행선은 비행기에 비해 엔진을 적게 쓰는 거야. 적은 양의 에너지로 오랫동안 떠 있을 수 있다는 뜻이야.」","correct":true},{"t":"「맞아, 에너지가 하나도 안 들어.」","mis":"SC4-2-u3-X43"},{"t":"「비행선도 긴 활주로가 꼭 있어야 해.」","mis":"SC4-2-u3-X44"},{"t":"「비행선 풍선에는 공기만 들어 있어.」","mis":"SC4-2-u3-X42"}],"explanation":["「적게」와 「전혀」를 견줘요.","적은 에너지예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#9','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C33',4,'mc','auto','친구가 「친환경 제품은 엔진을 크게 만들어 더 빨리 가는 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X41']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C33","difficulty":4,"kind":"mc","stem":"친구가 「친환경 제품은 엔진을 크게 만들어 더 빨리 가는 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「친환경 제품은 기체의 성질을 이용해 환경오염 물질을 줄이는 거야. 수소 자동차처럼 말이야.」","correct":true},{"t":"「맞아, 크고 빠르면 친환경이야.」","mis":"SC4-2-u3-X45"},{"t":"「이산화 탄소를 많이 뿜을수록 친환경이야.」","mis":"SC4-2-u3-X45"},{"t":"「기체는 환경과 상관없어.」","mis":"SC4-2-u3-X41"}],"explanation":["친환경의 뜻을 떠올려요.","환경오염 물질을 줄여요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_L08_challenge#10','sci',4,2,'u3','L08','g4_2_sci_u3_L08_challenge','lesson_challenge','SC4-2-u3-C31',4,'essay','teacher','헬륨 비행선이 공중에 떠오르는 까닭을 쓰고, 비행기와 견주어 비행선의 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u3-C31","difficulty":4,"kind":"essay","stem":"헬륨 비행선이 공중에 떠오르는 까닭을 쓰고, 비행기와 견주어 비행선의 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 비행선의 풍선 안에 든 헬륨 기체가 같은 부피의 공기보다 가볍기 때문에 떠오른다. 비행선은 비행기에 비해 엔진을 적게 사용하고, 활주로가 없는 곳에서도 뜨고 내릴 수 있다.","scoring_points":["떠오르는 까닭을 썼는가","좋은 점 하나를 썼는가","좋은 점 또 하나를 썼는가"]},"explanation":["헬륨을 떠올려요.","까닭을 써요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#1','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C3',1,'mc','auto','하늘반 일지 ①에서 공이 팽팽한 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X05']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C3","difficulty":1,"kind":"mc","stem":"하늘반 일지 ①에서 공이 팽팽한 까닭은 무엇인가요?","options":[{"t":"안에 공기가 들어 있기 때문에","correct":true},{"t":"공이 원래 딱딱하기 때문에","mis":"SC4-2-u3-X05"},{"t":"공에서 바람이 나오기 때문에","mis":"SC4-2-u3-X05"},{"t":"공기가 공 밖으로 이동했기 때문에","mis":"SC4-2-u3-X05"}],"explanation":["둘째 줄을 읽어요.","안에 무엇이 있나요?","공기가 들어 있어요."],"asset":{"type":"passage","lines":["운동장에서 공기가 있는 곳을 찾아보았다.","공 — 안에 공기가 들어 있어 팽팽하다.","부채 — 부채질을 하면 공기가 이동해 바람이 분다.","친구 가 — 「물속에서 올라오는 공기 방울도 생각났어.」"],"title":"하늘반 일지 ① 공기 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#2','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C6',1,'mc','auto','하늘반 일지 ②에서 페트병에 공기를 넣은 뒤 무게는 어떻게 되었나요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C6","difficulty":1,"kind":"mc","stem":"하늘반 일지 ②에서 페트병에 공기를 넣은 뒤 무게는 어떻게 되었나요?","options":[{"t":"늘어났다","correct":true},{"t":"줄어들었다","mis":"SC4-2-u3-X08"},{"t":"그대로였다","mis":"SC4-2-u3-X08"},{"t":"잴 수 없었다","mis":"SC4-2-u3-X07"}],"explanation":["셋째 줄을 읽어요.","공기를 넣었어요.","늘어났어요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#3','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C10',1,'mc','auto','하늘반 일지 ③에서 따뜻한 바람을 쏘였을 때 풍선 안 기체의 부피는 어떻게 되었나요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"mc","stem":"하늘반 일지 ③에서 따뜻한 바람을 쏘였을 때 풍선 안 기체의 부피는 어떻게 되었나요?","options":[{"t":"늘어났다","correct":true},{"t":"줄어들었다","mis":"SC4-2-u3-X13"},{"t":"그대로였다","mis":"SC4-2-u3-X14"},{"t":"모두 사라졌다","mis":"SC4-2-u3-X14"}],"explanation":["둘째 줄을 읽어요.","부풀어 올랐어요.","늘어났어요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#4','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C15',1,'mc','auto','하늘반 일지 ④에서 피스톤을 눌렀을 때 주사기 안 풍선은 어떻게 되었나요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X21','SC4-2-u3-X24']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C15","difficulty":1,"kind":"mc","stem":"하늘반 일지 ④에서 피스톤을 눌렀을 때 주사기 안 풍선은 어떻게 되었나요?","options":[{"t":"작아졌다","correct":true},{"t":"커졌다","mis":"SC4-2-u3-X20"},{"t":"피스톤에 닿지 않아 그대로였다","mis":"SC4-2-u3-X21"},{"t":"터져서 사라졌다","mis":"SC4-2-u3-X24"}],"explanation":["둘째 줄을 읽어요.","공기와 함께 작아졌어요.","작아졌어요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#5','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C19',1,'mc','auto','하늘반 일지 ⑤의 ㉠에서 튜브가 팽팽해진 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X13','SC4-2-u3-X27']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C19","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑤의 ㉠에서 튜브가 팽팽해진 까닭은 무엇인가요?","options":[{"t":"온도가 높아졌기 때문에","correct":true},{"t":"압력이 높아졌기 때문에","mis":"SC4-2-u3-X25"},{"t":"온도가 낮아졌기 때문에","mis":"SC4-2-u3-X13"},{"t":"공기가 빠져나갔기 때문에","mis":"SC4-2-u3-X27"}],"explanation":["㉠을 읽어요.","땡볕은 뜨거워요.","온도가 높아졌어요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#6','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C22',1,'mc','auto','하늘반 일지 ⑥에서 과자 봉지에 들어 있는 기체는 무엇인가요?',ARRAY['SC4-2-u3-X30','SC4-2-u3-X29']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C22","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑥에서 과자 봉지에 들어 있는 기체는 무엇인가요?","options":[{"t":"질소","correct":true},{"t":"산소","mis":"SC4-2-u3-X30"},{"t":"이산화 탄소","mis":"SC4-2-u3-X30"},{"t":"수소","mis":"SC4-2-u3-X29"}],"explanation":["첫 줄을 읽어요.","안정된 성질이에요.","질소예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#7','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C26',1,'mc','auto','하늘반 일지 ⑦에서 장치를 창가에 두었을 때 시럽은 어떻게 되었나요?',ARRAY['SC4-2-u3-X35','SC4-2-u3-X36']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C26","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑦에서 장치를 창가에 두었을 때 시럽은 어떻게 되었나요?","options":[{"t":"올라갔다","correct":true},{"t":"내려갔다","mis":"SC4-2-u3-X35"},{"t":"움직이지 않았다","mis":"SC4-2-u3-X36"},{"t":"녹아서 사라졌다","mis":"SC4-2-u3-X36"}],"explanation":["셋째 줄을 읽어요.","창가는 따뜻해요.","올라갔어요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#8','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C31',1,'mc','auto','하늘반 일지 ⑧에서 비행선을 떠오르게 하는 기체는 무엇인가요?',ARRAY['SC4-2-u3-X42']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C31","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑧에서 비행선을 떠오르게 하는 기체는 무엇인가요?","options":[{"t":"헬륨","correct":true},{"t":"이산화 탄소","mis":"SC4-2-u3-X42"},{"t":"공기보다 무거운 기체","mis":"SC4-2-u3-X42"},{"t":"산소","mis":"SC4-2-u3-X42"}],"explanation":["둘째 줄을 읽어요.","공기보다 가벼워요.","헬륨이에요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#9','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C2',2,'match','auto','기체를 찾은 물건과 기체가 있는 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC4-2-u3-C2","difficulty":2,"kind":"match","stem":"기체를 찾은 물건과 기체가 있는 부분을 알맞게 이으세요.","pairs":[{"l":"풍선","r":"풍선 안에 들어 있는 공기"},{"l":"부채","r":"부채질로 이동하는 공기"},{"l":"자전거 타이어","r":"공기 주입기로 넣는 공기"}],"mis":"SC4-2-u3-X04","explanation":["물건을 하나씩 떠올려요.","들어 있거나 이동해요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#10','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C8',2,'mc','auto','전자저울에 나온 페트병의 무게에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X10','SC4-2-u3-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C8","difficulty":2,"kind":"mc","stem":"전자저울에 나온 페트병의 무게에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"페트병, 공기 주입 마개, 안의 공기를 모두 합한 무게이다","correct":true},{"t":"페트병 안 공기만의 무게이다","mis":"SC4-2-u3-X10"},{"t":"공기 주입 마개만의 무게이다","mis":"SC4-2-u3-X10"},{"t":"공기는 빼고 잰 무게이다","mis":"SC4-2-u3-X07"}],"explanation":["저울 위를 떠올려요.","통째로 올렸어요.","모두 합한 무게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#11','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C13',2,'mc','auto','열기구 아래쪽을 가열하면 열기구가 크게 부풀어 오르는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X15','SC4-2-u3-X14']::text[],false,'{"seq":11,"concept":"SC4-2-u3-C13","difficulty":2,"kind":"mc","stem":"열기구 아래쪽을 가열하면 열기구가 크게 부풀어 오르는 까닭은 무엇인가요?","options":[{"t":"온도가 높아지면서 안에 든 기체의 부피가 늘어나기 때문에","correct":true},{"t":"온도가 높아지면서 안에 든 기체의 부피가 줄어들기 때문에","mis":"SC4-2-u3-X13"},{"t":"가열하면 바람이 안으로 들어가기 때문에","mis":"SC4-2-u3-X15"},{"t":"열기구는 온도와 상관없기 때문에","mis":"SC4-2-u3-X14"}],"explanation":["가열하면 온도가 높아져요.","부피가 늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#12','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C14',2,'mc','auto','피스톤을 누를 때와 당길 때 기체에 미치는 압력을 바르게 짝지은 것은 무엇인가요?',ARRAY['SC4-2-u3-X19']::text[],false,'{"seq":12,"concept":"SC4-2-u3-C14","difficulty":2,"kind":"mc","stem":"피스톤을 누를 때와 당길 때 기체에 미치는 압력을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"누를 때 — 높아진다 / 당길 때 — 낮아진다","correct":true},{"t":"누를 때 — 낮아진다 / 당길 때 — 높아진다","mis":"SC4-2-u3-X19"},{"t":"누를 때 — 높아진다 / 당길 때 — 높아진다","mis":"SC4-2-u3-X19"},{"t":"누를 때 — 그대로이다 / 당길 때 — 그대로이다","mis":"SC4-2-u3-X19"}],"explanation":["압력은 누르는 힘이에요.","누르면 커져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#13','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C18',2,'mc','auto','자동차에 짐을 많이 실었을 때 타이어가 찌그러지는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X24','SC4-2-u3-X27']::text[],false,'{"seq":13,"concept":"SC4-2-u3-C18","difficulty":2,"kind":"mc","stem":"자동차에 짐을 많이 실었을 때 타이어가 찌그러지는 까닭은 무엇인가요?","options":[{"t":"타이어 안 공기에 미치는 압력이 높아져 부피가 줄어들기 때문에","correct":true},{"t":"온도가 높아져 부피가 늘어나기 때문에","mis":"SC4-2-u3-X25"},{"t":"짐이 공기를 밀어내 공기가 사라지기 때문에","mis":"SC4-2-u3-X24"},{"t":"타이어는 공기와 상관없기 때문에","mis":"SC4-2-u3-X27"}],"explanation":["짐이 타이어를 눌러요.","압력이 높아져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#14','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C25',2,'match','auto','기체와 이용을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC4-2-u3-C25","difficulty":2,"kind":"match","stem":"기체와 이용을 알맞게 이으세요.","pairs":[{"l":"질소","r":"식품을 오랫동안 보관하는 포장"},{"l":"산소","r":"로켓의 연료를 태울 때"},{"l":"이산화 탄소","r":"불을 끄는 소화기"}],"mis":"SC4-2-u3-X34","explanation":["성질을 떠올려요.","성질에 맞게 써요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#15','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C27',2,'mc','auto','시럽 장치를 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X37','SC4-2-u3-X39']::text[],false,'{"seq":15,"concept":"SC4-2-u3-C27","difficulty":2,"kind":"mc","stem":"시럽 장치를 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"설계하기 → 빨대 꽂고 틈 막기 → 시럽 넣기 → 여러 곳에 두고 견주기","correct":true},{"t":"시럽 넣기 → 설계하기 → 틈 막기 → 견주기","mis":"SC4-2-u3-X37"},{"t":"견주기 → 시럽 넣기 → 틈 막기 → 설계하기","mis":"SC4-2-u3-X37"},{"t":"꾸미기 → 꾸미기 → 꾸미기 → 끝내기","mis":"SC4-2-u3-X39"}],"explanation":["설계가 먼저예요.","틈을 막고 시럽을 넣어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#16','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C31',2,'mc','auto','헬륨 비행선이 떠오를 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X42','SC4-2-u3-X43','SC4-2-u3-X44']::text[],false,'{"seq":16,"concept":"SC4-2-u3-C31","difficulty":2,"kind":"mc","stem":"헬륨 비행선이 떠오를 수 있는 까닭은 무엇인가요?","options":[{"t":"헬륨이 같은 부피의 공기보다 가볍기 때문에","correct":true},{"t":"헬륨이 공기보다 무겁기 때문에","mis":"SC4-2-u3-X42"},{"t":"엔진을 아주 많이 쓰기 때문에","mis":"SC4-2-u3-X43"},{"t":"활주로를 빠르게 달리기 때문에","mis":"SC4-2-u3-X44"}],"explanation":["헬륨을 떠올려요.","가벼워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#17','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C8',3,'error','auto','하늘반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X10','SC4-2-u3-X08','SC4-2-u3-X09']::text[],false,'{"seq":17,"concept":"SC4-2-u3-C8","difficulty":3,"kind":"error","stem":"하늘반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「저울에 나온 페트병 무게는 안에 든 공기만의 무게야.」","correct":true,"mis_target":"SC4-2-u3-X10"},{"t":"친구 가 — 「공기를 넣으니 페트병이 더 무거워졌어.」","mis":"SC4-2-u3-X08"},{"t":"친구 나 — 「공기를 빼니 감압 용기가 더 가벼워졌어.」","mis":"SC4-2-u3-X09"}],"explanation":["무엇을 재었는지 떠올려요.","용기를 통째로 재었어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#18','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C11',3,'error','auto','하늘반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X15','SC4-2-u3-X13']::text[],false,'{"seq":18,"concept":"SC4-2-u3-C11","difficulty":3,"kind":"error","stem":"하늘반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」","correct":true,"mis_target":"SC4-2-u3-X15"},{"t":"친구 가 — 「입구를 잘 닫았으니 안의 기체가 그대로 있어.」","mis":"SC4-2-u3-X15"},{"t":"친구 나 — 「따뜻해지니 기체의 부피가 늘어났어.」","mis":"SC4-2-u3-X13"}],"explanation":["첫 줄을 읽어요.","입구를 잘 닫았어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#19','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C15',3,'error','auto','하늘반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X19','SC4-2-u3-X21']::text[],false,'{"seq":19,"concept":"SC4-2-u3-C15","difficulty":3,"kind":"error","stem":"하늘반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「피스톤을 누르면 압력이 높아져서 풍선이 커져.」","correct":true,"mis_target":"SC4-2-u3-X20"},{"t":"친구 가 — 「피스톤을 당기니 압력이 낮아졌어.」","mis":"SC4-2-u3-X19"},{"t":"친구 다 — 「풍선은 피스톤에 닿지 않았는데도 작아졌어.」","mis":"SC4-2-u3-X21"}],"explanation":["둘째 줄을 읽어요.","작아졌어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#20','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C19',3,'error','auto','하늘반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X26','SC4-2-u3-X25','SC4-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC4-2-u3-C19","difficulty":3,"kind":"error","stem":"하늘반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉡과 ㉢은 둘 다 줄어들었으니 까닭도 같아.」","correct":true,"mis_target":"SC4-2-u3-X26"},{"t":"친구 나 — 「㉠은 온도가 높아져서 부피가 늘어났어.」","mis":"SC4-2-u3-X25"},{"t":"친구 다 — 「자료마다 출처를 적었으니 다시 확인할 수 있어.」","mis":"SC4-2-u3-X28"}],"explanation":["㉡과 ㉢을 따로 따져요.","압력과 온도예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#21','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C24',3,'error','auto','하늘반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X32','SC4-2-u3-X30','SC4-2-u3-X31']::text[],false,'{"seq":21,"concept":"SC4-2-u3-C24","difficulty":3,"kind":"error","stem":"하늘반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「소화기 속 이산화 탄소는 물처럼 스스로 불을 꺼.」","correct":true,"mis_target":"SC4-2-u3-X32"},{"t":"친구 가 — 「질소는 반응을 거의 하지 않아서 과자를 오래 보관해.」","mis":"SC4-2-u3-X30"},{"t":"친구 다 — 「산소는 타는 것을 도와서 소화기에는 맞지 않아.」","mis":"SC4-2-u3-X31"}],"explanation":["넷째 줄을 읽어요.","타는 것을 막아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#22','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C28',3,'error','auto','하늘반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X39','SC4-2-u3-X35','SC4-2-u3-X37']::text[],false,'{"seq":22,"concept":"SC4-2-u3-C28","difficulty":3,"kind":"error","stem":"하늘반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」","correct":true,"mis_target":"SC4-2-u3-X39"},{"t":"친구 가 — 「온도가 높아지면 약병 안 공기의 부피가 늘어나.」","mis":"SC4-2-u3-X35"},{"t":"친구 다 — 「틈을 유토로 막아서 공기가 새지 않아.」","mis":"SC4-2-u3-X37"}],"explanation":["넷째 줄을 따져요.","꾸밈이 움직이지 않아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#23','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C5',4,'essay','teacher','하늘반 일지 ②를 보고 기체에 무게가 있다는 것을 두 가지 결과를 들어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u3-C5","difficulty":4,"kind":"essay","stem":"하늘반 일지 ②를 보고 기체에 무게가 있다는 것을 두 가지 결과를 들어 설명하세요.","answer_guide":{"answer":"예: 공기를 가득 넣은 고무배가 쭈글쭈글한 고무배보다 더 무거웠고, 페트병에 공기를 넣으니 무게가 늘어났다. 공기의 양에 따라 무게가 달라지므로 공기와 같은 기체도 무게가 있다.","scoring_points":["결과 하나를 썼는가","결과 또 하나를 썼는가","기체도 무게가 있다는 결론을 썼는가"]},"explanation":["일지를 읽어요.","결과를 골라요.","결론을 써요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#24','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C5',4,'mc','auto','친구가 「공기는 눈에 보이지 않으니 공기를 가득 넣은 고무배나 쭈글쭈글한 고무배나 무게가 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X07','SC4-2-u3-X08','SC4-2-u3-X11']::text[],false,'{"seq":24,"concept":"SC4-2-u3-C5","difficulty":4,"kind":"mc","stem":"친구가 「공기는 눈에 보이지 않으니 공기를 가득 넣은 고무배나 쭈글쭈글한 고무배나 무게가 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「공기에도 무게가 있어서 공기를 많이 넣을수록 고무배가 더 무거워져.」","correct":true},{"t":"「맞아, 보이지 않으면 무게도 없어.」","mis":"SC4-2-u3-X07"},{"t":"「공기를 넣으면 더 가벼워져.」","mis":"SC4-2-u3-X08"},{"t":"「무게가 아니라 크기만 달라져.」","mis":"SC4-2-u3-X11"}],"explanation":["무게 실험을 떠올려요.","공기를 넣으면 무거워졌어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_a#25','sci',4,2,'u3','','g4_2_sci_u3_review_a','unit_review','SC4-2-u3-C25',4,'essay','teacher','하늘반 일지 ⑥을 보고 질소, 산소, 이산화 탄소의 성질과 이용을 하나씩 짝지어 쓰고, 소화기에 산소를 쓰지 않는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u3-C25","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑥을 보고 질소, 산소, 이산화 탄소의 성질과 이용을 하나씩 짝지어 쓰고, 소화기에 산소를 쓰지 않는 까닭을 쓰세요.","answer_guide":{"answer":"예: 질소는 반응을 거의 하지 않는 안정된 성질이 있어 과자 봉지 포장에 쓰인다. 산소는 타는 것을 돕고 호흡에 필요해 산소 캔에 쓰인다. 이산화 탄소는 다른 물질이 타는 것을 막는 성질이 있어 소화기에 쓰인다. 산소는 타는 것을 돕는 성질이 있으므로 불을 끄는 소화기에는 맞지 않다.","scoring_points":["세 기체의 성질과 이용을 바르게 짝지었는가","성질과 이용이 이어지게 썼는가","소화기에 산소를 쓰지 않는 까닭을 썼는가"]},"explanation":["일지를 읽어요.","짝을 지어요.","까닭을 써요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#1','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C3',1,'sa','auto','하늘반 일지 ①에서 부채질을 하면 공기가 어떻게 되어 바람이 부나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC4-2-u3-C3","difficulty":1,"kind":"sa","stem":"하늘반 일지 ①에서 부채질을 하면 공기가 어떻게 되어 바람이 부나요? 두 글자로 쓰세요.","answer":["이동","이동해","이동해요","이동한다"],"explanation":["셋째 줄을 읽어요.","공기가 움직여요.","이동해요."],"asset":{"type":"passage","lines":["운동장에서 공기가 있는 곳을 찾아보았다.","공 — 안에 공기가 들어 있어 팽팽하다.","부채 — 부채질을 하면 공기가 이동해 바람이 분다.","친구 가 — 「물속에서 올라오는 공기 방울도 생각났어.」"],"title":"하늘반 일지 ① 공기 찾기"},"mis":"SC4-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#2','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C5',1,'mc','auto','하늘반 일지 ②에서 공기를 가득 넣은 고무배가 더 무거웠던 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C5","difficulty":1,"kind":"mc","stem":"하늘반 일지 ②에서 공기를 가득 넣은 고무배가 더 무거웠던 까닭은 무엇인가요?","options":[{"t":"공기에도 무게가 있어 공기를 많이 넣을수록 무게가 늘어나기 때문에","correct":true},{"t":"공기를 넣으면 고무배가 가벼워지기 때문에","mis":"SC4-2-u3-X08"},{"t":"공기는 무게가 없지만 모양만 커지기 때문에","mis":"SC4-2-u3-X07"},{"t":"공기를 넣으면 고무배가 차가워지기 때문에","mis":"SC4-2-u3-X07"}],"explanation":["둘째 줄을 읽어요.","공기도 무게가 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#3','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C10',1,'mc','auto','하늘반 일지 ③에서 얼음이 담긴 수조에 넣은 풍선은 어떻게 되었나요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14','SC4-2-u3-X17']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"mc","stem":"하늘반 일지 ③에서 얼음이 담긴 수조에 넣은 풍선은 어떻게 되었나요?","options":[{"t":"쭈그러들었다","correct":true},{"t":"부풀어 올랐다","mis":"SC4-2-u3-X13"},{"t":"그대로였다","mis":"SC4-2-u3-X14"},{"t":"터졌다","mis":"SC4-2-u3-X17"}],"explanation":["셋째 줄을 읽어요.","차가워졌어요.","쭈그러들었어요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#4','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C14',1,'sa','auto','하늘반 일지 ④에서 피스톤을 누를 때처럼 누르는 힘을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u3-C14","difficulty":1,"kind":"sa","stem":"하늘반 일지 ④에서 피스톤을 누를 때처럼 누르는 힘을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["압력"],"explanation":["누르는 힘이에요.","두 글자예요.","압력이에요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"},"mis":"SC4-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#5','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C19',1,'mc','auto','하늘반 일지 ⑤의 ㉡에서 매트가 움푹 들어간 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X20']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C19","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑤의 ㉡에서 매트가 움푹 들어간 까닭은 무엇인가요?","options":[{"t":"압력이 높아졌기 때문에","correct":true},{"t":"온도가 높아졌기 때문에","mis":"SC4-2-u3-X25"},{"t":"압력이 낮아졌기 때문에","mis":"SC4-2-u3-X20"},{"t":"온도가 낮아졌기 때문에","mis":"SC4-2-u3-X25"}],"explanation":["㉡을 읽어요.","뛰어내려 눌렀어요.","압력이 높아졌어요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#6','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C23',1,'mc','auto','하늘반 일지 ⑥에서 타는 것을 돕고 호흡에 필요한 기체는 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X33','SC4-2-u3-X29']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C23","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑥에서 타는 것을 돕고 호흡에 필요한 기체는 무엇인가요?","options":[{"t":"산소","correct":true},{"t":"질소","mis":"SC4-2-u3-X31"},{"t":"이산화 탄소","mis":"SC4-2-u3-X33"},{"t":"헬륨","mis":"SC4-2-u3-X29"}],"explanation":["둘째 줄을 읽어요.","산소 캔이에요.","산소예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#7','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C27',1,'sa','auto','하늘반 일지 ⑦에서 틈을 막는 데 쓴 재료는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u3-C27","difficulty":1,"kind":"sa","stem":"하늘반 일지 ⑦에서 틈을 막는 데 쓴 재료는 무엇인가요? 두 글자로 쓰세요.","answer":["유토"],"explanation":["첫 줄을 읽어요.","틈을 막았어요.","유토예요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"},"mis":"SC4-2-u3-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#8','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C30',1,'mc','auto','하늘반 일지 ⑧에서 비행기의 엔진에서 나오는 것은 무엇인가요?',ARRAY['SC4-2-u3-X41']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C30","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑧에서 비행기의 엔진에서 나오는 것은 무엇인가요?","options":[{"t":"많은 양의 이산화 탄소","correct":true},{"t":"많은 양의 헬륨","mis":"SC4-2-u3-X41"},{"t":"아무것도 나오지 않는다","mis":"SC4-2-u3-X41"},{"t":"깨끗한 공기만 나온다","mis":"SC4-2-u3-X41"}],"explanation":["첫 줄을 읽어요.","환경오염을 유발해요.","이산화 탄소예요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#9','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C1',2,'mc','auto','기체에 대해 바르게 말한 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u3-X02']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C1","difficulty":2,"kind":"mc","stem":"기체에 대해 바르게 말한 것끼리 묶은 것은 무엇인가요?","options":[{"t":"대부분 눈에 보이지 않고, 담는 용기에 따라 모양이 바뀐다","correct":true},{"t":"언제나 눈에 보이고, 모양이 늘 같다","mis":"SC4-2-u3-X02"},{"t":"대부분 눈에 보이지 않고, 모양이 늘 같다","mis":"SC4-2-u3-X02"},{"t":"언제나 눈에 보이고, 용기에 따라 모양이 바뀐다","mis":"SC4-2-u3-X02"}],"explanation":["기체의 특징을 떠올려요.","보이지 않고 모양이 바뀌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#10','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C6',2,'blank','auto','「공기 주입 마개를 여러 번 누를수록 페트병의 무게가 (    ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C6","difficulty":2,"kind":"blank","stem":"「공기 주입 마개를 여러 번 누를수록 페트병의 무게가 (    ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"늘어나요","correct":true},{"t":"줄어들어요","mis":"SC4-2-u3-X08"},{"t":"그대로예요","mis":"SC4-2-u3-X08"},{"t":"사라져요","mis":"SC4-2-u3-X07"}],"explanation":["누를수록 공기가 들어가요.","무거워져요.","늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#11','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C12',2,'match','auto','실험 준비와 지킬 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC4-2-u3-C12","difficulty":2,"kind":"match","stem":"실험 준비와 지킬 일을 알맞게 이으세요.","pairs":[{"l":"풍선에 공기 넣기","r":"터지지 않게 덜 팽팽할 만큼만 넣기"},{"l":"머리 말리개 쓰기","r":"피부나 풍선에 가까이 하지 않기"},{"l":"얼음 다루기","r":"맛보거나 먹지 않기"}],"mis":"SC4-2-u3-X17","explanation":["안전 셋을 떠올려요.","하나씩 짝이 있어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#12','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C15',2,'ox','auto','피스톤에 닿지 않은 주사기 안 풍선도 피스톤을 누르면 작아져요.',ARRAY['SC4-2-u3-X21']::text[],false,'{"seq":12,"concept":"SC4-2-u3-C15","difficulty":2,"kind":"ox","stem":"피스톤에 닿지 않은 주사기 안 풍선도 피스톤을 누르면 작아져요.","answer":"O","reason_options":[{"t":"피스톤을 누르면 주사기 안 기체에 미치는 압력이 높아지기 때문에","correct":true},{"t":"피스톤이 풍선을 직접 눌러야만 작아지기 때문에","mis":"SC4-2-u3-X21"}],"mis":"SC4-2-u3-X21","explanation":["주사기 실험을 떠올려요.","닿지 않아도 작아졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#13','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C19',2,'error','auto','생활 속 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X26','SC4-2-u3-X25']::text[],false,'{"seq":13,"concept":"SC4-2-u3-C19","difficulty":2,"kind":"error","stem":"생활 속 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「부피가 줄어든 모습이 같으면 까닭도 늘 같아.」","correct":true,"mis_target":"SC4-2-u3-X26"},{"t":"친구 가 — 「땡볕의 비치 볼은 온도가 높아져서 팽팽해졌어.」","mis":"SC4-2-u3-X25"},{"t":"친구 나 — 「세게 찬 축구공은 압력이 높아져서 찌그러졌어.」","mis":"SC4-2-u3-X25"}],"explanation":["까닭을 따로 따져요.","같은 모습, 다른 까닭이 있어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#14','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C23',2,'mc','auto','등산할 때 쓰는 산소 캔에 산소를 이용하는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X33','SC4-2-u3-X31']::text[],false,'{"seq":14,"concept":"SC4-2-u3-C23","difficulty":2,"kind":"mc","stem":"등산할 때 쓰는 산소 캔에 산소를 이용하는 까닭은 무엇인가요?","options":[{"t":"산소가 생물의 호흡에 필요하기 때문에","correct":true},{"t":"산소가 톡 쏘는 맛을 내기 때문에","mis":"SC4-2-u3-X33"},{"t":"산소가 타는 것을 막기 때문에","mis":"SC4-2-u3-X31"},{"t":"산소가 반응을 거의 하지 않기 때문에","mis":"SC4-2-u3-X31"}],"explanation":["산을 오를 때를 떠올려요.","숨을 쉬어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#15','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C26',2,'ox','auto','장치를 냉장고 안에 넣으면 시럽이 내려가요.',ARRAY['SC4-2-u3-X36']::text[],false,'{"seq":15,"concept":"SC4-2-u3-C26","difficulty":2,"kind":"ox","stem":"장치를 냉장고 안에 넣으면 시럽이 내려가요.","answer":"O","reason_options":[{"t":"온도가 낮아지면서 약병 안 기체의 부피가 줄어들기 때문에","correct":true},{"t":"차가워지면 시럽이 무거워지기 때문에","mis":"SC4-2-u3-X36"}],"mis":"SC4-2-u3-X36","explanation":["냉장고는 차가워요.","부피가 줄어들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#16','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C32',2,'match','auto','비행기와 비행선의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC4-2-u3-C32","difficulty":2,"kind":"match","stem":"비행기와 비행선의 특징을 알맞게 이으세요.","pairs":[{"l":"비행기의 엔진","r":"많은 양의 이산화 탄소가 나와요"},{"l":"비행선의 엔진","r":"비행기에 비해 적게 사용해요"},{"l":"비행선이 뜨고 내리는 곳","r":"활주로가 없는 곳도 돼요"}],"mis":"SC4-2-u3-X43","explanation":["견주는 표를 떠올려요.","엔진과 뜨고 내리는 곳이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#17','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C5',3,'mc','auto','하늘반 일지 ②의 고무배, 페트병, 감압 용기 결과를 모두 설명하는 말은 무엇인가요?',ARRAY['SC4-2-u3-X07','SC4-2-u3-X08','SC4-2-u3-X09']::text[],false,'{"seq":17,"concept":"SC4-2-u3-C5","difficulty":3,"kind":"mc","stem":"하늘반 일지 ②의 고무배, 페트병, 감압 용기 결과를 모두 설명하는 말은 무엇인가요?","options":[{"t":"공기와 같은 기체도 무게가 있다","correct":true},{"t":"공기는 무게가 없다","mis":"SC4-2-u3-X07"},{"t":"공기를 넣으면 가벼워진다","mis":"SC4-2-u3-X08"},{"t":"공기를 빼면 무거워진다","mis":"SC4-2-u3-X09"}],"explanation":["세 결과를 견줘요.","공기의 양에 따라 무게가 달라졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#18','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C10',3,'mc','auto','하늘반 일지 ③의 결과를 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X14']::text[],false,'{"seq":18,"concept":"SC4-2-u3-C10","difficulty":3,"kind":"mc","stem":"하늘반 일지 ③의 결과를 바르게 정리한 것은 무엇인가요?","options":[{"t":"온도가 높아지면 기체의 부피가 늘어나고, 낮아지면 줄어든다","correct":true},{"t":"온도가 높아지면 줄어들고, 낮아지면 늘어난다","mis":"SC4-2-u3-X13"},{"t":"온도와 상관없이 부피는 그대로이다","mis":"SC4-2-u3-X14"},{"t":"온도가 높아지든 낮아지든 늘어난다","mis":"SC4-2-u3-X14"}],"explanation":["둘째와 셋째 줄을 견줘요.","방향이 반대예요.","첫 번째예요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#19','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C15',3,'mc','auto','하늘반 일지 ④의 결과를 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X21']::text[],false,'{"seq":19,"concept":"SC4-2-u3-C15","difficulty":3,"kind":"mc","stem":"하늘반 일지 ④의 결과를 바르게 정리한 것은 무엇인가요?","options":[{"t":"압력이 높아지면 기체의 부피가 줄어들고, 낮아지면 늘어난다","correct":true},{"t":"압력이 높아지면 늘어나고, 낮아지면 줄어든다","mis":"SC4-2-u3-X20"},{"t":"압력과 상관없이 부피는 그대로이다","mis":"SC4-2-u3-X20"},{"t":"풍선만 달라지고 공기는 그대로이다","mis":"SC4-2-u3-X21"}],"explanation":["둘째와 셋째 줄을 견줘요.","방향이 반대예요.","첫 번째예요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#20','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C19',3,'mc','auto','하늘반 일지 ⑤의 ㉡과 ㉢의 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X26']::text[],false,'{"seq":20,"concept":"SC4-2-u3-C19","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑤의 ㉡과 ㉢의 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"㉡ — 압력이 높아짐 / ㉢ — 온도가 낮아짐","correct":true},{"t":"㉡ — 온도가 낮아짐 / ㉢ — 압력이 높아짐","mis":"SC4-2-u3-X25"},{"t":"㉡ — 압력이 높아짐 / ㉢ — 압력이 높아짐","mis":"SC4-2-u3-X26"},{"t":"㉡ — 온도가 높아짐 / ㉢ — 온도가 높아짐","mis":"SC4-2-u3-X26"}],"explanation":["㉡은 뛰어내렸어요.","㉢은 냉장고예요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#21','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C25',3,'mc','auto','하늘반 일지 ⑥에서 이산화 탄소가 두 곳에 이용되는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X34','SC4-2-u3-X33']::text[],false,'{"seq":21,"concept":"SC4-2-u3-C25","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑥에서 이산화 탄소가 두 곳에 이용되는 까닭은 무엇인가요?","options":[{"t":"서로 다른 두 가지 성질이 있어 성질마다 맞는 곳에 이용되기 때문에","correct":true},{"t":"아무 곳에나 넣어도 되기 때문에","mis":"SC4-2-u3-X34"},{"t":"이용 사례를 외워 두었기 때문에","mis":"SC4-2-u3-X34"},{"t":"산소와 성질이 같기 때문에","mis":"SC4-2-u3-X33"}],"explanation":["셋째와 넷째 줄을 견줘요.","성질이 둘이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#22','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C32',3,'error','auto','하늘반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X43','SC4-2-u3-X42','SC4-2-u3-X41']::text[],false,'{"seq":22,"concept":"SC4-2-u3-C32","difficulty":3,"kind":"error","stem":"하늘반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「비행선은 엔진이 아예 없대.」","correct":true,"mis_target":"SC4-2-u3-X43"},{"t":"친구 나 — 「헬륨은 공기보다 가벼워서 떠올라.」","mis":"SC4-2-u3-X42"},{"t":"친구 다 — 「비행기 엔진에서는 이산화 탄소가 많이 나와.」","mis":"SC4-2-u3-X41"}],"explanation":["셋째 줄을 읽어요.","적게 써요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#23','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C10',4,'essay','teacher','하늘반 일지 ③을 보고 온도에 따른 기체의 부피 변화를 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u3-C10","difficulty":4,"kind":"essay","stem":"하늘반 일지 ③을 보고 온도에 따른 기체의 부피 변화를 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 온도가 높아지면 기체의 부피가 늘어나고, 온도가 낮아지면 기체의 부피가 줄어든다. 입구를 잘 닫았으므로 바람이 들어간 것이 아니라 풍선 안에 든 기체의 부피가 늘어나서 커진 것이다.","scoring_points":["온도가 높아질 때의 변화를 썼는가","온도가 낮아질 때의 변화를 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 변화를 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#24','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C19',4,'mc','auto','친구가 「여름에 튜브가 팽팽해진 것도, 에어 매트가 납작해진 것도 모두 온도 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X20','SC4-2-u3-X26']::text[],false,'{"seq":24,"concept":"SC4-2-u3-C19","difficulty":4,"kind":"mc","stem":"친구가 「여름에 튜브가 팽팽해진 것도, 에어 매트가 납작해진 것도 모두 온도 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「튜브는 온도가 높아져서 부피가 늘어났지만, 에어 매트는 앉아서 압력이 높아져 부피가 줄어든 거야.」","correct":true},{"t":"「맞아, 모두 온도 때문이야.」","mis":"SC4-2-u3-X25"},{"t":"「둘 다 압력이 낮아져서야.」","mis":"SC4-2-u3-X20"},{"t":"「모습이 다르니 둘 다 까닭을 알 수 없어.」","mis":"SC4-2-u3-X26"}],"explanation":["두 예를 따로 따져요.","하나는 온도, 하나는 압력이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_b#25','sci',4,2,'u3','','g4_2_sci_u3_review_b','unit_review','SC4-2-u3-C28',4,'essay','teacher','하늘반 일지 ⑦을 보고 장치가 움직이는 까닭을 온도와 기체의 부피로 설명하고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u3-C28","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑦을 보고 장치가 움직이는 까닭을 온도와 기체의 부피로 설명하고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 창가에 두면 온도가 높아져 약병 안 기체의 부피가 늘어나 시럽이 올라가고, 냉장고에 두면 온도가 낮아져 부피가 줄어들어 시럽이 내려간다. 반짝이를 더 붙인다고 잘 움직이는 것이 아니라 약병 안 공기의 부피 변화가 시럽을 움직인다.","scoring_points":["창가에서의 변화를 썼는가","냉장고에서의 변화를 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 곳의 변화를 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#1','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C4',1,'ox','auto','하늘반 일지 ①의 친구 가처럼 눈앞에 없는 물속 공기 방울을 떠올린 것도 이야기할 수 있어요.',ARRAY['SC4-2-u3-X06']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C4","difficulty":1,"kind":"ox","stem":"하늘반 일지 ①의 친구 가처럼 눈앞에 없는 물속 공기 방울을 떠올린 것도 이야기할 수 있어요.","answer":"O","reason_options":[{"t":"기체가 있는 상황은 정해진 몇 가지뿐이 아니기 때문에","correct":true},{"t":"눈앞에서 찾은 것만 답이 될 수 있기 때문에","mis":"SC4-2-u3-X06"}],"mis":"SC4-2-u3-X06","explanation":["넷째 줄을 읽어요.","까닭을 들어 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["운동장에서 공기가 있는 곳을 찾아보았다.","공 — 안에 공기가 들어 있어 팽팽하다.","부채 — 부채질을 하면 공기가 이동해 바람이 분다.","친구 가 — 「물속에서 올라오는 공기 방울도 생각났어.」"],"title":"하늘반 일지 ① 공기 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#2','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C7',1,'ox','auto','하늘반 일지 ②에서 감압 용기의 공기를 빼니 무게가 줄어들었어요.',ARRAY['SC4-2-u3-X09']::text[],false,'{"seq":2,"concept":"SC4-2-u3-C7","difficulty":1,"kind":"ox","stem":"하늘반 일지 ②에서 감압 용기의 공기를 빼니 무게가 줄어들었어요.","answer":"O","reason_options":[{"t":"용기 안의 공기가 빠져나갔기 때문에","correct":true},{"t":"공기를 빼도 무게는 늘어나기 때문에","mis":"SC4-2-u3-X09"}],"mis":"SC4-2-u3-X09","explanation":["넷째 줄을 읽어요.","공기가 빠졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#3','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C11',1,'ox','auto','하늘반 일지 ③의 친구 다 말처럼 바람이 풍선 안으로 들어가서 풍선이 커졌어요.',ARRAY['SC4-2-u3-X15']::text[],false,'{"seq":3,"concept":"SC4-2-u3-C11","difficulty":1,"kind":"ox","stem":"하늘반 일지 ③의 친구 다 말처럼 바람이 풍선 안으로 들어가서 풍선이 커졌어요.","answer":"X","reason_options":[{"t":"풍선의 입구를 잘 닫아 바람이 들어가지 않았기 때문에","correct":true},{"t":"머리 말리개 바람이 풍선 안을 채우기 때문에","mis":"SC4-2-u3-X15"}],"mis":"SC4-2-u3-X15","explanation":["첫 줄을 읽어요.","입구를 잘 닫았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#4','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C17',1,'ox','auto','하늘반 일지 ④에서 호핑볼에 앉으니 호핑볼 안 기체의 부피가 줄어들었어요.',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C17","difficulty":1,"kind":"ox","stem":"하늘반 일지 ④에서 호핑볼에 앉으니 호핑볼 안 기체의 부피가 줄어들었어요.","answer":"O","reason_options":[{"t":"앉으면 기체에 미치는 압력이 높아지기 때문에","correct":true},{"t":"앉으면 온도가 높아지기 때문에","mis":"SC4-2-u3-X25"}],"mis":"SC4-2-u3-X25","explanation":["넷째 줄을 읽어요.","몸으로 눌렀어요.","그래서 O예요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#5','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C20',1,'ox','auto','하늘반 일지 ⑤처럼 조사한 자료마다 출처를 적어 두어요.',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":5,"concept":"SC4-2-u3-C20","difficulty":1,"kind":"ox","stem":"하늘반 일지 ⑤처럼 조사한 자료마다 출처를 적어 두어요.","answer":"O","reason_options":[{"t":"옳은 정보인지 다시 확인할 수 있기 때문에","correct":true},{"t":"누리망 정보는 모두 옳아서 출처는 장식이기 때문에","mis":"SC4-2-u3-X28"}],"mis":"SC4-2-u3-X28","explanation":["넷째 줄을 읽어요.","다시 확인할 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#6','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C24',1,'ox','auto','하늘반 일지 ⑥에서 이산화 탄소는 탄산음료와 소화기에 모두 이용돼요.',ARRAY['SC4-2-u3-X33']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C24","difficulty":1,"kind":"ox","stem":"하늘반 일지 ⑥에서 이산화 탄소는 탄산음료와 소화기에 모두 이용돼요.","answer":"O","reason_options":[{"t":"톡 쏘는 맛과 타는 것을 막는 성질이 함께 있기 때문에","correct":true},{"t":"이산화 탄소는 타는 것을 돕기 때문에","mis":"SC4-2-u3-X33"}],"mis":"SC4-2-u3-X33","explanation":["셋째와 넷째 줄을 읽어요.","두 곳에 쓰여요.","그래서 O예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#7','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C28',1,'ox','auto','하늘반 일지 ⑦의 친구 나 말처럼 꾸밈을 더 붙이면 장치가 더 잘 움직여요.',ARRAY['SC4-2-u3-X39']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C28","difficulty":1,"kind":"ox","stem":"하늘반 일지 ⑦의 친구 나 말처럼 꾸밈을 더 붙이면 장치가 더 잘 움직여요.","answer":"X","reason_options":[{"t":"장치를 움직이는 것은 꾸밈이 아니라 약병 안 공기의 부피 변화이기 때문에","correct":true},{"t":"꾸밀수록 시럽이 가벼워지기 때문에","mis":"SC4-2-u3-X39"}],"mis":"SC4-2-u3-X39","explanation":["넷째 줄을 따져요.","움직이는 까닭은 공기예요.","그래서 X예요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#8','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C32',1,'ox','auto','하늘반 일지 ⑧의 친구 가 말처럼 비행선은 엔진이 아예 없어요.',ARRAY['SC4-2-u3-X43']::text[],false,'{"seq":8,"concept":"SC4-2-u3-C32","difficulty":1,"kind":"ox","stem":"하늘반 일지 ⑧의 친구 가 말처럼 비행선은 엔진이 아예 없어요.","answer":"X","reason_options":[{"t":"비행선은 비행기에 비해 엔진을 적게 쓰는 것이기 때문에","correct":true},{"t":"헬륨이 있으면 엔진이 전혀 필요 없기 때문에","mis":"SC4-2-u3-X43"}],"mis":"SC4-2-u3-X43","explanation":["셋째 줄을 읽어요.","적게 써요.","그래서 X예요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#9','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C2',2,'error','auto','숨이를 단서로 기체를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u3-X03','SC4-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C2","difficulty":2,"kind":"error","stem":"숨이를 단서로 기체를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「숨이를 가장 빨리 찾는 게 이 활동의 목표야.」","correct":true,"mis_target":"SC4-2-u3-X03"},{"t":"친구 가 — 「숨이는 기체를 찾는 단서야.」","mis":"SC4-2-u3-X03"},{"t":"친구 다 — 「◯표는 기체가 있는 부분에 하자.」","mis":"SC4-2-u3-X04"}],"explanation":["활동의 목표를 떠올려요.","숨이는 단서예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#10','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C9',2,'mc','auto','공기를 많이 넣은 공기 주입 마개를 열 때 조심해야 하는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X12']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C9","difficulty":2,"kind":"mc","stem":"공기를 많이 넣은 공기 주입 마개를 열 때 조심해야 하는 까닭은 무엇인가요?","options":[{"t":"큰 소리가 나고 마개가 튕겨 나갈 수 있기 때문에","correct":true},{"t":"마개가 무거워지기 때문에","mis":"SC4-2-u3-X12"},{"t":"공기가 보이지 않기 때문에","mis":"SC4-2-u3-X12"},{"t":"전자저울이 고장 나기 때문에","mis":"SC4-2-u3-X12"}],"explanation":["안전을 떠올려요.","튕겨 나갈 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#11','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C10',2,'ox','auto','온도가 높아지면 기체의 부피는 줄어들어요.',ARRAY['SC4-2-u3-X13']::text[],false,'{"seq":11,"concept":"SC4-2-u3-C10","difficulty":2,"kind":"ox","stem":"온도가 높아지면 기체의 부피는 줄어들어요.","answer":"X","reason_options":[{"t":"온도가 높아지면 기체의 부피는 늘어나기 때문에","correct":true},{"t":"따뜻해지면 기체가 작아지기 때문에","mis":"SC4-2-u3-X13"}],"mis":"SC4-2-u3-X13","explanation":["따뜻한 바람을 떠올려요.","부풀어 올랐어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#12','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C16',2,'mc','auto','주사기 안에 풍선을 넣으려고 분리할 때 먼저 빼는 것은 무엇인가요?',ARRAY['SC4-2-u3-X22']::text[],false,'{"seq":12,"concept":"SC4-2-u3-C16","difficulty":2,"kind":"mc","stem":"주사기 안에 풍선을 넣으려고 분리할 때 먼저 빼는 것은 무엇인가요?","options":[{"t":"주사기 마개","correct":true},{"t":"피스톤","mis":"SC4-2-u3-X22"},{"t":"주사기 안의 풍선","mis":"SC4-2-u3-X22"},{"t":"보안경","mis":"SC4-2-u3-X22"}],"explanation":["분리하는 차례를 떠올려요.","입구를 막은 것이에요.","주사기 마개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#13','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C20',2,'blank','auto','「조사한 정보가 다른 사람에게 (    ) 내용인지 판단해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":13,"concept":"SC4-2-u3-C20","difficulty":2,"kind":"blank","stem":"「조사한 정보가 다른 사람에게 (    ) 내용인지 판단해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전달해도 되는","correct":true},{"t":"숨겨야 하는","mis":"SC4-2-u3-X28"},{"t":"외워야 하는","mis":"SC4-2-u3-X28"},{"t":"꾸며야 하는","mis":"SC4-2-u3-X28"}],"explanation":["조사의 규칙을 떠올려요.","전해도 되는지 살펴요.","전달해도 되는이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#14','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C24',2,'ox','auto','이산화 탄소는 물처럼 스스로 불을 꺼 버려요.',ARRAY['SC4-2-u3-X32']::text[],false,'{"seq":14,"concept":"SC4-2-u3-C24","difficulty":2,"kind":"ox","stem":"이산화 탄소는 물처럼 스스로 불을 꺼 버려요.","answer":"X","reason_options":[{"t":"이산화 탄소는 다른 물질이 타는 것을 막는 성질이 있는 것이기 때문에","correct":true},{"t":"이산화 탄소는 물과 같은 것이기 때문에","mis":"SC4-2-u3-X32"}],"mis":"SC4-2-u3-X32","explanation":["소화기를 떠올려요.","타는 것을 막아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#15','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C29',2,'mc','auto','옳은 내용이 쓰인 풍선은 무엇인가요?',ARRAY['SC4-2-u3-X31','SC4-2-u3-X08','SC4-2-u3-X20']::text[],false,'{"seq":15,"concept":"SC4-2-u3-C29","difficulty":2,"kind":"mc","stem":"옳은 내용이 쓰인 풍선은 무엇인가요?","options":[{"t":"「병원에서 쓰는 환자의 호흡 장치에 산소를 이용할 수 있어요.」","correct":true},{"t":"「불을 끄는 소화기에 산소를 이용할 수 있어요.」","mis":"SC4-2-u3-X31"},{"t":"「축구공에 공기를 더 넣을수록 무게가 줄어들어요.」","mis":"SC4-2-u3-X08"},{"t":"「압력이 높아지면 기체의 부피가 늘어나요.」","mis":"SC4-2-u3-X20"}],"explanation":["하나씩 따져요.","산소는 호흡에 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#16','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C30',2,'ox','auto','비행기 엔진에서 나오는 많은 양의 이산화 탄소는 환경오염을 유발해요.',ARRAY['SC4-2-u3-X41']::text[],false,'{"seq":16,"concept":"SC4-2-u3-C30","difficulty":2,"kind":"ox","stem":"비행기 엔진에서 나오는 많은 양의 이산화 탄소는 환경오염을 유발해요.","answer":"O","reason_options":[{"t":"이산화 탄소가 많이 나오면 환경에 나쁜 영향을 주기 때문에","correct":true},{"t":"이산화 탄소는 비행기를 띄우는 기체이기 때문에","mis":"SC4-2-u3-X41"}],"mis":"SC4-2-u3-X41","explanation":["비행기의 문제를 떠올려요.","환경에 나빠요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#17','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C8',3,'mc','auto','하늘반 일지 ②처럼 공기의 양에 따라 무게가 달라진다는 것을 이용하면 무엇을 알아낼 수 있나요?',ARRAY['SC4-2-u3-X11','SC4-2-u3-X10','SC4-2-u3-X07']::text[],false,'{"seq":17,"concept":"SC4-2-u3-C8","difficulty":3,"kind":"mc","stem":"하늘반 일지 ②처럼 공기의 양에 따라 무게가 달라진다는 것을 이용하면 무엇을 알아낼 수 있나요?","options":[{"t":"모양과 크기가 같은 두 고무배 가운데 공기가 더 많이 든 것","correct":true},{"t":"고무배의 색깔","mis":"SC4-2-u3-X11"},{"t":"공기만의 정확한 무게","mis":"SC4-2-u3-X10"},{"t":"공기가 눈에 보이는 곳","mis":"SC4-2-u3-X07"}],"explanation":["무게를 비교해요.","공기가 많으면 무거워요.","첫 번째예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#18','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C13',3,'mc','auto','하늘반 일지 ③의 결과로 설명할 수 있는 생활 속 모습은 무엇인가요?',ARRAY['SC4-2-u3-X25','SC4-2-u3-X07']::text[],false,'{"seq":18,"concept":"SC4-2-u3-C13","difficulty":3,"kind":"mc","stem":"하늘반 일지 ③의 결과로 설명할 수 있는 생활 속 모습은 무엇인가요?","options":[{"t":"추운 바깥에 둔 풍선이 쭈그러든다","correct":true},{"t":"호핑볼에 앉으면 납작해진다","mis":"SC4-2-u3-X25"},{"t":"배구공을 세게 치면 찌그러진다","mis":"SC4-2-u3-X25"},{"t":"페트병에 공기를 넣으면 무거워진다","mis":"SC4-2-u3-X07"}],"explanation":["온도 때문인 것을 찾아요.","추운 바깥이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#19','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C17',3,'mc','auto','하늘반 일지 ④의 호핑볼과 같은 까닭으로 부피가 달라진 예는 무엇인가요?',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":19,"concept":"SC4-2-u3-C17","difficulty":3,"kind":"mc","stem":"하늘반 일지 ④의 호핑볼과 같은 까닭으로 부피가 달라진 예는 무엇인가요?","options":[{"t":"세게 친 배구공이 찌그러진다","correct":true},{"t":"냉장고 속 페트병이 쭈그러든다","mis":"SC4-2-u3-X25"},{"t":"땡볕 아래 튜브가 팽팽해진다","mis":"SC4-2-u3-X25"},{"t":"열기구가 부풀어 오른다","mis":"SC4-2-u3-X25"}],"explanation":["호핑볼은 압력 때문이에요.","누르는 힘을 찾아요.","첫 번째예요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#20','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C18',3,'mc','auto','하늘반 일지 ⑤의 ㉠ 튜브를 시원한 그늘로 옮기면 어떻게 될까요?',ARRAY['SC4-2-u3-X13','SC4-2-u3-X25','SC4-2-u3-X27']::text[],false,'{"seq":20,"concept":"SC4-2-u3-C18","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑤의 ㉠ 튜브를 시원한 그늘로 옮기면 어떻게 될까요?","options":[{"t":"온도가 낮아지면서 공기의 부피가 줄어 조금 작아진다","correct":true},{"t":"더 팽팽해진다","mis":"SC4-2-u3-X13"},{"t":"그늘에서는 압력이 높아져 작아진다","mis":"SC4-2-u3-X25"},{"t":"한 번 팽팽해지면 그대로이다","mis":"SC4-2-u3-X27"}],"explanation":["그늘은 시원해요.","온도가 낮아져요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#21','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C22',3,'mc','auto','하늘반 일지 ⑥에서 질소를 과자 봉지에 넣는 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X30']::text[],false,'{"seq":21,"concept":"SC4-2-u3-C22","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑥에서 질소를 과자 봉지에 넣는 까닭은 무엇인가요?","options":[{"t":"반응을 거의 하지 않는 안정된 성질이 있어 과자를 오랫동안 보관할 수 있기 때문에","correct":true},{"t":"톡 쏘는 맛을 내기 위해서","mis":"SC4-2-u3-X30"},{"t":"과자가 잘 타도록 돕기 위해서","mis":"SC4-2-u3-X30"},{"t":"과자가 숨을 쉬게 하기 위해서","mis":"SC4-2-u3-X30"}],"explanation":["첫 줄을 읽어요.","안정된 성질이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#22','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C26',3,'mc','auto','하늘반 일지 ⑦의 장치가 이용한 것은 무엇인가요?',ARRAY['SC4-2-u3-X36','SC4-2-u3-X40']::text[],false,'{"seq":22,"concept":"SC4-2-u3-C26","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑦의 장치가 이용한 것은 무엇인가요?","options":[{"t":"온도에 따라 기체의 부피가 달라지는 성질","correct":true},{"t":"압력에 따라 기체의 무게가 달라지는 성질","mis":"SC4-2-u3-X36"},{"t":"시럽이 따뜻해지면 가벼워지는 성질","mis":"SC4-2-u3-X36"},{"t":"특별한 기체가 스스로 움직이는 성질","mis":"SC4-2-u3-X40"}],"explanation":["셋째 줄을 읽어요.","창가와 냉장고예요.","첫 번째예요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#23','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C15',4,'essay','teacher','하늘반 일지 ④를 보고 압력에 따른 기체의 부피 변화를 쓰고, 호핑볼에 앉을 때의 변화를 압력과 함께 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u3-C15","difficulty":4,"kind":"essay","stem":"하늘반 일지 ④를 보고 압력에 따른 기체의 부피 변화를 쓰고, 호핑볼에 앉을 때의 변화를 압력과 함께 설명하세요.","answer_guide":{"answer":"예: 압력이 높아지면 기체의 부피가 줄어들고, 압력이 낮아지면 기체의 부피가 늘어난다. 호핑볼에 앉으면 호핑볼 안 기체에 미치는 압력이 높아져 부피가 줄어들어 납작해진다.","scoring_points":["압력이 높아질 때의 변화를 썼는가","압력이 낮아질 때의 변화를 썼는가","호핑볼의 변화를 압력으로 설명했는가"]},"explanation":["일지를 읽어요.","두 변화를 써요.","호핑볼을 설명해요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#24','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C25',4,'mc','auto','친구가 「기체 이름과 쓰이는 곳만 짝지어 두면 공부 끝이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X34','SC4-2-u3-X31']::text[],false,'{"seq":24,"concept":"SC4-2-u3-C25","difficulty":4,"kind":"mc","stem":"친구가 「기체 이름과 쓰이는 곳만 짝지어 두면 공부 끝이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「기체마다 성질이 있어서 그 성질에 맞게 쓰여. 성질과 이어서 이해하면 처음 보는 예도 알 수 있어.」","correct":true},{"t":"「맞아, 짝만 기억하면 돼.」","mis":"SC4-2-u3-X34"},{"t":"「모든 기체는 성질이 같아.」","mis":"SC4-2-u3-X34"},{"t":"「산소는 불을 끄는 데 써.」","mis":"SC4-2-u3-X31"}],"explanation":["성질과 이용을 이어 봐요.","성질이 먼저예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_c#25','sci',4,2,'u3','','g4_2_sci_u3_review_c','unit_review','SC4-2-u3-C32',4,'essay','teacher','하늘반 일지 ⑧을 보고 비행선이 떠오르는 까닭과 비행기와 견준 좋은 점을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u3-C32","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑧을 보고 비행선이 떠오르는 까닭과 비행기와 견준 좋은 점을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 비행선은 공기보다 가벼운 헬륨이 들어 있어 떠오른다. 비행기에 비해 엔진을 적게 써서 이산화 탄소를 덜 내보낸다. 비행선은 엔진이 아예 없는 것이 아니라 비행기에 비해 엔진을 적게 쓰는 것이다.","scoring_points":["떠오르는 까닭을 썼는가","비행기와 견준 좋은 점을 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","까닭과 좋은 점을 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#1','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C1',1,'mc','auto','하늘반 일지 ①로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u3-X01','SC4-2-u3-X04']::text[],false,'{"seq":1,"concept":"SC4-2-u3-C1","difficulty":1,"kind":"mc","stem":"하늘반 일지 ①로 알 수 있는 것은 무엇인가요?","options":[{"t":"눈으로 볼 수 없어도 여러 상황에서 공기가 있다는 것을 알 수 있다","correct":true},{"t":"공기는 눈으로 보여야만 있다","mis":"SC4-2-u3-X01"},{"t":"공기는 공 안에만 있다","mis":"SC4-2-u3-X04"},{"t":"공기는 색깔을 보고 찾는다","mis":"SC4-2-u3-X01"}],"explanation":["일지 전체를 읽어요.","공과 부채에서 알았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동장에서 공기가 있는 곳을 찾아보았다.","공 — 안에 공기가 들어 있어 팽팽하다.","부채 — 부채질을 하면 공기가 이동해 바람이 분다.","친구 가 — 「물속에서 올라오는 공기 방울도 생각났어.」"],"title":"하늘반 일지 ① 공기 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#2','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C5',1,'sa','auto','하늘반 일지 ②로 알 수 있는 것을 쓰세요. 「공기와 같은 기체도 ○○가 있다.」의 ○○에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u3-C5","difficulty":1,"kind":"sa","stem":"하늘반 일지 ②로 알 수 있는 것을 쓰세요. 「공기와 같은 기체도 ○○가 있다.」의 ○○에 알맞은 말을 두 글자로 쓰세요.","answer":["무게"],"explanation":["일지 전체를 읽어요.","저울로 잰 것이에요.","무게예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"},"mis":"SC4-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#3','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C10',1,'sa','auto','하늘반 일지 ③으로 알 수 있는 것을 쓰세요. 「기체의 부피는 ○○에 따라 달라진다.」의 ○○에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC4-2-u3-C10","difficulty":1,"kind":"sa","stem":"하늘반 일지 ③으로 알 수 있는 것을 쓰세요. 「기체의 부피는 ○○에 따라 달라진다.」의 ○○에 알맞은 말을 두 글자로 쓰세요.","answer":["온도"],"explanation":["따뜻할 때와 차가울 때를 견줘요.","덥고 추운 정도예요.","온도예요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"},"mis":"SC4-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#4','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C15',1,'mc','auto','하늘반 일지 ④에서 피스톤을 당겼을 때 압력과 부피를 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X19']::text[],false,'{"seq":4,"concept":"SC4-2-u3-C15","difficulty":1,"kind":"mc","stem":"하늘반 일지 ④에서 피스톤을 당겼을 때 압력과 부피를 바르게 말한 것은 무엇인가요?","options":[{"t":"압력이 낮아지고 부피가 늘어났다","correct":true},{"t":"압력이 높아지고 부피가 늘어났다","mis":"SC4-2-u3-X20"},{"t":"압력이 낮아지고 부피가 줄어들었다","mis":"SC4-2-u3-X20"},{"t":"압력이 높아지고 부피가 줄어들었다","mis":"SC4-2-u3-X19"}],"explanation":["셋째 줄을 읽어요.","당기면 덜 눌러요.","첫 번째예요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#5','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C19',1,'sa','auto','하늘반 일지 ⑤의 ㉢에서 비닐 랩이 오목해진 까닭은 온도가 어떻게 되었기 때문인가요? 「온도가 ○○졌다」의 ○○를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u3-C19","difficulty":1,"kind":"sa","stem":"하늘반 일지 ⑤의 ㉢에서 비닐 랩이 오목해진 까닭은 온도가 어떻게 되었기 때문인가요? 「온도가 ○○졌다」의 ○○를 쓰세요.","answer":["낮아"],"explanation":["㉢을 읽어요.","냉장고는 차가워요.","낮아졌어요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"},"mis":"SC4-2-u3-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#6','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C25',1,'mc','auto','하늘반 일지 ⑥을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u3-X34']::text[],false,'{"seq":6,"concept":"SC4-2-u3-C25","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑥을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"여러 가지 기체는 각각의 성질에 맞게 이용된다","correct":true},{"t":"기체의 이용은 성질과 상관없다","mis":"SC4-2-u3-X34"},{"t":"모든 기체의 성질은 같다","mis":"SC4-2-u3-X34"},{"t":"이용 사례는 외우기만 하면 된다","mis":"SC4-2-u3-X34"}],"explanation":["성질과 이용을 이어 봐요.","줄마다 짝이 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#7','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C26',1,'mc','auto','하늘반 일지 ⑦의 장치를 움직이는 것은 무엇인가요?',ARRAY['SC4-2-u3-X36','SC4-2-u3-X39','SC4-2-u3-X40']::text[],false,'{"seq":7,"concept":"SC4-2-u3-C26","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑦의 장치를 움직이는 것은 무엇인가요?","options":[{"t":"약병 안 공기","correct":true},{"t":"시럽의 무게","mis":"SC4-2-u3-X36"},{"t":"빨대의 색깔","mis":"SC4-2-u3-X39"},{"t":"따로 넣은 특별한 기체","mis":"SC4-2-u3-X40"}],"explanation":["약병 안을 떠올려요.","부피가 달라져요.","약병 안 공기예요."],"asset":{"type":"passage","lines":["약병에 빨대를 꽂고 유토로 틈을 막았다.","빨대 중간에 색소를 섞은 시럽 한 방울을 넣었다.","창가에 두니 시럽이 올라가고, 냉장고에 두니 내려갔다.","친구 나 — 「반짝이를 더 붙이면 더 잘 움직일 거야.」"],"title":"하늘반 일지 ⑦ 시럽 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#8','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C31',1,'sa','auto','하늘반 일지 ⑧에서 헬륨은 공기보다 어떻기 때문에 비행선이 떠오르나요? 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC4-2-u3-C31","difficulty":1,"kind":"sa","stem":"하늘반 일지 ⑧에서 헬륨은 공기보다 어떻기 때문에 비행선이 떠오르나요? 알맞은 말을 쓰세요.","answer":["가볍기","가벼워서","가볍다","가벼움","가벼워"],"explanation":["둘째 줄을 읽어요.","무겁지 않아요.","가볍기 때문이에요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"},"mis":"SC4-2-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#9','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C4',2,'mc','auto','친구와 찾은 것이 달랐을 때 알맞은 태도는 무엇인가요?',ARRAY['SC4-2-u3-X06','SC4-2-u3-X03']::text[],false,'{"seq":9,"concept":"SC4-2-u3-C4","difficulty":2,"kind":"mc","stem":"친구와 찾은 것이 달랐을 때 알맞은 태도는 무엇인가요?","options":[{"t":"서로 그렇게 생각한 까닭을 이야기하고 들어 본다","correct":true},{"t":"내가 찾은 것만 맞다고 한다","mis":"SC4-2-u3-X06"},{"t":"그림에 없는 것은 모두 지운다","mis":"SC4-2-u3-X06"},{"t":"숨이를 먼저 찾은 사람 말을 따른다","mis":"SC4-2-u3-X03"}],"explanation":["비교할 때를 떠올려요.","까닭을 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#10','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C8',2,'ox','auto','모양과 크기가 똑같은 두 축구공 가운데 공기가 더 많이 든 것은 무게를 재어 알아낼 수 있어요.',ARRAY['SC4-2-u3-X11']::text[],false,'{"seq":10,"concept":"SC4-2-u3-C8","difficulty":2,"kind":"ox","stem":"모양과 크기가 똑같은 두 축구공 가운데 공기가 더 많이 든 것은 무게를 재어 알아낼 수 있어요.","answer":"O","reason_options":[{"t":"공기가 많이 들어 있을수록 더 무겁기 때문에","correct":true},{"t":"모양과 크기가 같으면 무게도 늘 같기 때문에","mis":"SC4-2-u3-X11"}],"mis":"SC4-2-u3-X11","explanation":["공기통 문제를 떠올려요.","무게를 비교해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#11','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C11',2,'mc','auto','포일 풍선 실험에서 가장 중요하게 살필 것은 무엇인가요?',ARRAY['SC4-2-u3-X16','SC4-2-u3-X15']::text[],false,'{"seq":11,"concept":"SC4-2-u3-C11","difficulty":2,"kind":"mc","stem":"포일 풍선 실험에서 가장 중요하게 살필 것은 무엇인가요?","options":[{"t":"온도에 따라 풍선 안 기체의 부피가 어떻게 변하는지","correct":true},{"t":"풍선의 정확한 크기","mis":"SC4-2-u3-X16"},{"t":"풍선 안으로 바람이 얼마나 들어가는지","mis":"SC4-2-u3-X15"},{"t":"풍선의 색깔","mis":"SC4-2-u3-X16"}],"explanation":["무엇을 알아보는 실험인가요?","부피 변화예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#12','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C17',2,'mc','auto','운동화를 신고 발로 땅을 디딜 때 밑창 속 공기 주머니의 부피는 어떻게 되나요?',ARRAY['SC4-2-u3-X20','SC4-2-u3-X24']::text[],false,'{"seq":12,"concept":"SC4-2-u3-C17","difficulty":2,"kind":"mc","stem":"운동화를 신고 발로 땅을 디딜 때 밑창 속 공기 주머니의 부피는 어떻게 되나요?","options":[{"t":"줄어든다","correct":true},{"t":"늘어난다","mis":"SC4-2-u3-X20"},{"t":"그대로이다","mis":"SC4-2-u3-X24"},{"t":"공기가 사라진다","mis":"SC4-2-u3-X24"}],"explanation":["디딜 때 눌러요.","압력이 높아져요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#13','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C19',2,'mc','auto','온도 때문에 기체의 부피가 달라진 예는 무엇인가요?',ARRAY['SC4-2-u3-X25']::text[],false,'{"seq":13,"concept":"SC4-2-u3-C19","difficulty":2,"kind":"mc","stem":"온도 때문에 기체의 부피가 달라진 예는 무엇인가요?","options":[{"t":"냉장고에 넣어 둔 용기의 비닐 랩이 오목해졌다","correct":true},{"t":"호핑볼에 앉으니 납작해졌다","mis":"SC4-2-u3-X25"},{"t":"축구공을 세게 차니 찌그러졌다","mis":"SC4-2-u3-X25"},{"t":"에어 매트에 앉으니 납작해졌다","mis":"SC4-2-u3-X25"}],"explanation":["누르는 것과 차갑게 하는 것을 나눠요.","냉장고를 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#14','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C21',2,'mc','auto','과자 봉지에 어떤 기체가 들어 있는지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X29']::text[],false,'{"seq":14,"concept":"SC4-2-u3-C21","difficulty":2,"kind":"mc","stem":"과자 봉지에 어떤 기체가 들어 있는지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"제품 설명 부분을 돋보기로 살펴본다","correct":true},{"t":"봉지를 흔들어 소리로 짐작한다","mis":"SC4-2-u3-X29"},{"t":"과자 색깔을 보고 짐작한다","mis":"SC4-2-u3-X29"},{"t":"봉지를 들고 친구와 장난친다","mis":"SC4-2-u3-X29"}],"explanation":["제품 겉면을 떠올려요.","설명이 적혀 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#15','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C28',2,'mc','auto','만든 장치가 잘 되었는지 살필 때 알맞은 물음은 무엇인가요?',ARRAY['SC4-2-u3-X39','SC4-2-u3-X40']::text[],false,'{"seq":15,"concept":"SC4-2-u3-C28","difficulty":2,"kind":"mc","stem":"만든 장치가 잘 되었는지 살필 때 알맞은 물음은 무엇인가요?","options":[{"t":"만든 장치가 알맞게 작동했나요?","correct":true},{"t":"가장 화려하게 꾸몄나요?","mis":"SC4-2-u3-X39"},{"t":"가장 비싼 약병을 썼나요?","mis":"SC4-2-u3-X39"},{"t":"특별한 기체를 따로 넣었나요?","mis":"SC4-2-u3-X40"}],"explanation":["평가 기준을 떠올려요.","작동이 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#16','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C33',2,'mc','auto','기체를 이용한 친환경 제품을 떠올릴 때 가장 알맞은 생각은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X41']::text[],false,'{"seq":16,"concept":"SC4-2-u3-C33","difficulty":2,"kind":"mc","stem":"기체를 이용한 친환경 제품을 떠올릴 때 가장 알맞은 생각은 무엇인가요?","options":[{"t":"기체의 성질을 이용해 환경오염 물질을 줄일 방법을 찾는다","correct":true},{"t":"엔진을 더 크게 만든다","mis":"SC4-2-u3-X45"},{"t":"이산화 탄소를 더 많이 뿜게 한다","mis":"SC4-2-u3-X45"},{"t":"기체는 환경과 상관없다고 여긴다","mis":"SC4-2-u3-X41"}],"explanation":["친환경의 뜻을 떠올려요.","오염을 줄여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#17','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C7',3,'mc','auto','하늘반 일지 ②에서 감압 용기의 무게가 줄어든 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X08','SC4-2-u3-X07','SC4-2-u3-X09']::text[],false,'{"seq":17,"concept":"SC4-2-u3-C7","difficulty":3,"kind":"mc","stem":"하늘반 일지 ②에서 감압 용기의 무게가 줄어든 까닭은 무엇인가요?","options":[{"t":"펌프로 용기 안의 공기를 빼냈기 때문에","correct":true},{"t":"용기에 공기를 더 넣었기 때문에","mis":"SC4-2-u3-X08"},{"t":"공기는 무게가 없기 때문에","mis":"SC4-2-u3-X07"},{"t":"공기를 빼면 무게가 늘어나기 때문에","mis":"SC4-2-u3-X09"}],"explanation":["넷째 줄을 읽어요.","공기를 빼냈어요.","첫 번째예요."],"asset":{"type":"passage","lines":["쭈글쭈글한 고무배와 공기를 가득 넣은 고무배를 들어 보았다.","공기를 가득 넣은 고무배가 더 무거웠다.","페트병에 공기를 넣으니 무게가 늘어났다.","감압 용기에서 공기를 빼니 무게가 줄어들었다."],"title":"하늘반 일지 ② 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#18','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C12',3,'mc','auto','하늘반 일지 ③의 실험을 할 때 지켜야 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X17']::text[],false,'{"seq":18,"concept":"SC4-2-u3-C12","difficulty":3,"kind":"mc","stem":"하늘반 일지 ③의 실험을 할 때 지켜야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"얼음을 맛보거나 먹지 않는다","correct":true},{"t":"얼음을 조금 맛본다","mis":"SC4-2-u3-X17"},{"t":"풍선에 공기를 터지기 직전까지 넣는다","mis":"SC4-2-u3-X17"},{"t":"머리 말리개를 풍선에 바짝 댄다","mis":"SC4-2-u3-X17"}],"explanation":["안전 셋을 떠올려요.","얼음도 조심해요.","첫 번째예요."],"asset":{"type":"passage","lines":["포일 풍선에 공기를 넣고 입구를 잘 닫았다.","따뜻한 바람을 쏘이니 풍선이 부풀어 올랐다.","얼음이 담긴 수조에 넣으니 풍선이 쭈그러들었다.","친구 다 — 「바람이 풍선 안으로 들어가서 커진 거야.」"],"title":"하늘반 일지 ③ 온도와 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#19','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C16',3,'mc','auto','하늘반 일지 ④처럼 주사기 실험을 할 때 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u3-X22','SC4-2-u3-X23']::text[],false,'{"seq":19,"concept":"SC4-2-u3-C16","difficulty":3,"kind":"mc","stem":"하늘반 일지 ④처럼 주사기 실험을 할 때 알맞은 것은 무엇인가요?","options":[{"t":"입구를 주사기 마개로 막고, 부피가 어떻게 변하는지 살핀다","correct":true},{"t":"입구를 열어 둔 채 피스톤을 누른다","mis":"SC4-2-u3-X22"},{"t":"눈금 숫자를 정확히 읽는 데만 집중한다","mis":"SC4-2-u3-X23"},{"t":"피스톤을 먼저 뽑고 마개를 뺀다","mis":"SC4-2-u3-X22"}],"explanation":["첫 줄을 읽어요.","입구를 막았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["주사기에 공기와 작은 풍선을 넣고 입구를 막았다.","피스톤을 누르니 공기와 풍선이 함께 작아졌다.","피스톤을 당기니 공기와 풍선이 함께 커졌다.","호핑볼에 앉으니 호핑볼이 납작해졌다."],"title":"하늘반 일지 ④ 압력과 부피"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#20','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C20',3,'mc','auto','하늘반 일지 ⑤처럼 조사할 때 알맞은 검색어는 무엇인가요?',ARRAY['SC4-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC4-2-u3-C20","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑤처럼 조사할 때 알맞은 검색어는 무엇인가요?","options":[{"t":"압력에 따른 기체의 부피 변화의 예","correct":true},{"t":"기체 문제 정답","mis":"SC4-2-u3-X28"},{"t":"아무 낱말 한 글자","mis":"SC4-2-u3-X28"},{"t":"친구 사진","mis":"SC4-2-u3-X28"}],"explanation":["무엇을 찾나요?","부피가 달라지는 예예요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#21','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C21',3,'mc','auto','하늘반 일지 ⑥처럼 제품 속 기체를 조사할 때 알맞은 태도는 무엇인가요?',ARRAY['SC4-2-u3-X29','SC4-2-u3-X28']::text[],false,'{"seq":21,"concept":"SC4-2-u3-C21","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑥처럼 제품 속 기체를 조사할 때 알맞은 태도는 무엇인가요?","options":[{"t":"제품 설명을 살피고, 조사한 정보의 출처를 확인한다","correct":true},{"t":"제품 겉면을 보지 않고 짐작한다","mis":"SC4-2-u3-X29"},{"t":"출처 없는 정보를 그대로 옮긴다","mis":"SC4-2-u3-X28"},{"t":"준비물로 장난을 친다","mis":"SC4-2-u3-X29"}],"explanation":["조사의 규칙을 떠올려요.","제품 설명과 출처예요.","첫 번째예요."],"asset":{"type":"passage","lines":["과자 봉지 — 질소, 반응을 거의 하지 않는 안정된 성질","산소 캔 — 산소, 타는 것을 돕고 호흡에 필요함","탄산음료 — 이산화 탄소, 물에 넣으면 톡 쏘는 맛","소화기 — 이산화 탄소, 다른 물질이 타는 것을 막음"],"title":"하늘반 일지 ⑥ 기체 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#22','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C30',3,'mc','auto','하늘반 일지 ⑧에서 과학자들이 비행선에 주목한 까닭은 무엇인가요?',ARRAY['SC4-2-u3-X45','SC4-2-u3-X43','SC4-2-u3-X44']::text[],false,'{"seq":22,"concept":"SC4-2-u3-C30","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑧에서 과학자들이 비행선에 주목한 까닭은 무엇인가요?","options":[{"t":"비행기 엔진에서 나오는 많은 양의 이산화 탄소 문제를 보완하기 위해서","correct":true},{"t":"비행선이 이산화 탄소를 더 많이 뿜기 때문에","mis":"SC4-2-u3-X45"},{"t":"비행선은 엔진을 더 많이 쓰기 때문에","mis":"SC4-2-u3-X43"},{"t":"비행선은 긴 활주로가 꼭 필요하기 때문에","mis":"SC4-2-u3-X44"}],"explanation":["첫 줄을 읽어요.","비행기의 문제예요.","첫 번째예요."],"asset":{"type":"passage","lines":["비행기 — 엔진에서 많은 양의 이산화 탄소가 나온다.","비행선 — 공기보다 가벼운 헬륨으로 떠오른다.","비행선 — 비행기에 비해 엔진을 적게 쓴다.","친구 가 — 「비행선은 엔진이 아예 없대.」"],"title":"하늘반 일지 ⑧ 비행선 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#23','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C19',4,'essay','teacher','하늘반 일지 ⑤의 ㉠~㉢에서 기체의 부피가 달라진 까닭을 각각 쓰고, 모습이 같아도 까닭이 다를 수 있다는 것을 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u3-C19","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑤의 ㉠~㉢에서 기체의 부피가 달라진 까닭을 각각 쓰고, 모습이 같아도 까닭이 다를 수 있다는 것을 설명하세요.","answer_guide":{"answer":"예: ㉠은 온도가 높아져 부피가 늘어났고, ㉡은 압력이 높아져 부피가 줄어들었으며, ㉢은 온도가 낮아져 부피가 줄어들었다. ㉡과 ㉢은 모두 부피가 줄어들었지만 하나는 압력, 하나는 온도 때문이므로 모습이 같아도 까닭은 다를 수 있다.","scoring_points":["㉠~㉢의 까닭을 모두 바르게 썼는가","줄어든 두 가지를 견주었는가","까닭이 다를 수 있음을 설명했는가"]},"explanation":["일지를 읽어요.","까닭을 하나씩 써요.","견주어 설명해요."],"asset":{"type":"passage","lines":["㉠ 땡볕 아래 둔 튜브가 팽팽해졌다.","㉡ 공기 안전 매트에 뛰어내리니 매트가 움푹 들어갔다.","㉢ 냉장고에 넣은 용기의 비닐 랩이 오목해졌다.","조사한 자료마다 출처를 적었다."],"title":"하늘반 일지 ⑤ 생활 속 부피 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#24','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C28',4,'mc','auto','친구가 「우리 장치는 특별한 기체를 따로 사서 넣어야 작동해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u3-X40','SC4-2-u3-X36','SC4-2-u3-X39']::text[],false,'{"seq":24,"concept":"SC4-2-u3-C28","difficulty":4,"kind":"mc","stem":"친구가 「우리 장치는 특별한 기체를 따로 사서 넣어야 작동해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「약병 안에 든 공기만으로도 온도에 따라 부피가 달라져서 시럽이 움직여.」","correct":true},{"t":"「맞아, 공기로는 움직이지 않아.」","mis":"SC4-2-u3-X40"},{"t":"「시럽이 스스로 움직이니 기체는 필요 없어.」","mis":"SC4-2-u3-X36"},{"t":"「꾸밈을 더하면 작동해.」","mis":"SC4-2-u3-X39"}],"explanation":["장치 안을 떠올려요.","공기가 들어 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u3_review_d#25','sci',4,2,'u3','','g4_2_sci_u3_review_d','unit_review','SC4-2-u3-C18',4,'essay','teacher','우리 주변에서 온도나 압력에 따라 기체의 부피가 달라지는 예를 두 가지 찾아 쓰고, 각각의 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u3-C18","difficulty":4,"kind":"essay","stem":"우리 주변에서 온도나 압력에 따라 기체의 부피가 달라지는 예를 두 가지 찾아 쓰고, 각각의 까닭을 쓰세요.","answer_guide":{"answer":"예: 땡볕 아래 둔 비치 볼이 팽팽해지는 것은 온도가 높아져 기체의 부피가 늘어났기 때문이다. 호핑볼에 앉으면 납작해지는 것은 압력이 높아져 기체의 부피가 줄어들었기 때문이다.","scoring_points":["예 두 가지를 썼는가","각각 온도인지 압력인지 썼는가","부피가 어떻게 달라졌는지 썼는가"]},"explanation":["주변을 떠올려요.","예를 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
